-- ============================================================
-- HỆ THỐNG TRẮC NGHIỆM QUẢN TRỊ HỌC - 9 CHƯƠNG / 360 CÂU
-- Có thể chạy lại an toàn. Dữ liệu câu hỏi được UPSERT theo (chapter_id, question_no).
-- ============================================================
create extension if not exists pgcrypto;

create table if not exists subjects(id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, created_at timestamptz default now());
create table if not exists chapters(id uuid primary key default gen_random_uuid(), subject_id uuid not null references subjects(id) on delete cascade, slug text unique not null, title text not null, sort_order int not null default 0, is_active boolean not null default true, created_at timestamptz default now());
create table if not exists questions(id uuid primary key default gen_random_uuid(), chapter_id uuid not null references chapters(id) on delete cascade, question_no int not null, section_label text, question_text text not null, option_a text not null, option_b text not null, option_c text not null, option_d text not null, correct_option text not null check(correct_option in('A','B','C','D')), explanation text, topic text, unique(chapter_id,question_no));
create table if not exists attempts(id uuid primary key default gen_random_uuid(), chapter_id uuid not null references chapters(id), full_name text not null, class_name text not null, identity_key text not null, browser_id text, attempt_number int not null, status text not null default 'active' check(status in('active','submitted')), monitoring_required boolean not null default false, started_at timestamptz not null default now(), submitted_at timestamptz, score int, total_questions int, percent numeric(5,2), active_session_token text, active_session_seen_at timestamptz, concurrent_detected boolean not null default false);
create table if not exists attempt_answers(attempt_id uuid not null references attempts(id) on delete cascade, question_id uuid not null references questions(id), selected_option text not null check(selected_option in('A','B','C','D')), is_correct boolean, updated_at timestamptz default now(), primary key(attempt_id,question_id));
create table if not exists monitor_events(id bigserial primary key, attempt_id uuid not null references attempts(id) on delete cascade, session_token text, event_type text not null, event_detail jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now());
create table if not exists teacher_profiles(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz default now());
create index if not exists attempts_identity_idx on attempts(identity_key,chapter_id,status);
create unique index if not exists attempts_one_active_idx on attempts(chapter_id,identity_key) where status='active';
create index if not exists monitor_events_attempt_idx on monitor_events(attempt_id,occurred_at);

alter table subjects enable row level security; alter table chapters enable row level security; alter table questions enable row level security; alter table attempts enable row level security; alter table attempt_answers enable row level security; alter table monitor_events enable row level security; alter table teacher_profiles enable row level security;
revoke all on subjects,chapters,questions,attempts,attempt_answers,monitor_events,teacher_profiles from anon,authenticated;

insert into subjects(slug,name) values('quan-tri-hoc','Quản trị học') on conflict(slug) do update set name=excluded.name;

with j as (select * from jsonb_to_recordset($chapters$[{"slug": "chuong-1", "title": "Chương 1. Tổng quan về quản trị", "sort_order": 1}, {"slug": "chuong-2", "title": "Chương 2. Sự tiến triển của tư tưởng quản trị", "sort_order": 2}, {"slug": "chuong-3", "title": "Chương 3. Môi trường của tổ chức", "sort_order": 3}, {"slug": "chuong-4", "title": "Chương 4. Văn hóa với quản trị của tổ chức", "sort_order": 4}, {"slug": "chuong-5", "title": "Chương 5. Quyết định quản trị", "sort_order": 5}, {"slug": "chuong-6", "title": "Chương 6. Chức năng hoạch định", "sort_order": 6}, {"slug": "chuong-7", "title": "Chương 7. Chức năng tổ chức", "sort_order": 7}, {"slug": "chuong-8", "title": "Chương 8. Chức năng điều khiển", "sort_order": 8}, {"slug": "chuong-9", "title": "Chương 9. Chức năng kiểm tra", "sort_order": 9}]$chapters$::jsonb) as x(slug text,title text,sort_order int))
insert into chapters(subject_id,slug,title,sort_order,is_active)
select s.id,j.slug,j.title,j.sort_order,true from j cross join subjects s where s.slug='quan-tri-hoc'
on conflict(slug) do update set title=excluded.title,sort_order=excluded.sort_order,is_active=true;

with j as (select * from jsonb_to_recordset($questions$[{"chapter_slug": "chuong-1", "question_no": 1, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Năm sinh viên cùng thành lập một nhóm để tổ chức chương trình quyên góp sách cho trẻ em vùng khó khăn. Nhóm xác định mục tiêu, phân chia người phụ trách truyền thông, vận chuyển, tài chính và thường xuyên phối hợp với nhau.\n\nTrường hợp này thể hiện rõ nhất đặc điểm nào của một tổ chức?", "option_a": "Mọi thành viên phải có cùng chuyên môn", "option_b": "Có nhiều người phối hợp hoạt động nhằm đạt mục tiêu chung", "option_c": "Bắt buộc phải tạo ra lợi nhuận", "option_d": "Phải có cơ cấu nhiều cấp quản lý", "correct_option": "B", "explanation": "Một tổ chức không nhất thiết phải kinh doanh hay có nhiều cấp quản lý. Điểm quan trọng là có nhiều người cùng phối hợp hoạt động để đạt một hoặc một số mục tiêu chung.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 2, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Một cửa hàng có 12 nhân viên nhưng chủ cửa hàng không phân công rõ trách nhiệm. Khi khách phản ánh sản phẩm giao sai, nhân viên bán hàng cho rằng lỗi của kho, còn kho cho rằng trách nhiệm thuộc bộ phận giao hàng.\n\nĐiều cửa hàng đang thiếu rõ nhất là:", "option_a": "Nhiều nhân viên hơn", "option_b": "Mục tiêu lợi nhuận", "option_c": "Sự phối hợp và phân định công việc trong tổ chức", "option_d": "Một văn phòng lớn hơn", "correct_option": "C", "explanation": "Một tổ chức muốn hoạt động hiệu quả phải có sự phân công và phối hợp. Khi nhiệm vụ và trách nhiệm không rõ, công việc dễ bị bỏ sót hoặc các thành viên đổ trách nhiệm cho nhau.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 3, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Giám đốc một nhà hàng đặt mục tiêu giảm thời gian khách chờ món từ 25 phút xuống còn 15 phút trong ba tháng tới và yêu cầu các bộ phận xây dựng phương án thực hiện.\n\nHoạt động của giám đốc thể hiện rõ nhất chức năng nào?", "option_a": "Hoạch định", "option_b": "Tổ chức", "option_c": "Kiểm tra", "option_d": "Điều khiển", "correct_option": "A", "explanation": "Giám đốc đang xác định kết quả cần đạt trong tương lai và định hướng cách thực hiện. Đây là nội dung cốt lõi của chức năng hoạch định.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 4, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Sau khi có kế hoạch mở thêm chi nhánh, giám đốc quyết định thành lập bộ phận bán hàng, tuyển trưởng chi nhánh, phân công nhiệm vụ và xác định ai báo cáo cho ai.\n\nGiám đốc đang thực hiện chủ yếu chức năng:", "option_a": "Kiểm tra", "option_b": "Hoạch định", "option_c": "Điều khiển", "option_d": "Tổ chức", "correct_option": "D", "explanation": "Việc phân chia công việc, bố trí con người, xác định trách nhiệm và quan hệ báo cáo thuộc chức năng tổ chức.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 5, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Trưởng cửa hàng thường xuyên trao đổi với nhân viên, khuyến khích họ hoàn thành mục tiêu, giải quyết mâu thuẫn và động viên khi doanh số giảm.\n\nHoạt động này thuộc chủ yếu chức năng:", "option_a": "Hoạch định", "option_b": "Điều khiển/lãnh đạo", "option_c": "Tổ chức", "option_d": "Kiểm tra", "correct_option": "B", "explanation": "Nhà quản trị đang tác động đến con người, động viên và hướng dẫn nhân viên để thực hiện mục tiêu. Đây là chức năng điều khiển/lãnh đạo.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 6, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Cuối tháng, quản lý so sánh doanh thu thực tế 850 triệu đồng với mục tiêu 1 tỷ đồng, xác định nguyên nhân thiếu hụt và yêu cầu điều chỉnh kế hoạch bán hàng.\n\nĐây là hoạt động:", "option_a": "Tổ chức", "option_b": "Điều khiển", "option_c": "Kiểm tra", "option_d": "Tuyển dụng", "correct_option": "C", "explanation": "Nhà quản trị đang đo lường kết quả, so sánh với mục tiêu, xác định sai lệch và đưa ra điều chỉnh. Đây là chức năng kiểm tra.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 7, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Tổng giám đốc một công ty quyết định trong 5 năm tới doanh nghiệp sẽ mở rộng từ thị trường Việt Nam sang ba quốc gia Đông Nam Á.\n\nNgười đưa ra quyết định này thuộc chủ yếu cấp quản trị nào?", "option_a": "Quản trị cấp cao", "option_b": "Quản trị cấp cơ sở", "option_c": "Nhân viên tác nghiệp", "option_d": "Tổ trưởng sản xuất", "correct_option": "A", "explanation": "Những quyết định liên quan đến định hướng dài hạn và toàn bộ tổ chức thường thuộc trách nhiệm của nhà quản trị cấp cao.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 8, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Trưởng phòng marketing nhận chiến lược mở rộng thị trường từ ban giám đốc và chuyển nó thành kế hoạch quảng cáo, ngân sách và chỉ tiêu cho đội marketing.\n\nTrưởng phòng marketing thuộc chủ yếu:", "option_a": "Quản trị cấp cao", "option_b": "Nhân viên không quản lý", "option_c": "Cấp tác nghiệp trực tiếp", "option_d": "Quản trị cấp trung", "correct_option": "D", "explanation": "Nhà quản trị cấp trung thường chuyển định hướng của cấp cao thành kế hoạch và chương trình cụ thể cho bộ phận mình phụ trách.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 9, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Một tổ trưởng sản xuất trực tiếp phân công công việc cho 15 công nhân, theo dõi sản lượng từng ca và xử lý những vấn đề phát sinh hằng ngày.\n\nTổ trưởng này thuộc:", "option_a": "Quản trị cấp cao", "option_b": "Quản trị cấp trung", "option_c": "Quản trị cấp cơ sở", "option_d": "Không phải nhà quản trị", "correct_option": "C", "explanation": "Nhà quản trị cấp cơ sở trực tiếp quản lý những người thực hiện công việc tác nghiệp và chịu trách nhiệm đối với hoạt động hằng ngày.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 10, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Lan là chuyên viên thiết kế rất giỏi nhưng không quản lý bất kỳ nhân viên nào. Minh là trưởng nhóm, chịu trách nhiệm phân công và phối hợp công việc của sáu người.\n\nAi phù hợp với khái niệm nhà quản trị hơn?", "option_a": "Chỉ Lan", "option_b": "Minh", "option_c": "Cả hai chắc chắn đều là nhà quản trị", "option_d": "Không ai", "correct_option": "B", "explanation": "Nhà quản trị là người chịu trách nhiệm phối hợp và hướng dẫn công việc của người khác để đạt mục tiêu. Chuyên môn giỏi không tự động làm một người trở thành nhà quản trị.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 11, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Một quản lý nhà máy giảm lượng nguyên liệu hao hụt từ 8% xuống 3% trong khi vẫn duy trì sản lượng theo kế hoạch.\n\nKết quả này phản ánh rõ nhất việc:", "option_a": "Sử dụng nguồn lực hiệu quả hơn", "option_b": "Giảm mục tiêu của tổ chức", "option_c": "Tăng số cấp quản trị", "option_d": "Không cần hoạch định", "correct_option": "A", "explanation": "Hiệu quả sử dụng nguồn lực thể hiện ở việc đạt kết quả với ít hao phí hơn. Nhà máy vẫn duy trì đầu ra nhưng sử dụng nguyên liệu tốt hơn.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 12, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Một đội bán hàng hoàn thành mục tiêu doanh thu 10 tỷ đồng nhưng phải chi phí quảng cáo gấp ba lần dự kiến.\n\nNhận định phù hợp nhất là:", "option_a": "Đội vừa hiệu quả vừa sử dụng nguồn lực tối ưu", "option_b": "Đội chắc chắn thất bại hoàn toàn", "option_c": "Chỉ cần đạt doanh thu nên chi phí không quan trọng", "option_d": "Đội đạt mục tiêu nhưng hiệu quả sử dụng nguồn lực cần được xem xét", "correct_option": "D", "explanation": "Đội đã đạt kết quả mong muốn, nhưng mức chi phí quá cao cho thấy cần xem xét tính hiệu quả trong sử dụng nguồn lực.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 13, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Một quản lý sử dụng dữ liệu bán hàng, báo cáo thị trường và mô hình dự báo trước khi lựa chọn phương án kinh doanh.\n\nĐiều này thể hiện quản trị có tính:", "option_a": "Cảm tính hoàn toàn", "option_b": "Ngẫu nhiên", "option_c": "Khoa học", "option_d": "Không cần kinh nghiệm", "correct_option": "C", "explanation": "Quản trị có tính khoa học vì nhà quản trị có thể sử dụng dữ liệu, nguyên tắc, phương pháp và công cụ phân tích để hỗ trợ quyết định.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 14, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Hai cửa hàng có cùng dữ liệu và quy trình, nhưng quản lý cửa hàng A biết lựa chọn cách giao tiếp phù hợp với từng nhân viên nên đội ngũ hợp tác tốt hơn.\n\nĐiều này cho thấy quản trị còn mang tính:", "option_a": "Máy móc", "option_b": "Nghệ thuật", "option_c": "Hoàn toàn định lượng", "option_d": "Không cần kiến thức", "correct_option": "B", "explanation": "Quản trị còn mang tính nghệ thuật vì nhà quản trị phải vận dụng kiến thức linh hoạt trong những tình huống cụ thể, đặc biệt khi làm việc với con người.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 15, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Giám đốc được mời đại diện công ty tham dự lễ ký kết với một trường đại học và thực hiện nghi thức ký biên bản hợp tác.\n\nTrong tình huống này, giám đốc đang thực hiện chủ yếu vai trò:", "option_a": "Người phân bổ nguồn lực", "option_b": "Người giải quyết xáo trộn", "option_c": "Người thương lượng", "option_d": "Người đại diện", "correct_option": "D", "explanation": "Khi thực hiện các nhiệm vụ mang tính nghi thức và đại diện chính thức cho tổ chức, nhà quản trị đảm nhận vai trò người đại diện.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 16, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Trưởng phòng dành thời gian hướng dẫn nhân viên mới, tạo động lực cho nhóm và đánh giá kết quả công việc của từng người.\n\nVai trò nổi bật nhất là:", "option_a": "Người lãnh đạo", "option_b": "Người phát ngôn", "option_c": "Người liên lạc", "option_d": "Người thương lượng", "correct_option": "A", "explanation": "Hướng dẫn, động viên và phát triển nhân viên là những hoạt động điển hình của vai trò lãnh đạo.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 17, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Giám đốc kinh doanh thường xuyên đọc báo cáo thị trường, theo dõi đối thủ và tiếp nhận thông tin từ khách hàng để hiểu các thay đổi bên ngoài.\n\nÔng đang thực hiện vai trò chủ yếu nào?", "option_a": "Người đại diện", "option_b": "Người thương lượng", "option_c": "Người thu thập/giám sát thông tin", "option_d": "Người phân bổ nguồn lực", "correct_option": "C", "explanation": "Khi chủ động tìm kiếm và tiếp nhận thông tin để hiểu tổ chức và môi trường, nhà quản trị thực hiện vai trò giám sát thông tin.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 18, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Sau cuộc họp với ban giám đốc, trưởng phòng quay lại giải thích cho nhân viên về chính sách mới và những thay đổi cần thực hiện.\n\nVai trò của trưởng phòng lúc này là:", "option_a": "Người đại diện", "option_b": "Người truyền đạt thông tin", "option_c": "Người thương lượng", "option_d": "Người giải quyết xáo trộn", "correct_option": "B", "explanation": "Nhà quản trị đang chuyển thông tin từ cấp hoặc bộ phận khác đến các thành viên trong đơn vị mình.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 19, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Giám đốc được phỏng vấn trên truyền hình và trình bày chính thức về kế hoạch phát triển sản phẩm mới của công ty.\n\nÔng đang thực hiện vai trò:", "option_a": "Người lãnh đạo", "option_b": "Người phân bổ nguồn lực", "option_c": "Người liên lạc", "option_d": "Người phát ngôn", "correct_option": "D", "explanation": "Khi đại diện tổ chức cung cấp thông tin ra bên ngoài, nhà quản trị thực hiện vai trò người phát ngôn.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 20, "section_label": "PHẦN I. 20 CÂU THỰC TẾ MỨC DỄ", "question_text": "Một trưởng phòng thường xuyên kết nối với các phòng ban khác, nhà cung cấp và đối tác để duy trì quan hệ cần thiết cho công việc.\n\nVai trò nổi bật nhất là:", "option_a": "Người liên lạc", "option_b": "Người giải quyết xáo trộn", "option_c": "Người phân bổ nguồn lực", "option_d": "Người phát ngôn", "correct_option": "A", "explanation": "Vai trò liên lạc thể hiện việc nhà quản trị xây dựng và duy trì mạng lưới quan hệ trong và ngoài đơn vị.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 21, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Một công ty đạt đúng mục tiêu sản xuất 50.000 sản phẩm nhưng phải sử dụng thêm 30% lao động và 25% nguyên liệu so với kế hoạch.\n\nNhận định phù hợp nhất là:", "option_a": "Công ty không đạt mục tiêu nên không có hiệu lực", "option_b": "Công ty vừa có hiệu lực vừa có hiệu quả cao", "option_c": "Công ty đạt mục tiêu nhưng hiệu quả sử dụng nguồn lực chưa tốt", "option_d": "Chỉ cần xem xét số lượng sản phẩm, không cần quan tâm đầu vào", "correct_option": "C", "explanation": "Công ty đã đạt mục tiêu đầu ra nên thể hiện tính hiệu lực ở kết quả, nhưng chi phí nguồn lực vượt nhiều so với kế hoạch cho thấy hiệu quả sử dụng nguồn lực thấp.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 22, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Doanh số công ty giảm mạnh. Tổng giám đốc quyết định thay đổi chiến lược giá; trưởng phòng kinh doanh xây dựng chương trình bán hàng mới; tổ trưởng bán hàng phân công chỉ tiêu hằng ngày cho từng nhân viên.\n\nNhận định phù hợp nhất là:", "option_a": "Ba cấp quản trị đang xử lý cùng vấn đề nhưng ở phạm vi và mức độ khác nhau", "option_b": "Chỉ tổng giám đốc đang làm công việc quản trị", "option_c": "Tổ trưởng đang thực hiện nhiệm vụ của quản trị cấp cao", "option_d": "Trưởng phòng và tổ trưởng có vai trò giống hệt nhau", "correct_option": "A", "explanation": "Cùng một vấn đề có thể được xử lý ở nhiều cấp. Cấp cao tập trung định hướng tổng thể, cấp trung chuyển thành kế hoạch bộ phận, còn cấp cơ sở tổ chức hoạt động cụ thể.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 23, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Một giám đốc phát hiện quy trình hiện tại quá chậm nên chủ động đề xuất hệ thống bán hàng trực tuyến mới và tổ chức thử nghiệm tại hai chi nhánh.\n\nVai trò nổi bật nhất của giám đốc là:", "option_a": "Người đại diện", "option_b": "Người truyền đạt thông tin", "option_c": "Người phát ngôn", "option_d": "Người khởi xướng/nhà doanh nhân", "correct_option": "D", "explanation": "Nhà quản trị đang chủ động tìm kiếm cơ hội cải tiến và khởi xướng thay đổi, phù hợp với vai trò doanh nhân trong nhóm vai trò quyết định.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 24, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Hệ thống máy chủ của doanh nghiệp bất ngờ ngừng hoạt động trong giờ cao điểm. Giám đốc CNTT nhanh chóng điều nhân lực xử lý, ưu tiên khôi phục dịch vụ quan trọng và làm việc với nhà cung cấp.\n\nVai trò nổi bật nhất là:", "option_a": "Người phát ngôn", "option_b": "Người giải quyết xáo trộn", "option_c": "Người đại diện", "option_d": "Người liên lạc", "correct_option": "B", "explanation": "Khi xử lý một sự cố bất ngờ nghiêm trọng đe dọa hoạt động của tổ chức, nhà quản trị thực hiện vai trò giải quyết xáo trộn.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 25, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Công ty chỉ có ngân sách 5 tỷ đồng nhưng ba phòng cùng đề nghị đầu tư. Tổng giám đốc phải quyết định phòng nào được bao nhiêu và dự án nào được ưu tiên.\n\nÔng đang thực hiện vai trò:", "option_a": "Người phát ngôn", "option_b": "Người giám sát thông tin", "option_c": "Người phân bổ nguồn lực", "option_d": "Người đại diện", "correct_option": "C", "explanation": "Quyết định phân chia tiền, con người, thời gian hoặc thiết bị giữa các hoạt động là vai trò phân bổ nguồn lực.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 26, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Giám đốc nhân sự và đại diện người lao động thảo luận nhiều vòng để thống nhất chính sách tiền thưởng mới.\n\nVai trò nổi bật nhất của giám đốc nhân sự là:", "option_a": "Người đại diện", "option_b": "Người giám sát", "option_c": "Người khởi xướng", "option_d": "Người thương lượng", "correct_option": "D", "explanation": "Khi đại diện cho tổ chức trao đổi để đạt thỏa thuận với một bên khác, nhà quản trị đang thực hiện vai trò thương lượng.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 27, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Một quản lý rất giỏi chuyên môn và thường tự làm những công việc khó thay nhân viên. Vì vậy anh gần như không còn thời gian phân công, phối hợp, theo dõi và hỗ trợ đội nhóm.\n\nVấn đề quản trị cốt lõi là:", "option_a": "Anh chưa chuyển đầy đủ từ vai trò chuyên viên sang vai trò nhà quản trị", "option_b": "Nhà quản trị nên tự làm càng nhiều việc chuyên môn càng tốt", "option_c": "Anh đang phân quyền quá nhiều", "option_d": "Nhân viên không cần được phối hợp", "correct_option": "A", "explanation": "Nhà quản trị không được đánh giá chủ yếu bởi số công việc chuyên môn tự mình hoàn thành mà bởi khả năng phối hợp công việc của người khác để đạt mục tiêu.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 28, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Một nhà quản trị có đầy đủ kế hoạch, cơ cấu và KPI nhưng nhân viên không hiểu vì sao phải thực hiện thay đổi và tỏ ra thiếu động lực.\n\nChức năng nào cần được nhà quản trị chú trọng bổ sung?", "option_a": "Chỉ kiểm tra", "option_b": "Điều khiển/lãnh đạo", "option_c": "Chỉ tổ chức", "option_d": "Chỉ hoạch định", "correct_option": "B", "explanation": "Kế hoạch và cơ cấu chưa đủ. Nhà quản trị còn phải truyền đạt, tạo động lực và tác động đến con người để kế hoạch được thực hiện.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 29, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Một doanh nghiệp liên tục hoàn thành công việc hằng ngày rất tốt nhưng trong ba năm không nhận ra thị trường đang chuyển sang công nghệ mới. Khi phản ứng thì đã mất phần lớn khách hàng.\n\nNhóm quản trị nào chịu trách nhiệm lớn nhất trong việc bỏ sót định hướng dài hạn?", "option_a": "Chỉ nhân viên tác nghiệp", "option_b": "Chỉ tổ trưởng", "option_c": "Quản trị cấp cao", "option_d": "Khách hàng", "correct_option": "C", "explanation": "Quản trị cấp cao chịu trách nhiệm chủ yếu về định hướng tổng thể, chiến lược dài hạn và sự thích nghi của toàn tổ chức với môi trường.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 30, "section_label": "PHẦN II. 10 CÂU THỰC TẾ MỨC KHÁ", "question_text": "Giám đốc bệnh viện phải đồng thời bảo đảm chất lượng chăm sóc bệnh nhân và kiểm soát chi phí. Một phương án tiết kiệm chi phí 20% nhưng làm giảm nghiêm trọng chất lượng phục vụ.\n\nNhận định phù hợp nhất là:", "option_a": "Cứ giảm chi phí là quản trị hiệu quả", "option_b": "Chỉ chất lượng mới quan trọng", "option_c": "Nhà quản trị không cần quan tâm nguồn lực", "option_d": "Quản trị phải cân bằng giữa đạt mục tiêu và sử dụng nguồn lực hợp lý", "correct_option": "D", "explanation": "Quản trị không chỉ hướng tới tiết kiệm nguồn lực mà phải bảo đảm tổ chức đạt được mục tiêu quan trọng. Cắt chi phí nhưng phá hỏng chất lượng cốt lõi không phải là kết quả quản trị tốt.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 31, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Công ty A hoàn thành 100% mục tiêu doanh thu nhưng chi phí cao hơn kế hoạch 40%. Công ty B chỉ đạt 92% mục tiêu doanh thu nhưng sử dụng ít hơn 25% nguồn lực và vẫn duy trì chất lượng. Ban lãnh đạo muốn kết luận ngay công ty nào được quản trị “tốt hơn”.\n\nCách đánh giá phù hợp nhất là:", "option_a": "B chắc chắn tốt hơn vì chi phí thấp", "option_b": "Chưa thể kết luận chỉ từ một chỉ số; cần đánh giá đồng thời mức độ đạt mục tiêu và hiệu quả sử dụng nguồn lực", "option_c": "A chắc chắn tốt hơn vì đạt đủ doanh thu", "option_d": "Cả hai đều quản trị kém", "correct_option": "B", "explanation": "Quản trị phải xem xét cả kết quả đạt được và nguồn lực sử dụng. Chỉ dựa vào doanh thu hoặc chi phí riêng lẻ đều có thể tạo kết luận sai.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 32, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một CEO thường xuyên quyết định cả lịch trực, duyệt từng đơn hàng nhỏ và xử lý lỗi hằng ngày. Trong khi đó, không ai dành đủ thời gian nghiên cứu thị trường mới và chiến lược dài hạn.\n\nVấn đề phù hợp nhất là:", "option_a": "CEO đang thực hiện quá nhiều vai trò thông tin", "option_b": "Công ty có quá nhiều hoạch định", "option_c": "Nhân viên cấp dưới đang thực hiện quá nhiều chiến lược", "option_d": "Cấp quản trị cao đang sa vào công việc tác nghiệp thay vì tập trung đúng trọng tâm của mình", "correct_option": "D", "explanation": "Nhà quản trị cấp cao vẫn có thể tham gia các vấn đề tác nghiệp khi cần, nhưng nếu thường xuyên bị cuốn vào công việc chi tiết thì những trách nhiệm chiến lược quan trọng có nguy cơ bị bỏ quên.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 33, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một doanh nghiệp có bản chiến lược rất tốt. Ban giám đốc xác định rõ mục tiêu nhưng không phân công trách nhiệm, không tạo động lực cho nhân viên và cũng không đo lường kết quả.\n\nNguyên nhân hợp lý nhất khiến chiến lược có nguy cơ thất bại là:", "option_a": "Các chức năng quản trị phải liên kết với nhau; hoạch định tốt nhưng thiếu tổ chức, điều khiển và kiểm tra vẫn khó tạo kết quả", "option_b": "Chỉ cần hoạch định tốt là đủ", "option_c": "Công ty cần bỏ toàn bộ mục tiêu", "option_d": "Nhà quản trị cấp cao không cần quan tâm thực thi", "correct_option": "A", "explanation": "Các chức năng quản trị không tồn tại biệt lập. Hoạch định tạo phương hướng nhưng phải được hỗ trợ bằng tổ chức nguồn lực, lãnh đạo con người và kiểm tra kết quả.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 34, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một trưởng phòng có thành tích cá nhân rất cao vì thường xuyên tự xử lý những việc quan trọng. Tuy nhiên, khi trưởng phòng nghỉ hai tuần, bộ phận gần như đình trệ vì nhân viên không biết cách tự giải quyết công việc.\n\nĐánh giá phù hợp nhất là:", "option_a": "Trưởng phòng quản trị rất tốt vì tự làm được nhiều việc", "option_b": "Bộ phận chỉ cần tuyển thêm nhân viên", "option_c": "Thành tích chuyên môn cá nhân cao chưa đủ chứng minh hiệu quả quản trị nếu đội ngũ quá phụ thuộc vào một người", "option_d": "Nhà quản trị không cần phát triển nhân viên", "correct_option": "C", "explanation": "Hiệu quả của nhà quản trị phải thể hiện ở khả năng làm cho hệ thống và đội ngũ hoạt động, không chỉ ở năng lực cá nhân. Sự phụ thuộc quá mức vào trưởng phòng cho thấy chức năng quản trị chưa được thực hiện đầy đủ.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 35, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một công ty giảm thời gian sản xuất 25% sau khi áp dụng quy trình mới. Tuy nhiên tỷ lệ sản phẩm lỗi tăng từ 1% lên 12%, khiến nhiều khách hàng trả hàng.\n\nKết luận quản trị phù hợp nhất là:", "option_a": "Quy trình mới hoàn toàn thành công vì sản xuất nhanh hơn", "option_b": "Không thể xem tốc độ là hiệu quả nếu sự cải thiện một chỉ tiêu làm tổn hại mục tiêu chất lượng của tổ chức", "option_c": "Công ty chỉ cần tăng sản lượng thêm", "option_d": "Chất lượng không liên quan đến quản trị", "correct_option": "B", "explanation": "Hiệu quả quản trị cần được đánh giá trong mối quan hệ với mục tiêu tổng thể. Tối ưu một bộ phận nhưng làm giảm chất lượng và ảnh hưởng khách hàng có thể khiến kết quả chung xấu đi.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 36, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Trong một cuộc họp, giám đốc đầu tiên nghe báo cáo từ nhiều nguồn để hiểu tình hình, sau đó thông báo kết luận cho nhân viên và cuối cùng đàm phán với nhà cung cấp để giải quyết vấn đề.\n\nNhận định nào đúng nhất?", "option_a": "Một nhà quản trị có thể thực hiện nhiều vai trò khác nhau liên tiếp tùy yêu cầu của tình huống", "option_b": "Nhà quản trị chỉ được thực hiện một vai trò trong mỗi ngày", "option_c": "Vai trò thông tin không liên quan vai trò quyết định", "option_d": "Chỉ cấp cao mới có vai trò quản trị", "correct_option": "A", "explanation": "Các vai trò quản trị không tách biệt cứng nhắc. Trong thực tế, nhà quản trị thường chuyển liên tục giữa vai trò thông tin, quan hệ và quyết định.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 37, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một công ty có ba cấp quản trị. Ban giám đốc xây chiến lược rất rõ, tổ trưởng thực hiện tốt công việc hằng ngày, nhưng các phòng ban thường nhận mục tiêu không nhất quán và nguồn lực phân bổ chậm.\n\nVị trí nào nên được xem xét đầu tiên?", "option_a": "Khách hàng", "option_b": "Chỉ nhân viên sản xuất", "option_c": "Chỉ hội đồng quản trị", "option_d": "Cấp quản trị trung gian và khả năng chuyển hóa chiến lược thành kế hoạch bộ phận", "correct_option": "D", "explanation": "Cấp trung đóng vai trò cầu nối quan trọng giữa chiến lược của cấp cao và hoạt động của cấp cơ sở. Sự đứt gãy ở cấp này có thể làm chiến lược không được chuyển thành hành động nhất quán.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 38, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một doanh nghiệp đạt lợi nhuận cao trong năm nay vì giảm mạnh ngân sách bảo trì máy móc. Sáu tháng sau, máy liên tục hỏng, năng suất giảm và chi phí sửa chữa tăng mạnh.\n\nBài học quản trị phù hợp nhất là:", "option_a": "Lợi nhuận ngắn hạn luôn phản ánh quản trị tốt", "option_b": "Chỉ cần tăng chức năng kiểm tra", "option_c": "Nhà quản trị phải đánh giá quyết định trong mối quan hệ với mục tiêu tổng thể và hậu quả dài hạn, không chỉ kết quả trước mắt", "option_d": "Bảo trì không phải nguồn lực của tổ chức", "correct_option": "C", "explanation": "Quản trị hướng tới việc đạt mục tiêu một cách bền vững và sử dụng nguồn lực hợp lý. Một kết quả ngắn hạn tích cực có thể che giấu những hậu quả bất lợi trong tương lai.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 39, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một trưởng phòng nhận được báo cáo cho thấy kế hoạch đang thất bại nhưng không chuyển thông tin lên giám đốc vì lo bị đánh giá kém. Giám đốc vì vậy tiếp tục phân bổ nguồn lực theo kế hoạch cũ.\n\nPhân tích phù hợp nhất là:", "option_a": "Vấn đề chỉ nằm ở chức năng hoạch định", "option_b": "Việc thực hiện không tốt vai trò thông tin của nhà quản trị có thể làm giảm chất lượng của các quyết định quản trị khác", "option_c": "Thông tin không quan trọng đối với quản trị", "option_d": "Chỉ nhà quản trị cấp cao mới cần truyền đạt thông tin", "correct_option": "B", "explanation": "Các vai trò quản trị có quan hệ với nhau. Khi thông tin quan trọng không được thu thập hoặc truyền đạt đúng, hoạch định, phân bổ nguồn lực và kiểm tra đều có thể bị ảnh hưởng.", "topic": null}, {"chapter_slug": "chuong-1", "question_no": 40, "section_label": "PHẦN III. 10 CÂU THỰC TẾ MỨC KHÓ – SUY LUẬN", "question_text": "Một startup từ 10 người tăng lên 300 người trong hai năm. Người sáng lập vẫn muốn trực tiếp quyết định mọi việc như khi công ty còn nhỏ. Quyết định chậm, trưởng bộ phận không chủ động và nhân viên liên tục chờ CEO.\n\nCách nhìn quản trị phù hợp nhất là:", "option_a": "Khi tổ chức thay đổi về quy mô và độ phức tạp, cách thực hiện các chức năng và vai trò quản trị cũng phải thay đổi phù hợp", "option_b": "CEO nên tiếp tục quyết định mọi việc vì người sáng lập hiểu công ty nhất", "option_c": "Chỉ cần tuyển thêm nhân viên, không cần thay đổi cách quản trị", "option_d": "Công ty càng lớn càng không cần nhà quản trị cấp trung", "correct_option": "A", "explanation": "Quản trị diễn ra trong bối cảnh cụ thể. Khi tổ chức lớn hơn, nhà quản trị phải điều chỉnh cách phân công, phối hợp, giao trách nhiệm và sử dụng các cấp quản trị. Cách quản trị phù hợp với tổ chức 10 người chưa chắc còn phù hợp với tổ chức 300 người.", "topic": null}, {"chapter_slug": "chuong-2", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Nhân tố quan trọng thúc đẩy sự hình thành các lý thuyết quản trị vào cuối thế kỷ XIX và đầu thế kỷ XX là:", "option_a": "Sự phát triển của mạng xã hội", "option_b": "Sự phát triển của sản xuất công nghiệp quy mô lớn", "option_c": "Sự suy giảm dân số lao động", "option_d": "Sự phát triển của thương mại điện tử", "correct_option": "B", "explanation": "Cách mạng công nghiệp làm xuất hiện các nhà máy lớn, lực lượng lao động đông, sản xuất hàng loạt và sự phân công lao động ngày càng phức tạp. Khi quy mô tổ chức tăng, nhà quản trị phải giải quyết các vấn đề về phân công, năng suất, quyền hạn, phối hợp và kiểm soát. Đây là một trong những nguyên nhân trực tiếp thúc đẩy sự hình thành khoa học quản trị.", "topic": "Mục 1.2. Tác động của Cách mạng công nghiệp."}, {"chapter_slug": "chuong-2", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Tư tưởng về phân công lao động được Adam Smith trình bày nổi bật trong tác phẩm nào?", "option_a": "The Practice of Management", "option_b": "The Human Side of Enterprise", "option_c": "The Wealth of Nations", "option_d": "The Principles of Scientific Management", "correct_option": "C", "explanation": "Adam Smith trình bày vai trò của phân công lao động trong tác phẩm *The Wealth of Nations* năm 1776. Ông cho rằng chuyên môn hóa giúp tăng năng suất vì người lao động thành thạo hơn, giảm thời gian chuyển đổi công việc và tạo điều kiện sử dụng công cụ chuyên dụng.", "topic": "Mục 1.3. Phân công lao động của Adam Smith."}, {"chapter_slug": "chuong-2", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Ai được xem là người đặt nền móng quan trọng cho quản trị khoa học?", "option_a": "Henri Fayol", "option_b": "Frederick W. Taylor", "option_c": "Max Weber", "option_d": "Elton Mayo", "correct_option": "B", "explanation": "Frederick Winslow Taylor là người hệ thống hóa quản trị khoa học và trình bày các nguyên tắc cơ bản trong tác phẩm *The Principles of Scientific Management* năm 1911. Ông tập trung vào việc nghiên cứu công việc, tiêu chuẩn hóa và nâng cao năng suất.", "topic": "Mục 2.2.1. Khái niệm quản trị khoa học."}, {"chapter_slug": "chuong-2", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Tác phẩm *The Principles of Scientific Management* gắn với tác giả nào?", "option_a": "Frederick W. Taylor", "option_b": "Peter Drucker", "option_c": "Abraham Maslow", "option_d": "W. Edwards Deming", "correct_option": "A", "explanation": "Tác phẩm này được Frederick W. Taylor xuất bản năm 1911 và được xem là một công trình tiêu biểu của trường phái quản trị khoa học.", "topic": "Mục 2.2.1. Khái niệm quản trị khoa học."}, {"chapter_slug": "chuong-2", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Nội dung nào sau đây thuộc một trong bốn nguyên tắc quản trị khoa học của Taylor?", "option_a": "Loại bỏ hoàn toàn hệ thống cấp bậc", "option_b": "Lựa chọn và đào tạo người lao động một cách khoa học", "option_c": "Xóa bỏ việc phân công lao động", "option_d": "Không cần tiêu chuẩn hóa công việc", "correct_option": "B", "explanation": "Taylor cho rằng người lao động cần được lựa chọn, đào tạo và phát triển một cách khoa học để phù hợp với yêu cầu của công việc. Đây là một trong bốn nguyên tắc cốt lõi của quản trị khoa học.\n\nCác đáp án A, C và D đều không phù hợp vì Taylor nhấn mạnh chuyên môn hóa, tiêu chuẩn hóa và tổ chức công việc có hệ thống.", "topic": "Mục 2.2.2. Bốn nguyên tắc quản trị khoa học của Taylor."}, {"chapter_slug": "chuong-2", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Ai là đại diện tiêu biểu của quản trị hành chính?", "option_a": "Elton Mayo", "option_b": "Max Weber", "option_c": "Henri Fayol", "option_d": "Peter Senge", "correct_option": "C", "explanation": "Henri Fayol là đại diện tiêu biểu của quản trị hành chính. Ông tập trung nghiên cứu hoạt động của nhà quản trị và toàn bộ tổ chức, khác với Taylor chủ yếu tập trung vào công việc ở cấp tác nghiệp.", "topic": "Mục 2.3.1. Khái niệm quản trị hành chính."}, {"chapter_slug": "chuong-2", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Nguyên tắc “một nhân viên nên nhận mệnh lệnh trực tiếp từ một cấp trên” của Fayol được gọi là:", "option_a": "Unity of Direction", "option_b": "Unity of Command", "option_c": "Scalar Chain", "option_d": "Division of Work", "correct_option": "B", "explanation": "Unity of Command – thống nhất chỉ huy có nghĩa là một nhân viên nên nhận mệnh lệnh trực tiếp từ một cấp trên nhằm hạn chế xung đột trong chỉ đạo và trách nhiệm.\n\nUnity of Direction – thống nhất định hướng lại nhấn mạnh các hoạt động cùng mục tiêu phải được thực hiện theo một kế hoạch và một định hướng thống nhất.", "topic": "Mục 2.3.3. Mười bốn nguyên tắc quản trị của Henri Fayol."}, {"chapter_slug": "chuong-2", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Mô hình tổ chức quan liêu gắn liền với học giả nào?", "option_a": "Max Weber", "option_b": "Douglas McGregor", "option_c": "Peter Drucker", "option_d": "Adam Smith", "correct_option": "A", "explanation": "Max Weber phát triển mô hình tổ chức quan liêu dựa trên cơ cấu cấp bậc, các quy tắc chính thức, chuyên môn hóa, tính phi cá nhân và quyền lực hợp lý – pháp lý.", "topic": "Mục 2.4.1. Khái niệm tổ chức quan liêu."}, {"chapter_slug": "chuong-2", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quan điểm nào xem tổ chức là một chỉnh thể gồm nhiều bộ phận có quan hệ phụ thuộc lẫn nhau?", "option_a": "Quan điểm hệ thống", "option_b": "Quản trị khoa học", "option_c": "Quản trị hành chính", "option_d": "Thuyết X", "correct_option": "A", "explanation": "Quan điểm hệ thống xem tổ chức như một chỉnh thể gồm nhiều bộ phận có quan hệ tương tác và phụ thuộc lẫn nhau. Thay đổi ở một bộ phận có thể ảnh hưởng đến các bộ phận khác và toàn tổ chức.", "topic": "Mục 3.6. Quan điểm hệ thống."}, {"chapter_slug": "chuong-2", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quan điểm tình huống nhấn mạnh rằng:", "option_a": "Luôn có một phương pháp quản trị tốt nhất", "option_b": "Mọi doanh nghiệp cần sử dụng cùng một cơ cấu", "option_c": "Phương pháp quản trị hiệu quả phụ thuộc vào từng hoàn cảnh cụ thể", "option_d": "Mọi quyết định nên tập trung vào cấp cao nhất", "correct_option": "C", "explanation": "Quan điểm tình huống cho rằng không có một phương pháp quản trị phù hợp cho mọi tổ chức và mọi hoàn cảnh. Nhà quản trị phải căn cứ vào các yếu tố như môi trường, công nghệ, quy mô, chiến lược và đặc điểm nhân sự để lựa chọn phương pháp phù hợp.", "topic": "Mục 3.7. Quan điểm tình huống."}, {"chapter_slug": "chuong-2", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác biệt cơ bản giữa Taylor và Fayol là:", "option_a": "Taylor nghiên cứu văn hóa tổ chức, Fayol nghiên cứu động lực", "option_b": "Taylor tập trung vào hiệu quả công việc, Fayol tập trung vào hoạt động quản trị toàn tổ chức", "option_c": "Taylor nghiên cứu cơ cấu tổ chức, Fayol nghiên cứu tâm lý", "option_d": "Taylor nghiên cứu môi trường, Fayol nghiên cứu công nghệ", "correct_option": "B", "explanation": "Taylor tập trung chủ yếu vào cách tổ chức công việc để nâng cao năng suất của người lao động.\n\nFayol nghiên cứu hoạt động quản trị ở phạm vi rộng hơn như hoạch định, tổ chức, chỉ huy, phối hợp và kiểm soát.\n\nCó thể nhớ:\n\nTaylor → Công việc\n\nFayol → Quản trị toàn tổ chức", "topic": "Mục 2.2. Quản trị khoa học; Mục 2.3. Quản trị hành chính; Mục 2.5. Tổng hợp quan điểm quản trị cổ điển."}, {"chapter_slug": "chuong-2", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Đặc điểm nào sau đây không phù hợp với mô hình tổ chức quan liêu của Weber?", "option_a": "Phân công công việc rõ ràng", "option_b": "Quyền hạn được tổ chức theo cấp bậc", "option_c": "Tuyển dụng dựa chủ yếu trên quan hệ cá nhân", "option_d": "Hoạt động dựa trên quy tắc chính thức", "correct_option": "C", "explanation": "Weber nhấn mạnh tuyển dụng dựa trên năng lực và trình độ chuyên môn, chứ không dựa trên quan hệ cá nhân.\n\nCác đáp án A, B và D đều là những đặc điểm quan trọng của mô hình tổ chức quan liêu.", "topic": "Mục 2.4.2. Những đặc điểm chủ yếu của mô hình Weber."}, {"chapter_slug": "chuong-2", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một doanh nghiệp muốn giảm các thao tác thừa, chuẩn hóa thời gian và xây dựng phương pháp thực hiện công việc tối ưu. Quan điểm phù hợp nhất là:", "option_a": "Quản trị khoa học", "option_b": "Quan điểm hệ thống", "option_c": "Quản trị theo mục tiêu", "option_d": "Tổ chức học tập", "correct_option": "A", "explanation": "Quản trị khoa học của Taylor tập trung trực tiếp vào:\n\n- phân tích công việc;\n- nghiên cứu thao tác;\n- chuẩn hóa phương pháp;\n- xác định thời gian hợp lý;\n- nâng cao năng suất.\n\nVì vậy đây là cách tiếp cận phù hợp nhất với tình huống trên.", "topic": "Mục 2.2.1 và 2.2.2. Quản trị khoa học."}, {"chapter_slug": "chuong-2", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Đóng góp quan trọng của các nghiên cứu Hawthorne đối với tư tưởng quản trị là:", "option_a": "Chứng minh tiền lương không ảnh hưởng đến nhân viên", "option_b": "Chứng minh máy móc là yếu tố duy nhất quyết định năng suất", "option_c": "Làm nổi bật vai trò của các yếu tố tâm lý, xã hội và quan hệ nhóm", "option_d": "Loại bỏ vai trò của nhà quản trị", "correct_option": "C", "explanation": "Các nghiên cứu Hawthorne góp phần làm thay đổi cách nhìn về người lao động. Năng suất không chỉ phụ thuộc vào tiền lương và điều kiện vật chất mà còn chịu ảnh hưởng của:\n\n- thái độ;\n- nhóm;\n- quan hệ xã hội;\n- cách quản lý;\n- cảm giác được quan tâm.\n\nĐáp án A sai vì Hawthorne không kết luận tiền lương hoàn toàn không quan trọng.", "topic": "Mục 3.2. Quan điểm quan hệ con người."}, {"chapter_slug": "chuong-2", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Theo Douglas McGregor, một nhà quản trị cho rằng người lao động có thể tự định hướng, chấp nhận trách nhiệm và sáng tạo khi có điều kiện phù hợp đang thể hiện giả định của:", "option_a": "Theory X", "option_b": "Theory Y", "option_c": "Scientific Management", "option_d": "Bureaucratic Management", "correct_option": "B", "explanation": "Theory Y cho rằng trong điều kiện phù hợp, con người có khả năng:\n\n- tự định hướng;\n- tự kiểm soát;\n- nhận trách nhiệm;\n- sáng tạo.\n\nNgược lại, Theory X giả định người lao động thường không thích làm việc và cần được kiểm soát chặt chẽ.", "topic": "Mục 3.4.3. Thuyết X và Thuyết Y."}, {"chapter_slug": "chuong-2", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Phòng kinh doanh của một doanh nghiệp tăng mạnh doanh số nhờ chương trình khuyến mãi, nhưng bộ phận sản xuất không đáp ứng kịp khiến giao hàng trễ và khiếu nại tăng. Tình huống này phản ánh rõ nhất hạn chế nào?", "option_a": "Thiếu chuyên môn hóa lao động", "option_b": "Tối ưu cục bộ mà không xem xét hiệu quả toàn hệ thống", "option_c": "Thiếu hệ thống cấp bậc", "option_d": "Thiếu quản trị theo mục tiêu", "correct_option": "B", "explanation": "Phòng kinh doanh có thể đạt mục tiêu doanh số của riêng mình, nhưng kết quả đó lại làm:\n\n- sản xuất quá tải;\n- giao hàng trễ;\n- khiếu nại tăng.\n\nNhư vậy, một bộ phận đạt kết quả nhưng toàn tổ chức lại bị ảnh hưởng tiêu cực. Đây là biểu hiện của tối ưu cục bộ.\n\nQuan điểm hệ thống yêu cầu nhà quản trị phải xem xét hiệu quả của toàn tổ chức chứ không chỉ hiệu quả riêng của từng phòng ban.", "topic": "Mục 3.6.3. Sự phụ thuộc lẫn nhau; Mục 3.6.4. Ý nghĩa của quan điểm hệ thống."}, {"chapter_slug": "chuong-2", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp công nghệ hoạt động trong môi trường thay đổi nhanh nhưng lại áp dụng cơ cấu rất tập trung, nhiều cấp phê duyệt và quy trình cứng nhắc. Theo quan điểm tình huống, nhận định phù hợp nhất là:", "option_a": "Cơ cấu tập trung luôn sai", "option_b": "Cơ cấu phân quyền luôn tốt hơn", "option_c": "Vấn đề nằm ở sự không phù hợp giữa cơ cấu quản trị và môi trường hoạt động", "option_d": "Doanh nghiệp nên loại bỏ mọi quy trình", "correct_option": "C", "explanation": "Quan điểm tình huống không cho rằng tập trung luôn sai hoặc phân quyền luôn đúng.\n\nVấn đề nằm ở sự phù hợp.\n\nMột môi trường công nghệ biến động nhanh thường đòi hỏi:\n\n- tốc độ phản ứng cao;\n- nhiều quyền tự chủ;\n- giao tiếp ngang;\n- khả năng đổi mới.\n\nNếu cơ cấu quá tập trung và nhiều cấp phê duyệt, tốc độ phản ứng có thể không phù hợp với môi trường.", "topic": "Mục 3.7.2. Các yếu tố tình huống; Mục 3.7.3. Ý nghĩa của quan điểm tình huống."}, {"chapter_slug": "chuong-2", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một trung tâm chăm sóc khách hàng đặt KPI là “mỗi cuộc gọi không quá 3 phút”. Nhân viên đạt KPI nhưng tỷ lệ khách gọi lại và khiếu nại đều tăng. Phân tích phù hợp nhất là:", "option_a": "KPI càng cụ thể càng hiệu quả", "option_b": "Nhân viên thiếu kỷ luật", "option_c": "Chỉ tiêu đo lường đã trở thành mục tiêu thay thế cho mục tiêu phục vụ khách hàng", "option_d": "Công ty cần tăng thêm cấp quản trị", "correct_option": "C", "explanation": "Mục tiêu thật sự của trung tâm phải là:\n\ngiải quyết vấn đề của khách hàng hiệu quả.\n\nNhưng khi chỉ tiêu “3 phút” được đặt quá nặng, nhân viên có thể cố kết thúc cuộc gọi nhanh thay vì giải quyết triệt để vấn đề.\n\nNhư vậy, chỉ số đo lường đã lấn át mục tiêu thực sự.", "topic": "Mục 4.2.3. Ý nghĩa và hạn chế của quản trị theo mục tiêu."}, {"chapter_slug": "chuong-2", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một nhà quản trị quyết định áp dụng mô hình làm việc từ xa chỉ vì một công ty nổi tiếng đang áp dụng thành công. Cách ra quyết định này trái với quan điểm nào nhất?", "option_a": "Quản trị khoa học", "option_b": "Quản trị dựa trên bằng chứng", "option_c": "Quản trị hành chính", "option_d": "Quan điểm quan hệ con người", "correct_option": "B", "explanation": "Quản trị dựa trên bằng chứng yêu cầu nhà quản trị xem xét:\n\n- nghiên cứu khoa học;\n- dữ liệu của tổ chức;\n- kinh nghiệm chuyên môn;\n- đặc điểm tình huống;\n- phản hồi của các bên liên quan.\n\nViệc sao chép một mô hình chỉ vì “doanh nghiệp nổi tiếng đang làm” là quyết định dựa trên trào lưu chứ chưa phải bằng chứng.", "topic": "Mục 4.5. Quản trị dựa trên bằng chứng."}, {"chapter_slug": "chuong-2", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp sử dụng đồng thời: tiêu chuẩn hóa quy trình sản xuất, phân quyền quản lý, xây dựng hệ thống KPI, phân tích dữ liệu và điều chỉnh cơ cấu theo môi trường. Nhận định nào phù hợp nhất?", "option_a": "Doanh nghiệp đang vận dụng sai vì chỉ nên chọn một trường phái quản trị", "option_b": "Doanh nghiệp đang thể hiện tư duy hội nhập trong quản trị", "option_c": "Doanh nghiệp chỉ đang áp dụng quản trị khoa học", "option_d": "Doanh nghiệp chỉ đang áp dụng quan điểm tình huống", "correct_option": "B", "explanation": "Doanh nghiệp đang sử dụng nhiều tư tưởng quản trị khác nhau:\n\n- chuẩn hóa quy trình → Taylor;\n- phân quyền → Fayol;\n- KPI → quản trị theo mục tiêu;\n- dữ liệu → quan điểm định lượng;\n- điều chỉnh cơ cấu theo môi trường → quan điểm tình huống.\n\nĐiều này thể hiện đúng tinh thần của quan điểm hội nhập.", "topic": "Mục 3.8. Ý nghĩa của quan điểm hội nhập."}, {"chapter_slug": "chuong-2", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một xưởng sản xuất nhận thấy cùng một công đoạn nhưng mỗi công nhân thực hiện theo một cách khác nhau, dẫn đến thời gian hoàn thành và tỷ lệ lỗi rất khác biệt. Giải pháp phù hợp nhất theo tư tưởng Taylor là:", "option_a": "Cho công nhân hoàn toàn tự chọn cách làm", "option_b": "Phân tích công việc và xây dựng phương pháp thực hiện tiêu chuẩn", "option_c": "Tăng thêm cấp quản lý", "option_d": "Thay toàn bộ công nhân bằng máy móc", "correct_option": "B", "explanation": "Taylor chủ trương nghiên cứu công việc một cách khoa học để xác định phương pháp thực hiện hiệu quả thay vì để mỗi người làm theo kinh nghiệm riêng.", "topic": "Mục 2.2.2. Bốn nguyên tắc quản trị khoa học của Taylor."}, {"chapter_slug": "chuong-2", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty tuyển nhân viên bán hàng nhưng không có tiêu chuẩn tuyển dụng rõ ràng. Sau khi tuyển, nhân viên cũng không được đào tạo mà phải tự học qua kinh nghiệm. Theo Taylor, vấn đề quan trọng nhất là:", "option_a": "Thiếu thống nhất chỉ huy", "option_b": "Thiếu lựa chọn và đào tạo lao động một cách khoa học", "option_c": "Thiếu hệ thống cấp bậc", "option_d": "Thiếu quản trị chất lượng toàn diện", "correct_option": "B", "explanation": "Một trong bốn nguyên tắc của Taylor là lựa chọn, đào tạo và phát triển người lao động phù hợp với yêu cầu của công việc.", "topic": "Mục 2.2.2. Bốn nguyên tắc quản trị khoa học của Taylor."}, {"chapter_slug": "chuong-2", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên nhận yêu cầu trực tiếp từ trưởng phòng kinh doanh và đồng thời nhận một yêu cầu trái ngược từ phó giám đốc. Nhân viên không biết phải thực hiện chỉ đạo nào trước. Nguyên tắc nào của Fayol đang bị vi phạm rõ nhất?", "option_a": "Phân công lao động", "option_b": "Thống nhất chỉ huy", "option_c": "Công bằng", "option_d": "Tinh thần đoàn kết", "correct_option": "B", "explanation": "Thống nhất chỉ huy yêu cầu một nhân viên nên nhận mệnh lệnh trực tiếp từ một cấp trên, nhằm hạn chế xung đột chỉ đạo và trách nhiệm không rõ ràng.", "topic": "Mục 2.3.3. Nguyên tắc thống nhất chỉ huy của Fayol."}, {"chapter_slug": "chuong-2", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty giao cho trưởng chi nhánh chịu trách nhiệm hoàn toàn về doanh thu, nhưng mọi chương trình khuyến mãi, tuyển nhân viên và điều chỉnh giá đều phải được tổng giám đốc phê duyệt. Theo Fayol, vấn đề chính là:", "option_a": "Thiếu tương xứng giữa quyền hạn và trách nhiệm", "option_b": "Thiếu phân công lao động", "option_c": "Thiếu kỷ luật", "option_d": "Thiếu tinh thần đoàn kết", "correct_option": "A", "explanation": "Người quản trị không thể bị yêu cầu chịu trách nhiệm lớn nếu không được trao quyền hạn tương ứng để thực hiện nhiệm vụ.", "topic": "Mục 2.3.3. Nguyên tắc quyền hạn và trách nhiệm."}, {"chapter_slug": "chuong-2", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp gia đình thường bổ nhiệm người thân vào vị trí quản lý dù người đó không có chuyên môn phù hợp. Nếu đánh giá theo mô hình Weber, tổ chức đang vi phạm nguyên tắc nào rõ nhất?", "option_a": "Tuyển dụng dựa trên năng lực chuyên môn", "option_b": "Thống nhất định hướng", "option_c": "Quản trị theo mục tiêu", "option_d": "Cải tiến liên tục", "correct_option": "A", "explanation": "Weber nhấn mạnh các chức vụ chính thức cần được đảm nhiệm dựa trên năng lực, trình độ và chuyên môn thay vì quan hệ cá nhân.", "topic": "Mục 2.4.2. Những đặc điểm chủ yếu của mô hình Weber."}, {"chapter_slug": "chuong-2", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một ngân hàng quy định mọi giao dịch lớn phải được ghi nhận đầy đủ, lưu hồ sơ và có cấp có thẩm quyền phê duyệt. Tư tưởng nào thể hiện rõ nhất?", "option_a": "Human Relations", "option_b": "Bureaucracy của Weber", "option_c": "Theory Y", "option_d": "Learning Organization", "correct_option": "B", "explanation": "Hệ thống hồ sơ, quyền hạn rõ ràng, quy tắc chính thức và cấp bậc phê duyệt là những đặc điểm điển hình trong mô hình tổ chức quan liêu của Weber.", "topic": "Mục 2.4. Mô hình tổ chức quan liêu."}, {"chapter_slug": "chuong-2", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty có quy trình yêu cầu khách hàng phải nộp bản sao một loại giấy tờ dù thông tin đó đã có sẵn trên hệ thống. Nhân viên vẫn yêu cầu khách thực hiện vì “quy định ghi vậy”. Hạn chế nào đang xuất hiện?", "option_a": "Chuyên môn hóa không đủ", "option_b": "Quy trình trở nên cứng nhắc và xa rời mục tiêu thực tế", "option_c": "Không có hệ thống cấp bậc", "option_d": "Phân quyền quá mức", "correct_option": "B", "explanation": "Khi quy tắc được tuân thủ một cách máy móc dù không còn phục vụ mục tiêu, bureaucracy có thể trở nên cứng nhắc và làm giảm hiệu quả phục vụ.", "topic": "Mục 2.4.3. Đóng góp và hạn chế của mô hình Weber."}, {"chapter_slug": "chuong-2", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một quản lý thường chỉ quan tâm đến tiền thưởng nhưng bỏ qua bầu không khí nhóm, mâu thuẫn đồng nghiệp và cảm giác được công nhận của nhân viên. Quan điểm nào cho thấy cách quản lý này chưa đầy đủ?", "option_a": "Quan điểm quan hệ con người", "option_b": "Quản trị khoa học", "option_c": "Quan điểm định lượng", "option_d": "MBO", "correct_option": "A", "explanation": "Quan điểm quan hệ con người nhấn mạnh rằng hành vi và năng suất còn chịu ảnh hưởng của yếu tố xã hội, tâm lý và quan hệ nhóm, chứ không chỉ do các yếu tố kinh tế.", "topic": "Mục 3.2. Quan điểm quan hệ con người."}, {"chapter_slug": "chuong-2", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhóm nhân viên không có chức vụ quản lý nhưng thường xuyên ảnh hưởng đến thái độ và quyết định của những người khác trong phòng. Hiện tượng này phản ánh:", "option_a": "Chỉ có cơ cấu chính thức mới ảnh hưởng hành vi", "option_b": "Vai trò của nhóm và quan hệ không chính thức", "option_c": "Việc thiếu quản trị khoa học", "option_d": "Việc thiếu kiểm soát chất lượng", "correct_option": "B", "explanation": "Quan điểm quan hệ con người cho thấy bên cạnh cơ cấu chính thức, tổ chức còn tồn tại các nhóm và mạng lưới xã hội không chính thức có ảnh hưởng đáng kể đến hành vi của thành viên.", "topic": "Mục 3.2. Quan điểm quan hệ con người."}, {"chapter_slug": "chuong-2", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Phòng marketing muốn tung nhiều mẫu sản phẩm để đáp ứng khách hàng, trong khi phòng sản xuất muốn giảm số mẫu để tiết kiệm chi phí. Theo Mary Parker Follett, giải pháp tốt nhất là:", "option_a": "Cho marketing thắng", "option_b": "Cho sản xuất thắng", "option_c": "Mỗi bên giảm một nửa yêu cầu", "option_d": "Tìm phương án mới đáp ứng lợi ích cốt lõi của cả hai bên", "correct_option": "D", "explanation": "Follett đề cao integration – tích hợp, tức tìm một giải pháp mới có thể xử lý lợi ích cơ bản của cả hai bên thay vì chỉ áp đặt hoặc thỏa hiệp đơn thuần.", "topic": "Mục 3.3. Mary Parker Follett và tư tưởng phối hợp."}, {"chapter_slug": "chuong-2", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên đã có mức lương ổn định nhưng vẫn muốn được giao công việc khó hơn, được ghi nhận và có cơ hội phát triển nghề nghiệp. Lý thuyết nào giúp giải thích tốt nhất?", "option_a": "Maslow", "option_b": "Weber", "option_c": "Taylor", "option_d": "Fayol", "correct_option": "A", "explanation": "Maslow cho rằng ngoài nhu cầu cơ bản, con người còn có nhu cầu được tôn trọng và tự hoàn thiện. Vì vậy, tiền lương không phải yếu tố động lực duy nhất.", "topic": "Mục 3.4.2. Hệ thống nhu cầu của Abraham Maslow."}, {"chapter_slug": "chuong-2", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một giám đốc cho rằng “nhân viên mà không giám sát thì chắc chắn sẽ lười”, vì vậy mọi quyết định nhỏ đều phải xin phép. Quan điểm của giám đốc này gần nhất với:", "option_a": "Theory Y", "option_b": "Theory X", "option_c": "Systems Approach", "option_d": "MBO", "correct_option": "B", "explanation": "Theory X phản ánh giả định rằng người lao động không thích làm việc, né tránh trách nhiệm và cần được giám sát, kiểm soát chặt chẽ.", "topic": "Mục 3.4.3. Thuyết X và Thuyết Y."}, {"chapter_slug": "chuong-2", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty logistics cần lựa chọn tuyến giao hàng sao cho tổng chi phí vận chuyển thấp nhất trong điều kiện giới hạn về xe và thời gian. Cách tiếp cận phù hợp nhất là:", "option_a": "Quan hệ con người", "option_b": "Quan điểm định lượng", "option_c": "Bureaucracy", "option_d": "Theory Y", "correct_option": "B", "explanation": "Bài toán phân bổ phương tiện và tối ưu tuyến vận chuyển là ứng dụng điển hình của phương pháp định lượng và nghiên cứu tác nghiệp.", "topic": "Mục 3.5. Quan điểm định lượng."}, {"chapter_slug": "chuong-2", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp dùng phần mềm tối ưu lịch làm việc. Mô hình đề xuất giảm mạnh số nhân viên để tiết kiệm chi phí nhưng không tính đến chất lượng dịch vụ và sự quá tải. Bài học phù hợp nhất là:", "option_a": "Mô hình định lượng luôn cho đáp án đúng", "option_b": "Mô hình định lượng chỉ hỗ trợ quyết định và phụ thuộc vào dữ liệu, giả định", "option_c": "Nhà quản trị không nên sử dụng dữ liệu", "option_d": "Phải giao toàn bộ quyết định cho thuật toán", "correct_option": "B", "explanation": "Mô hình toán học chỉ phản ánh những yếu tố được đưa vào mô hình. Nếu bỏ sót yếu tố quan trọng, kết quả có thể tối ưu về số học nhưng không tối ưu về quản trị.", "topic": "Mục 3.5.3 và 3.5.4. Giá trị và hạn chế của quan điểm định lượng."}, {"chapter_slug": "chuong-2", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Phòng mua hàng được thưởng nếu giảm giá nguyên liệu. Họ chọn nhà cung cấp rẻ hơn, nhưng sau đó sản phẩm lỗi tăng và chi phí bảo hành tăng mạnh. Quan điểm nào giải thích tốt nhất?", "option_a": "Hệ thống", "option_b": "Quản trị khoa học", "option_c": "Theory X", "option_d": "Bureaucracy", "correct_option": "A", "explanation": "Phòng mua hàng tối ưu mục tiêu của bộ phận nhưng làm giảm hiệu quả toàn doanh nghiệp. Đây là ví dụ điển hình của tối ưu cục bộ trong tư duy hệ thống.", "topic": "Mục 3.6. Quan điểm hệ thống."}, {"chapter_slug": "chuong-2", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp áp dụng cùng một cơ cấu quản lý cho cả nhà máy sản xuất tiêu chuẩn và trung tâm nghiên cứu sản phẩm mới. Kết quả trung tâm nghiên cứu hoạt động kém hiệu quả. Quan điểm nào giải thích rõ nhất?", "option_a": "Quan điểm tình huống", "option_b": "Scientific Management", "option_c": "Human Relations", "option_d": "Maslow", "correct_option": "A", "explanation": "Hai đơn vị có công nghệ, nhiệm vụ và mức độ bất định khác nhau nên không nhất thiết phù hợp với cùng một cơ cấu quản trị.\n\nQuan điểm tình huống yêu cầu phương pháp quản trị phải phù hợp với đặc điểm cụ thể của từng đơn vị.", "topic": "Mục 3.7. Quan điểm tình huống."}, {"chapter_slug": "chuong-2", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một giám đốc thấy doanh nghiệp đối thủ thành công nhờ phân quyền nên quyết định phân quyền mạnh cho toàn công ty mình mà không xem xét năng lực cấp dưới hay hệ thống kiểm soát. Sai lầm lớn nhất là:", "option_a": "Không tuân thủ Taylor", "option_b": "Không xem xét các yếu tố tình huống", "option_c": "Không áp dụng Theory X", "option_d": "Không áp dụng bureaucracy", "correct_option": "B", "explanation": "Phân quyền không phải lúc nào cũng tốt. Mức độ phân quyền phải phù hợp với:\n\n- năng lực nhân sự;\n- rủi ro;\n- quy mô;\n- chiến lược;\n- đặc điểm môi trường.\n\nĐây là nội dung cốt lõi của quan điểm tình huống.", "topic": "Mục 3.7.2. Các yếu tố tình huống."}, {"chapter_slug": "chuong-2", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty đặt mục tiêu “tăng 20% doanh thu”, nhưng các phòng ban không biết mục tiêu của mình liên quan thế nào đến mục tiêu chung. Theo MBO, công ty đang thiếu điều gì?", "option_a": "Liên kết mục tiêu tổ chức, bộ phận và cá nhân", "option_b": "Thêm nhiều quy trình chính thức", "option_c": "Thêm nhiều cấp quản trị", "option_d": "Giảm toàn bộ chỉ tiêu", "correct_option": "A", "explanation": "MBO yêu cầu mục tiêu tổ chức phải được cụ thể hóa thành mục tiêu bộ phận và cá nhân để hoạt động của các cấp cùng hướng về kết quả chung.", "topic": "Mục 4.2. Quản trị theo mục tiêu."}, {"chapter_slug": "chuong-2", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhà máy chỉ kiểm tra sản phẩm ở cuối dây chuyền. Nếu phát hiện lỗi thì loại bỏ và sản xuất lại. Theo tư tưởng quản trị chất lượng hiện đại, cách cải tiến phù hợp hơn là:", "option_a": "Kiểm tra cuối cùng nhiều hơn", "option_b": "Tăng số nhân viên kiểm tra", "option_c": "Tìm nguyên nhân trong quy trình và ngăn lỗi xảy ra từ đầu", "option_d": "Bỏ hoàn toàn tiêu chuẩn chất lượng", "correct_option": "C", "explanation": "TQM và tư tưởng Deming nhấn mạnh xây dựng chất lượng ngay trong quy trình, phòng ngừa sai lỗi và cải tiến liên tục thay vì chỉ kiểm tra sản phẩm cuối cùng.", "topic": "Mục 4.3. Quản trị chất lượng toàn diện."}, {"chapter_slug": "chuong-2", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp triển khai AI để tuyển dụng. Hệ thống hoạt động nhanh nhưng sau đó phát hiện thuật toán thường loại một nhóm ứng viên nhất định. Nhà quản trị nên làm gì phù hợp nhất?", "option_a": "Tiếp tục sử dụng vì AI luôn khách quan", "option_b": "Chỉ quan tâm đến tốc độ tuyển dụng", "option_c": "Kiểm tra dữ liệu, tiêu chí thuật toán và trách nhiệm đối với quyết định", "option_d": "Giao toàn bộ trách nhiệm cho nhà cung cấp phần mềm", "correct_option": "C", "explanation": "Quản trị trong môi trường số không chỉ quan tâm đến hiệu quả mà còn phải xem xét:\n\n- thiên lệch dữ liệu;\n- tính công bằng;\n- trách nhiệm;\n- quyền riêng tư;\n- đạo đức.\n\nAI hỗ trợ quyết định nhưng không loại bỏ trách nhiệm của nhà quản trị.", "topic": "Mục 4.6. Quản trị trong môi trường số và AI."}, {"chapter_slug": "chuong-3", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Môi trường quản trị được hiểu là:", "option_a": "Chỉ những yếu tố kinh tế bên ngoài doanh nghiệp", "option_b": "Tổng thể các yếu tố có khả năng tác động đến quyết định và hoạt động của tổ chức", "option_c": "Chỉ những yếu tố nằm trong doanh nghiệp", "option_d": "Chỉ những yếu tố nhà quản trị có thể kiểm soát", "correct_option": "B", "explanation": "Môi trường quản trị bao gồm các yếu tố và lực lượng có khả năng ảnh hưởng đến quyết định, hoạt động và khả năng đạt mục tiêu của tổ chức.", "topic": "Mục 1.1. Khái niệm môi trường quản trị."}, {"chapter_slug": "chuong-3", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Yếu tố nào sau đây thuộc môi trường bên trong của tổ chức?", "option_a": "Lãi suất", "option_b": "Đối thủ cạnh tranh", "option_c": "Văn hóa tổ chức", "option_d": "Chính sách thuế", "correct_option": "C", "explanation": "Văn hóa tổ chức hình thành và tồn tại bên trong tổ chức. Lãi suất, đối thủ và chính sách thuế đều là những yếu tố bên ngoài.", "topic": "Mục 2.1. Môi trường bên trong."}, {"chapter_slug": "chuong-3", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Yếu tố nào thuộc môi trường tổng quát?", "option_a": "Khách hàng trực tiếp", "option_b": "Nhà cung cấp", "option_c": "Công nghệ", "option_d": "Đối thủ cạnh tranh trực tiếp", "correct_option": "C", "explanation": "Công nghệ là một lực lượng rộng lớn có khả năng ảnh hưởng đến nhiều ngành và tổ chức nên thuộc môi trường tổng quát.", "topic": "Mục 2.3. Môi trường tổng quát."}, {"chapter_slug": "chuong-3", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Yếu tố nào sau đây thuộc môi trường đặc thù?", "option_a": "Lạm phát", "option_b": "Dân số", "option_c": "Nhà cung cấp", "option_d": "Văn hóa xã hội", "correct_option": "C", "explanation": "Nhà cung cấp có quan hệ trực tiếp với tổ chức và ảnh hưởng đến khả năng tiếp cận các đầu vào nên thuộc môi trường đặc thù.", "topic": "Mục 2.4. Môi trường đặc thù."}, {"chapter_slug": "chuong-3", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Môi trường tổng quát thường bao gồm:", "option_a": "Khách hàng, nhà cung cấp và đối thủ", "option_b": "Kinh tế, chính trị – pháp luật, văn hóa – xã hội, dân số, công nghệ và toàn cầu", "option_c": "Nhân viên, vốn và máy móc", "option_d": "Chỉ các cơ quan nhà nước", "correct_option": "B", "explanation": "Đây là sáu nhóm yếu tố tổng quát thường được sử dụng trong cách phân loại của Robbins và Coulter.", "topic": "Mục 2.3. Môi trường tổng quát."}, {"chapter_slug": "chuong-3", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Yếu tố nào sau đây thuộc môi trường kinh tế?", "option_a": "Lạm phát", "option_b": "Giá trị văn hóa", "option_c": "Tuổi dân số", "option_d": "Công nghệ AI", "correct_option": "A", "explanation": "Lạm phát phản ánh tình trạng kinh tế và có thể ảnh hưởng đến chi phí, giá cả và sức mua.", "topic": "Mục 2.3.2. Môi trường kinh tế."}, {"chapter_slug": "chuong-3", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Sự bất trắc của môi trường phụ thuộc chủ yếu vào:", "option_a": "Quy mô và lợi nhuận", "option_b": "Mức độ thay đổi và mức độ phức tạp", "option_c": "Số lượng nhân viên và cấp quản trị", "option_d": "Doanh thu và thị phần", "correct_option": "B", "explanation": "Hai chiều quan trọng để đánh giá sự bất trắc là mức độ môi trường thay đổi và số lượng, tính đa dạng của các yếu tố mà nhà quản trị phải theo dõi.", "topic": "Mục 3.1. Khái niệm sự bất trắc của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Môi trường có ít yếu tố và các yếu tố thay đổi chậm được gọi là:", "option_a": "Phức tạp – năng động", "option_b": "Đơn giản – ổn định", "option_c": "Phức tạp – ổn định", "option_d": "Đơn giản – năng động", "correct_option": "B", "explanation": "Ít yếu tố thể hiện mức độ phức tạp thấp; thay đổi chậm thể hiện mức độ ổn định cao.", "topic": "Mục 3.4. Ma trận bất trắc của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quá trình thu thập và phân tích thông tin môi trường nhằm phát hiện xu hướng được gọi là:", "option_a": "Phân công lao động", "option_b": "Quét môi trường", "option_c": "Kiểm soát chất lượng", "option_d": "Chuyên môn hóa", "correct_option": "B", "explanation": "Environmental scanning giúp nhà quản trị theo dõi những thay đổi và phát hiện sớm cơ hội hoặc nguy cơ.", "topic": "Mục 3.6.1. Quét môi trường."}, {"chapter_slug": "chuong-3", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Biện pháp nào giúp giảm rủi ro khi doanh nghiệp đang phụ thuộc hoàn toàn vào một nhà cung cấp?", "option_a": "Giảm số lượng nhà cung cấp xuống một", "option_b": "Đa dạng hóa nhà cung cấp", "option_c": "Ngừng thu thập thông tin", "option_d": "Tăng mức độ tập trung quyền lực", "correct_option": "B", "explanation": "Đa dạng hóa nhà cung cấp giúp giảm mức độ phụ thuộc vào một nguồn lực bên ngoài duy nhất.", "topic": "Mục 3.6.5. Giảm sự phụ thuộc vào một nguồn lực duy nhất."}, {"chapter_slug": "chuong-3", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác biệt quan trọng giữa môi trường tổng quát và môi trường đặc thù là:", "option_a": "Môi trường tổng quát luôn quan trọng hơn", "option_b": "Môi trường đặc thù thường tác động trực tiếp hơn đến việc đạt mục tiêu của tổ chức", "option_c": "Môi trường tổng quát nằm trong tổ chức", "option_d": "Môi trường đặc thù không thay đổi", "correct_option": "B", "explanation": "Môi trường đặc thù gồm những lực lượng có quan hệ trực tiếp hơn như khách hàng, nhà cung cấp và đối thủ. Môi trường tổng quát thường tạo ra những điều kiện rộng lớn hơn.", "topic": "Mục 2.3 và 2.4."}, {"chapter_slug": "chuong-3", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một doanh nghiệp phải theo dõi nhiều cơ quan quản lý, hàng chục đối thủ, nhiều nhóm khách hàng và nhiều loại công nghệ. Điều này phản ánh:", "option_a": "Mức độ thay đổi thấp", "option_b": "Mức độ phức tạp cao", "option_c": "Môi trường ổn định", "option_d": "Môi trường nội bộ yếu", "correct_option": "B", "explanation": "Mức độ phức tạp tăng khi nhà quản trị phải theo dõi nhiều yếu tố khác nhau và cần nhiều kiến thức để hiểu chúng.", "topic": "Mục 3.3. Mức độ phức tạp của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Trong điều kiện môi trường vừa phức tạp vừa thay đổi nhanh, mức độ bất trắc thường:", "option_a": "Thấp nhất", "option_b": "Không đáng kể", "option_c": "Cao nhất", "option_d": "Không liên quan đến quản trị", "correct_option": "C", "explanation": "Khi vừa phải xử lý nhiều yếu tố, vừa phải đối mặt với sự thay đổi nhanh, khả năng dự đoán của nhà quản trị giảm mạnh.", "topic": "Mục 3.4. Ma trận bất trắc của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Doanh nghiệp xây dựng ba phương án ứng phó tương ứng với ba mức nhu cầu thị trường khác nhau. Đây là:", "option_a": "Hoạch định theo kịch bản", "option_b": "Chuyên môn hóa", "option_c": "Phân công lao động", "option_d": "Quản trị hành chính", "correct_option": "A", "explanation": "Scenario planning chuẩn bị trước nhiều trạng thái tương lai có thể xảy ra và phương án phản ứng tương ứng.", "topic": "Mục 3.6.3. Xây dựng các kịch bản."}, {"chapter_slug": "chuong-3", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Khi môi trường biến động nhanh, tổ chức thường cần:", "option_a": "Giảm thông tin", "option_b": "Tăng khả năng linh hoạt và phản ứng", "option_c": "Loại bỏ hoàn toàn phân quyền", "option_d": "Chỉ sử dụng kế hoạch dài hạn cố định", "correct_option": "B", "explanation": "Môi trường năng động đòi hỏi tổ chức phải điều chỉnh nhanh hơn, tăng trao đổi thông tin và khả năng ra quyết định.", "topic": "Mục 3.5 và 3.6.4."}, {"chapter_slug": "chuong-3", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp có thị trường tương đối ổn định nhưng phải tuân thủ nhiều hệ thống pháp luật, sử dụng nhiều nhà cung cấp chuyên môn và phục vụ nhiều nhóm khách hàng. Môi trường phù hợp nhất là:", "option_a": "Đơn giản – ổn định", "option_b": "Phức tạp – ổn định", "option_c": "Đơn giản – năng động", "option_d": "Phức tạp – năng động", "correct_option": "B", "explanation": "Có nhiều yếu tố cần theo dõi nên môi trường phức tạp; nhưng các yếu tố thay đổi tương đối chậm nên môi trường vẫn ổn định.", "topic": "Mục 3.4. Ma trận bất trắc của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp nhận thấy xu hướng công nghệ thay đổi nhưng vẫn tiếp tục sử dụng dữ liệu thị trường của ba năm trước để hoạch định sản phẩm. Vấn đề lớn nhất là:", "option_a": "Thiếu phân công lao động", "option_b": "Hệ thống quét môi trường không hiệu quả", "option_c": "Có quá nhiều nhà cung cấp", "option_d": "Mức độ chuyên môn hóa thấp", "correct_option": "B", "explanation": "Trong môi trường thay đổi nhanh, thông tin cũ có thể nhanh chóng mất giá trị. Doanh nghiệp cần hệ thống theo dõi và cập nhật môi trường thường xuyên.", "topic": "Mục 3.6.1. Quét môi trường."}, {"chapter_slug": "chuong-3", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty giảm chi phí bằng cách chỉ sử dụng duy nhất một nhà cung cấp. Sau đó nhà cung cấp gặp sự cố khiến toàn bộ dây chuyền dừng hoạt động. Bài học phù hợp nhất là:", "option_a": "Luôn chọn nhà cung cấp rẻ nhất", "option_b": "Cần quản trị sự phụ thuộc vào nguồn lực bên ngoài", "option_c": "Môi trường tổng quát không quan trọng", "option_d": "Cần tăng thêm cấp quản trị", "correct_option": "B", "explanation": "Phụ thuộc quá lớn vào một nguồn lực bên ngoài làm tăng tính dễ tổn thương của tổ chức. Có thể giảm rủi ro bằng nguồn cung thay thế, hợp đồng hoặc dự trữ.", "topic": "Mục 3.6.5. Giảm sự phụ thuộc vào một nguồn lực duy nhất."}, {"chapter_slug": "chuong-3", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Hai doanh nghiệp cùng chịu tỷ lệ lạm phát như nhau nhưng một doanh nghiệp bị ảnh hưởng nghiêm trọng hơn doanh nghiệp còn lại. Điều này cho thấy:", "option_a": "Một yếu tố môi trường luôn tác động giống nhau đến mọi tổ chức", "option_b": "Tác động của môi trường còn phụ thuộc vào đặc điểm và mức độ phụ thuộc của từng tổ chức", "option_c": "Lạm phát không phải yếu tố môi trường", "option_d": "Môi trường bên ngoài không ảnh hưởng nhà quản trị", "correct_option": "B", "explanation": "Cùng một yếu tố bên ngoài có thể tạo tác động khác nhau tùy ngành, chiến lược, khách hàng, nguồn lực và mức độ phụ thuộc của tổ chức.", "topic": "Mục 1.3 và 2.5."}, {"chapter_slug": "chuong-3", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Doanh nghiệp hoạt động trong môi trường bất trắc cao nhưng vẫn sử dụng kế hoạch năm cố định, mọi thay đổi phải chờ tổng giám đốc phê duyệt. Vấn đề phù hợp nhất là:", "option_a": "Cách tổ chức chưa phù hợp với mức độ bất trắc của môi trường", "option_b": "Doanh nghiệp cần thêm nhiều quy tắc hơn", "option_c": "Doanh nghiệp cần giảm thu thập thông tin", "option_d": "Doanh nghiệp đang quá phân quyền", "correct_option": "A", "explanation": "Bất trắc cao thường yêu cầu khả năng cập nhật, phối hợp và điều chỉnh nhanh hơn. Một hệ thống quá cứng có thể làm giảm khả năng phản ứng.", "topic": "Mục 3.5. Ảnh hưởng của bất trắc môi trường đến nhà quản trị."}, {"chapter_slug": "chuong-3", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một quán cà phê nhận thấy ngày càng nhiều khách hàng chuyển sang chọn đồ uống ít đường. Yếu tố môi trường nào đang tác động trực tiếp nhất?", "option_a": "Nhà cung cấp", "option_b": "Văn hóa – xã hội", "option_c": "Cơ cấu tổ chức", "option_d": "Nguồn lực tài chính", "correct_option": "B", "explanation": "Sự thay đổi trong lối sống và thái độ đối với sức khỏe là một xu hướng văn hóa – xã hội.", "topic": "Mục 2.3.4. Môi trường văn hóa – xã hội."}, {"chapter_slug": "chuong-3", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Ngân hàng tăng lãi suất cho vay khiến doanh nghiệp hoãn kế hoạch mở thêm nhà máy. Yếu tố tác động là:", "option_a": "Môi trường kinh tế", "option_b": "Môi trường văn hóa", "option_c": "Khách hàng", "option_d": "Văn hóa tổ chức", "correct_option": "A", "explanation": "Lãi suất là một yếu tố thuộc môi trường kinh tế và ảnh hưởng trực tiếp đến chi phí sử dụng vốn.", "topic": "Mục 2.3.2. Môi trường kinh tế."}, {"chapter_slug": "chuong-3", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Nhà nước ban hành quy định mới yêu cầu doanh nghiệp phải đáp ứng tiêu chuẩn an toàn cao hơn. Đây là tác động của:", "option_a": "Môi trường dân số", "option_b": "Môi trường chính trị – pháp luật", "option_c": "Môi trường nội bộ", "option_d": "Đối thủ cạnh tranh", "correct_option": "B", "explanation": "Các quy định pháp luật và chính sách nhà nước thuộc môi trường chính trị – pháp luật.", "topic": "Mục 2.3.3. Môi trường chính trị – pháp luật."}, {"chapter_slug": "chuong-3", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một trường đại học nhận thấy số lượng học sinh ở nhóm tuổi tuyển sinh trong khu vực giảm liên tục. Đây là yếu tố thuộc:", "option_a": "Môi trường dân số", "option_b": "Môi trường công nghệ", "option_c": "Nhà cung cấp", "option_d": "Văn hóa nội bộ", "correct_option": "A", "explanation": "Quy mô và cơ cấu độ tuổi của dân số là yếu tố nhân khẩu học.", "topic": "Mục 2.3.5. Môi trường dân số."}, {"chapter_slug": "chuong-3", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một phần mềm AI mới giúp đối thủ xử lý đơn hàng nhanh hơn 50%. Doanh nghiệp cần xem đây trước hết là thay đổi của:", "option_a": "Môi trường công nghệ", "option_b": "Môi trường dân số", "option_c": "Văn hóa nội bộ", "option_d": "Nguồn tài chính", "correct_option": "A", "explanation": "Sự xuất hiện của AI mới là thay đổi công nghệ, có khả năng làm thay đổi quy trình và lợi thế cạnh tranh.", "topic": "Mục 2.3.6. Môi trường công nghệ."}, {"chapter_slug": "chuong-3", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp nhập khẩu nguyên liệu gặp khó khăn khi tỷ giá ngoại tệ tăng mạnh. Tình huống này thể hiện:", "option_a": "Tổ chức không chịu ảnh hưởng của môi trường", "option_b": "Sự tác động của môi trường kinh tế và toàn cầu", "option_c": "Chỉ là vấn đề văn hóa nội bộ", "option_d": "Chỉ liên quan đến nguồn nhân lực", "correct_option": "B", "explanation": "Tỷ giá là yếu tố kinh tế, đồng thời hoạt động nhập khẩu làm doanh nghiệp chịu ảnh hưởng của môi trường toàn cầu.", "topic": "Mục 2.3.2 và 2.3.7."}, {"chapter_slug": "chuong-3", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một siêu thị phát hiện nhà cung cấp chính liên tục giao hàng chậm. Yếu tố môi trường đặc thù nào đang gây rủi ro?", "option_a": "Khách hàng", "option_b": "Nhà cung cấp", "option_c": "Công nghệ", "option_d": "Dân số", "correct_option": "B", "explanation": "Nhà cung cấp ảnh hưởng trực tiếp đến khả năng duy trì các đầu vào cần thiết của tổ chức.", "topic": "Mục 2.4.3. Nhà cung cấp."}, {"chapter_slug": "chuong-3", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một hãng điện thoại giảm giá mạnh sau khi đối thủ tung ra sản phẩm mới có nhiều tính năng hơn. Đây là phản ứng chủ yếu trước:", "option_a": "Cơ quan quản lý", "option_b": "Đối thủ cạnh tranh", "option_c": "Môi trường dân số", "option_d": "Văn hóa tổ chức", "correct_option": "B", "explanation": "Đối thủ có thể tác động trực tiếp đến giá, sản phẩm và chiến lược cạnh tranh của tổ chức.", "topic": "Mục 2.4.4. Đối thủ cạnh tranh."}, {"chapter_slug": "chuong-3", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp có nguồn vốn tốt và công nghệ hiện đại nhưng nhân viên thiếu kỹ năng sử dụng máy mới. Vấn đề thuộc chủ yếu về:", "option_a": "Môi trường bên trong", "option_b": "Môi trường toàn cầu", "option_c": "Khách hàng", "option_d": "Chính trị – pháp luật", "correct_option": "A", "explanation": "Năng lực của nguồn nhân lực là thành phần của môi trường nội bộ.", "topic": "Mục 2.1.3. Nguồn nhân lực."}, {"chapter_slug": "chuong-3", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp khuyến khích nhân viên thử nghiệm ý tưởng mới và không trừng phạt những thất bại hợp lý. Yếu tố nào đang hỗ trợ khả năng thích nghi?", "option_a": "Văn hóa tổ chức", "option_b": "Lạm phát", "option_c": "Đối thủ", "option_d": "Dân số", "correct_option": "A", "explanation": "Văn hóa tổ chức ảnh hưởng đến thái độ của nhân viên đối với đổi mới, học tập và rủi ro.", "topic": "Mục 2.1.7. Văn hóa tổ chức."}, {"chapter_slug": "chuong-3", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một cửa hàng nhỏ chỉ có hai đối thủ, ba nhà cung cấp và nhu cầu khách hàng thay đổi rất ít. Môi trường gần nhất với:", "option_a": "Đơn giản – ổn định", "option_b": "Phức tạp – năng động", "option_c": "Đơn giản – năng động", "option_d": "Phức tạp – ổn định", "correct_option": "A", "explanation": "Số lượng yếu tố ít nên đơn giản; các yếu tố thay đổi ít nên ổn định.", "topic": "Mục 3.4. Ma trận bất trắc của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty công nghệ phải theo dõi hàng chục đối thủ, luật ở nhiều quốc gia và công nghệ thay đổi liên tục. Môi trường của công ty có khả năng:", "option_a": "Bất trắc thấp", "option_b": "Bất trắc rất cao", "option_c": "Hoàn toàn ổn định", "option_d": "Đơn giản", "correct_option": "B", "explanation": "Môi trường vừa có nhiều yếu tố vừa thay đổi nhanh thuộc dạng phức tạp – năng động, tạo mức bất trắc cao.", "topic": "Mục 3.4. Ma trận bất trắc của môi trường."}, {"chapter_slug": "chuong-3", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp thường xuyên đọc báo cáo ngành, theo dõi mạng xã hội, khảo sát khách hàng và theo dõi đối thủ. Doanh nghiệp đang thực hiện:", "option_a": "Quét môi trường", "option_b": "Phân công lao động", "option_c": "Quản trị khoa học", "option_d": "Tập trung hóa", "correct_option": "A", "explanation": "Các hoạt động trên nhằm thu thập và phân tích thông tin để phát hiện những thay đổi trong môi trường.", "topic": "Mục 3.6.1. Quét môi trường."}, {"chapter_slug": "chuong-3", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp dự báo nhu cầu năm sau tăng 15% dựa trên dữ liệu bán hàng và xu hướng thị trường. Hoạt động này là:", "option_a": "Dự báo", "option_b": "Quản trị hành chính", "option_c": "Chuyên môn hóa", "option_d": "Kiểm soát bureaucracy", "correct_option": "A", "explanation": "Dự báo sử dụng thông tin hiện tại và quá khứ để ước lượng những điều kiện có thể xảy ra trong tương lai.", "topic": "Mục 3.6.2. Dự báo."}, {"chapter_slug": "chuong-3", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp chuẩn bị sẵn kế hoạch nếu nhà cung cấp chính ngừng hoạt động, trong đó xác định hai nhà cung cấp thay thế. Đây là:", "option_a": "Kế hoạch dự phòng", "option_b": "Unity of Command", "option_c": "Theory X", "option_d": "Chuyên môn hóa", "correct_option": "A", "explanation": "Kế hoạch dự phòng được xây dựng trước để tổ chức phản ứng khi sự kiện ngoài kế hoạch xảy ra.", "topic": "Mục 3.6.7. Chuẩn bị phương án dự phòng."}, {"chapter_slug": "chuong-3", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty nhận thấy nhu cầu thay đổi nhanh nên trao thêm quyền quyết định về giá cho quản lý khu vực thay vì chờ trụ sở chính phê duyệt từng trường hợp. Biện pháp này nhằm:", "option_a": "Tăng khả năng linh hoạt", "option_b": "Tăng phụ thuộc bên ngoài", "option_c": "Giảm khả năng phản ứng", "option_d": "Tăng mức độ phức tạp của môi trường", "correct_option": "A", "explanation": "Trao quyền hợp lý giúp đơn vị phản ứng nhanh hơn khi môi trường thay đổi.", "topic": "Mục 3.6.4. Tăng khả năng linh hoạt của tổ chức."}, {"chapter_slug": "chuong-3", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhà sản xuất mua 90% nguyên liệu từ một công ty duy nhất. Biện pháp quản trị rủi ro phù hợp nhất là:", "option_a": "Tăng tỷ lệ mua lên 100%", "option_b": "Tìm thêm nguồn cung thay thế", "option_c": "Ngừng theo dõi nhà cung cấp", "option_d": "Giảm thông tin thị trường", "correct_option": "B", "explanation": "Tìm thêm nguồn cung giúp giảm mức độ phụ thuộc và khả năng gián đoạn hoạt động.", "topic": "Mục 3.6.5. Giảm sự phụ thuộc vào một nguồn lực duy nhất."}, {"chapter_slug": "chuong-3", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp thường xuyên gặp đại diện hiệp hội ngành, trao đổi với nhà cung cấp và tổ chức đối thoại với cộng đồng địa phương. Mục đích chủ yếu là:", "option_a": "Xây dựng quan hệ với các lực lượng môi trường", "option_b": "Loại bỏ toàn bộ bất trắc", "option_c": "Loại bỏ khách hàng", "option_d": "Tăng chuyên môn hóa công việc", "correct_option": "A", "explanation": "Xây dựng quan hệ giúp tăng thông tin, giảm xung đột và tạo điều kiện phối hợp với các bên có liên quan.", "topic": "Mục 3.6.6. Xây dựng quan hệ với các bên trong môi trường."}, {"chapter_slug": "chuong-3", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp thấy doanh số giảm và lập tức kết luận nhân viên bán hàng yếu mà không kiểm tra thay đổi nhu cầu, giá đối thủ hay tình hình kinh tế. Sai lầm lớn nhất là:", "option_a": "Không xem xét đầy đủ các yếu tố môi trường", "option_b": "Có quá nhiều dữ liệu", "option_c": "Quá chú trọng khách hàng", "option_d": "Quá linh hoạt", "correct_option": "A", "explanation": "Kết quả tổ chức có thể chịu tác động đồng thời của nhiều yếu tố bên trong và bên ngoài. Nhà quản trị phải phân tích môi trường trước khi kết luận nguyên nhân.", "topic": "Mục 1.3 và Mục 3.7. Quy trình quản trị môi trường."}, {"chapter_slug": "chuong-3", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp thực hiện quy trình: theo dõi xu hướng → xác định nguy cơ → chuẩn bị phương án → thực hiện → tiếp tục kiểm tra môi trường. Cách làm này thể hiện:", "option_a": "Quản trị môi trường như một quá trình liên tục", "option_b": "Quản trị chỉ dựa trên kinh nghiệm", "option_c": "Doanh nghiệp không cần thích nghi", "option_d": "Tập trung hoàn toàn vào môi trường nội bộ", "correct_option": "A", "explanation": "Quản trị môi trường không phải hoạt động thực hiện một lần. Môi trường liên tục thay đổi nên tổ chức phải liên tục nhận diện, phân tích, phản ứng và điều chỉnh.", "topic": "Mục 3.7. Quy trình quản trị môi trường."}, {"chapter_slug": "chuong-4", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Văn hóa dân tộc được hiểu phù hợp nhất là:", "option_a": "Tính cách giống nhau của mọi công dân", "option_b": "Hệ thống những giá trị, niềm tin và chuẩn mực được chia sẻ tương đối phổ biến trong một xã hội", "option_c": "Chỉ những truyền thống lễ hội", "option_d": "Hệ thống pháp luật của một quốc gia", "correct_option": "B", "explanation": "Văn hóa dân tộc phản ánh những khuynh hướng giá trị, niềm tin và chuẩn mực được chia sẻ ở cấp độ xã hội, chứ không có nghĩa tất cả cá nhân đều giống nhau.", "topic": "Mục 1.1. Khái niệm văn hóa dân tộc."}, {"chapter_slug": "chuong-4", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Mô hình sáu chiều cạnh văn hóa quốc gia gắn với học giả nào?", "option_a": "Edgar Schein", "option_b": "Geert Hofstede", "option_c": "Peter Drucker", "option_d": "Frederick Taylor", "correct_option": "B", "explanation": "Geert Hofstede phát triển mô hình nổi tiếng dùng để so sánh văn hóa quốc gia theo các chiều cạnh khác nhau.", "topic": "Mục 1.4. Các chiều cạnh văn hóa dân tộc."}, {"chapter_slug": "chuong-4", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Chiều cạnh phản ánh mức độ chấp nhận sự phân phối quyền lực không đồng đều là:", "option_a": "Individualism", "option_b": "Power Distance", "option_c": "Indulgence", "option_d": "Long-Term Orientation", "correct_option": "B", "explanation": "Power Distance – khoảng cách quyền lực – liên quan đến mức độ những thành viên ít quyền lực hơn chấp nhận và kỳ vọng sự khác biệt quyền lực.", "topic": "Mục 1.5. Khoảng cách quyền lực."}, {"chapter_slug": "chuong-4", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Văn hóa thiên về tập thể thường nhấn mạnh:", "option_a": "Thành tích cá nhân tuyệt đối", "option_b": "Tính độc lập hoàn toàn", "option_c": "Nhóm và sự gắn kết", "option_d": "Loại bỏ quan hệ xã hội", "correct_option": "C", "explanation": "Collectivism nhấn mạnh bản sắc nhóm, quan hệ và trách nhiệm tập thể.", "topic": "Mục 1.6. Chủ nghĩa cá nhân và chủ nghĩa tập thể."}, {"chapter_slug": "chuong-4", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Ai là học giả nổi bật với mô hình ba cấp độ văn hóa tổ chức?", "option_a": "Edgar Schein", "option_b": "Max Weber", "option_c": "Henri Fayol", "option_d": "Elton Mayo", "correct_option": "A", "explanation": "Schein phân tích văn hóa qua artifacts, espoused values và basic underlying assumptions.", "topic": "Mục 2.2. Ba cấp độ văn hóa tổ chức."}, {"chapter_slug": "chuong-4", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Yếu tố nào thuộc cấp độ Artifacts?", "option_a": "Giả định sâu xa", "option_b": "Logo và nghi lễ", "option_c": "Niềm tin vô thức", "option_d": "Quan niệm nền tảng", "correct_option": "B", "explanation": "Logo, biểu tượng, trang phục và nghi lễ là những biểu hiện hữu hình có thể quan sát.", "topic": "Mục 2.2.1. Artifacts."}, {"chapter_slug": "chuong-4", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Loại văn hóa nào trong Competing Values Framework nhấn mạnh đổi mới và thử nghiệm?", "option_a": "Clan", "option_b": "Adhocracy", "option_c": "Market", "option_d": "Hierarchy", "correct_option": "B", "explanation": "Adhocracy Culture tập trung vào linh hoạt, đổi mới, thử nghiệm và thích nghi.", "topic": "Mục 2.9. Văn hóa sáng tạo."}, {"chapter_slug": "chuong-4", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Loại văn hóa nào nhấn mạnh quy trình, ổn định và kiểm soát?", "option_a": "Hierarchy", "option_b": "Clan", "option_c": "Adhocracy", "option_d": "Market", "correct_option": "A", "explanation": "Hierarchy Culture ưu tiên trật tự, quy trình, độ tin cậy và kiểm soát.", "topic": "Mục 2.11. Văn hóa thứ bậc."}, {"chapter_slug": "chuong-4", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quá trình giúp nhân viên mới học giá trị và chuẩn mực của tổ chức được gọi là:", "option_a": "Xã hội hóa tổ chức", "option_b": "Phân công lao động", "option_c": "Hoạch định", "option_d": "Chuyên môn hóa", "correct_option": "A", "explanation": "Organizational socialization giúp thành viên mới học cách hành động phù hợp với tổ chức.", "topic": "Mục 2.4.4. Xã hội hóa tổ chức."}, {"chapter_slug": "chuong-4", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Một chức năng quan trọng của văn hóa là:", "option_a": "Loại bỏ hoàn toàn nhu cầu quản trị", "option_b": "Định hướng hành vi thành viên", "option_c": "Xóa bỏ sự khác biệt cá nhân", "option_d": "Thay thế mọi quy trình", "correct_option": "B", "explanation": "Văn hóa tạo ra chuẩn mực chung và giúp thành viên nhận biết hành vi nào được chấp nhận.", "topic": "Mục 3.1. Bản chất của tác động."}, {"chapter_slug": "chuong-4", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một tổ chức tuyên bố “sáng tạo là giá trị cốt lõi” nhưng mọi đề xuất mới đều phải qua nhiều cấp phê duyệt. Điều này cho thấy:", "option_a": "Sự phù hợp hoàn toàn giữa văn hóa và cơ cấu", "option_b": "Khoảng cách giữa giá trị tuyên bố và thực tiễn", "option_c": "Văn hóa Clan rất mạnh", "option_d": "Không tồn tại văn hóa tổ chức", "correct_option": "B", "explanation": "Giá trị được tuyên bố chỉ trở thành văn hóa thực sự khi được thể hiện trong hành vi và hệ thống quản trị.", "topic": "Mục 2.2 và Mục 3.4."}, {"chapter_slug": "chuong-4", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác nhau quan trọng giữa văn hóa mạnh và văn hóa phù hợp là:", "option_a": "Văn hóa mạnh luôn phù hợp", "option_b": "Văn hóa phù hợp luôn yếu", "option_c": "Văn hóa mạnh nói về mức độ chia sẻ, còn văn hóa phù hợp nói về sự tương thích với chiến lược và môi trường", "option_d": "Hai khái niệm hoàn toàn giống nhau", "correct_option": "C", "explanation": "Một văn hóa có thể được chia sẻ rất mạnh nhưng nếu các giá trị không phù hợp với môi trường thì vẫn có thể làm giảm hiệu quả.", "topic": "Mục 2.5 và 3.12."}, {"chapter_slug": "chuong-4", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Trong một tổ chức, phòng R&D thích thử nghiệm trong khi phòng tài chính đề cao quy trình chặt chẽ. Đây là biểu hiện của:", "option_a": "Văn hóa dân tộc", "option_b": "Các văn hóa bộ phận", "option_c": "Không có văn hóa", "option_d": "Chỉ có văn hóa yếu", "correct_option": "B", "explanation": "Các bộ phận có chức năng khác nhau có thể phát triển những subculture khác nhau trong cùng một tổ chức.", "topic": "Mục 2.6. Văn hóa chủ đạo và văn hóa bộ phận."}, {"chapter_slug": "chuong-4", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một doanh nghiệp hoạt động trong ngành công nghệ biến động cao nhưng có văn hóa cực kỳ cứng nhắc và tránh thử nghiệm. Vấn đề lớn nhất là:", "option_a": "Văn hóa quá mạnh", "option_b": "Văn hóa không phù hợp với yêu cầu môi trường", "option_c": "Nhân viên có quá nhiều quyền", "option_d": "Doanh nghiệp không có giá trị", "correct_option": "B", "explanation": "Hiệu quả văn hóa phụ thuộc vào mức độ phù hợp giữa văn hóa, chiến lược và môi trường.", "topic": "Mục 3.12. Tác động đến hiệu quả tổ chức."}, {"chapter_slug": "chuong-4", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Nếu doanh nghiệp muốn xây dựng văn hóa làm việc nhóm nhưng phần thưởng chỉ dựa vào cạnh tranh cá nhân, tổ chức đang gặp vấn đề gì?", "option_a": "Hệ thống nhân sự không phù hợp với giá trị văn hóa mong muốn", "option_b": "Khoảng cách quyền lực thấp", "option_c": "Văn hóa quốc gia quá mạnh", "option_d": "Thiếu cơ cấu thứ bậc", "correct_option": "A", "explanation": "Văn hóa phải được hỗ trợ bằng hệ thống đánh giá và khen thưởng tương thích.", "topic": "Mục 3.6. Động lực và quản trị nhân lực."}, {"chapter_slug": "chuong-4", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty có tỷ lệ nghỉ việc thấp, nhân viên rất trung thành và chia sẻ mạnh giá trị “không thay đổi khi chưa thật cần thiết”. Khi công nghệ ngành thay đổi nhanh, công ty phản ứng rất chậm. Nhận định phù hợp nhất là:", "option_a": "Văn hóa mạnh luôn tạo lợi thế", "option_b": "Văn hóa mạnh có thể trở thành rào cản nếu giá trị không còn phù hợp", "option_c": "Công ty có văn hóa yếu", "option_d": "Công ty cần tăng thêm nghi lễ", "correct_option": "B", "explanation": "Mức độ chia sẻ mạnh không bảo đảm hiệu quả. Nếu các giá trị hỗ trợ sự ổn định trong khi môi trường yêu cầu thay đổi nhanh, văn hóa mạnh có thể làm giảm khả năng thích nghi.", "topic": "Mục 2.5 và 3.10."}, {"chapter_slug": "chuong-4", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một nhà quản trị nước ngoài áp dụng phong cách tranh luận trực tiếp và yêu cầu nhân viên thường xuyên phản biện cấp trên. Nhân viên tại chi nhánh lại rất ít phát biểu. Phân tích hợp lý nhất là:", "option_a": "Nhân viên chắc chắn thiếu năng lực", "option_b": "Có thể tồn tại khác biệt về khoảng cách quyền lực và chuẩn mực văn hóa", "option_c": "Công ty không có văn hóa", "option_d": "Đây chỉ là vấn đề tiền lương", "correct_option": "B", "explanation": "Kỳ vọng về việc phản biện người có quyền lực có thể khác nhau giữa các nền văn hóa. Nhà quản trị cần xem xét bối cảnh trước khi kết luận về năng lực hay động lực cá nhân.", "topic": "Mục 1.5 và 1.3."}, {"chapter_slug": "chuong-4", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty ghi “khách hàng là số một” trong mọi tài liệu nhưng thường khen thưởng nhân viên tiết kiệm chi phí ngay cả khi việc đó làm giảm chất lượng phục vụ. Theo mô hình Schein, điều nào quan trọng nhất để đánh giá văn hóa thực tế?", "option_a": "Chỉ đọc tuyên bố giá trị", "option_b": "Quan sát hành vi và những giả định thực sự thể hiện trong quyết định", "option_c": "Chỉ nhìn logo", "option_d": "Chỉ hỏi người sáng lập", "correct_option": "B", "explanation": "Espoused values có thể khác với những giả định và hành vi thực tế. Muốn hiểu văn hóa phải phân tích sâu hơn những gì tổ chức thực sự làm.", "topic": "Mục 2.2. Ba cấp độ văn hóa tổ chức."}, {"chapter_slug": "chuong-4", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty muốn đổi từ văn hóa kiểm soát sang văn hóa đổi mới. Công ty chỉ thay slogan thành “Hãy sáng tạo hơn”. Kết quả gần như không thay đổi. Nguyên nhân hợp lý nhất là:", "option_a": "Văn hóa chỉ cần thay bằng khẩu hiệu khác", "option_b": "Các hệ thống, hành vi lãnh đạo và cơ chế khen thưởng chưa được thay đổi", "option_c": "Tổ chức không nên thay đổi văn hóa", "option_d": "Mọi nhân viên đều chống đổi mới", "correct_option": "B", "explanation": "Thay đổi văn hóa đòi hỏi sự nhất quán giữa lãnh đạo, hệ thống nhân sự, quy trình và hành vi, chứ không chỉ là thông điệp truyền thông.", "topic": "Mục 3.13. Quản trị và thay đổi văn hóa."}, {"chapter_slug": "chuong-4", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một nền văn hóa “kết quả bằng mọi giá” giúp doanh số tăng nhanh nhưng đồng thời xuất hiện hành vi che giấu sai phạm. Kết luận phù hợp nhất là:", "option_a": "Văn hóa càng cạnh tranh càng tốt", "option_b": "Văn hóa có thể tạo động lực mạnh nhưng cũng có thể khuyến khích hành vi phi đạo đức nếu giá trị bị lệch", "option_c": "Văn hóa không ảnh hưởng đạo đức", "option_d": "Chỉ cần tăng mục tiêu bán hàng", "correct_option": "B", "explanation": "Văn hóa tạo ra chuẩn mực về điều được coi là chấp nhận được. Nếu tổ chức chỉ khen thưởng kết quả mà bỏ qua phương thức đạt kết quả, hành vi sai có thể được củng cố.", "topic": "Mục 3.11. Tác động đến đạo đức."}, {"chapter_slug": "chuong-4", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty đa quốc gia nhận thấy nhân viên ở chi nhánh A thường chờ trưởng phòng quyết định, trong khi nhân viên ở chi nhánh B chủ động tranh luận với cấp trên. Sự khác biệt này có thể liên quan rõ nhất đến:", "option_a": "Khoảng cách quyền lực", "option_b": "Quản trị khoa học", "option_c": "Phân công lao động", "option_d": "Văn hóa Market", "correct_option": "A", "explanation": "Power Distance ảnh hưởng đến mức độ chấp nhận chênh lệch quyền lực và kỳ vọng về quan hệ cấp trên – cấp dưới.", "topic": "Mục 1.5. Khoảng cách quyền lực."}, {"chapter_slug": "chuong-4", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp muốn tăng động lực bằng thưởng cá nhân rất cao, nhưng nhân viên lại coi trọng thành tích của nhóm và cảm thấy hệ thống này gây cạnh tranh nội bộ. Yếu tố văn hóa nào cần được xem xét?", "option_a": "Individualism – Collectivism", "option_b": "Power Distance", "option_c": "Long-Term Orientation", "option_d": "Indulgence", "correct_option": "A", "explanation": "Trong môi trường thiên về tập thể, hệ thống khen thưởng chỉ dựa trên cá nhân có thể không phù hợp với các giá trị nhóm.", "topic": "Mục 1.6. Chủ nghĩa cá nhân – tập thể."}, {"chapter_slug": "chuong-4", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty rất khó triển khai cách làm mới vì nhân viên luôn yêu cầu quy trình chi tiết trước khi thử nghiệm. Điều này có thể liên quan đến:", "option_a": "Mức né tránh bất định cao", "option_b": "Khoảng cách quyền lực thấp", "option_c": "Văn hóa Clan", "option_d": "Chủ nghĩa cá nhân cao", "correct_option": "A", "explanation": "Né tránh bất định cao thường đi kèm nhu cầu lớn hơn đối với sự rõ ràng, quy tắc và khả năng dự đoán.", "topic": "Mục 1.8. Né tránh bất định."}, {"chapter_slug": "chuong-4", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp chấp nhận lợi nhuận thấp trong vài năm để đầu tư mạnh vào công nghệ và năng lực tương lai. Điều này gần với:", "option_a": "Định hướng dài hạn", "option_b": "Khoảng cách quyền lực", "option_c": "Né tránh bất định", "option_d": "Văn hóa Hierarchy", "correct_option": "A", "explanation": "Định hướng dài hạn nhấn mạnh khả năng chuẩn bị cho tương lai, kiên trì và đầu tư vào kết quả lâu dài.", "topic": "Mục 1.9. Định hướng dài hạn – ngắn hạn."}, {"chapter_slug": "chuong-4", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên mới nhận thấy mọi người đều gọi tổng giám đốc bằng tên riêng, văn phòng không có phòng riêng cho lãnh đạo và nhân viên thường xuyên tranh luận trực tiếp trong họp. Những dấu hiệu quan sát được này thuộc:", "option_a": "Artifacts", "option_b": "Basic Assumptions", "option_c": "Môi trường kinh tế", "option_d": "Văn hóa dân tộc duy nhất", "correct_option": "A", "explanation": "Cách bố trí không gian, cách xưng hô và hành vi trong cuộc họp là những biểu hiện hữu hình của văn hóa.", "topic": "Mục 2.2.1. Artifacts."}, {"chapter_slug": "chuong-4", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty tuyên bố “an toàn là số một”, nhưng quản lý thường yêu cầu nhân viên bỏ qua bước kiểm tra để giao hàng nhanh hơn. Điều này thể hiện:", "option_a": "Sự nhất quán cao", "option_b": "Khoảng cách giữa giá trị tuyên bố và hành vi thực tế", "option_c": "Văn hóa mạnh tích cực", "option_d": "Xã hội hóa hiệu quả", "correct_option": "B", "explanation": "Giá trị tuyên bố chỉ có ý nghĩa nếu hành vi quản lý và quyết định thực tế phù hợp với nó.", "topic": "Mục 2.2.2 và 3.11."}, {"chapter_slug": "chuong-4", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một câu chuyện về người sáng lập từng tự mình giao sản phẩm cho khách giữa đêm thường xuyên được kể cho nhân viên mới để nhấn mạnh tinh thần phục vụ. Đây là:", "option_a": "Một phương tiện truyền văn hóa", "option_b": "Một yếu tố kinh tế", "option_c": "Một chính sách tài chính", "option_d": "Một loại cơ cấu", "correct_option": "A", "explanation": "Câu chuyện về người sáng lập có thể truyền tải những giá trị mà tổ chức coi trọng.", "topic": "Mục 2.3. Các biểu hiện của văn hóa tổ chức."}, {"chapter_slug": "chuong-4", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp tuyển người có chuyên môn tốt nhưng đồng thời đánh giá rất kỹ mức độ phù hợp với giá trị “hợp tác và minh bạch”. Hoạt động này góp phần:", "option_a": "Duy trì văn hóa thông qua tuyển chọn", "option_b": "Loại bỏ văn hóa", "option_c": "Giảm xã hội hóa", "option_d": "Làm văn hóa yếu đi", "correct_option": "A", "explanation": "Tuyển chọn người phù hợp với các giá trị quan trọng là một cách duy trì văn hóa tổ chức.", "topic": "Mục 2.4.3. Tuyển chọn nhân viên."}, {"chapter_slug": "chuong-4", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty tổ chức chương trình hội nhập một tháng để nhân viên mới học lịch sử, giá trị, cách phối hợp và những hành vi được mong đợi. Đây là:", "option_a": "Xã hội hóa tổ chức", "option_b": "Market Culture", "option_c": "Power Distance", "option_d": "Kiểm soát tài chính", "correct_option": "A", "explanation": "Chương trình giúp thành viên mới học cách hành động và thích nghi với tổ chức chính là quá trình organizational socialization.", "topic": "Mục 2.4.4. Xã hội hóa tổ chức."}, {"chapter_slug": "chuong-4", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty coi nhân viên như thành viên trong gia đình, nhấn mạnh cố vấn, hợp tác và phát triển con người. Văn hóa này gần nhất với:", "option_a": "Clan", "option_b": "Market", "option_c": "Hierarchy", "option_d": "Adhocracy", "correct_option": "A", "explanation": "Clan Culture chú trọng quan hệ, cam kết, làm việc nhóm và phát triển con người.", "topic": "Mục 2.8. Văn hóa gia đình."}, {"chapter_slug": "chuong-4", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một startup khuyến khích nhân viên thử ý tưởng mới, chấp nhận một số thất bại và thường xuyên điều chỉnh sản phẩm. Đây là:", "option_a": "Adhocracy Culture", "option_b": "Hierarchy Culture", "option_c": "Market Culture thuần túy", "option_d": "Văn hóa yếu", "correct_option": "A", "explanation": "Adhocracy ưu tiên đổi mới, linh hoạt, thử nghiệm và thích nghi.", "topic": "Mục 2.9. Văn hóa sáng tạo."}, {"chapter_slug": "chuong-4", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty yêu cầu từng bộ phận đạt chỉ tiêu thị phần, liên tục so sánh thành tích với đối thủ và thưởng cao cho kết quả vượt mục tiêu. Đây gần nhất với:", "option_a": "Market Culture", "option_b": "Clan Culture", "option_c": "Hierarchy Culture", "option_d": "Văn hóa bộ phận", "correct_option": "A", "explanation": "Market Culture tập trung mạnh vào cạnh tranh, thành tích và kết quả bên ngoài.", "topic": "Mục 2.10. Văn hóa thị trường."}, {"chapter_slug": "chuong-4", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một bệnh viện quy định rất rõ quy trình dùng thuốc, lưu hồ sơ và kiểm soát an toàn. Văn hóa phù hợp với hoạt động này có nhiều đặc điểm của:", "option_a": "Hierarchy Culture", "option_b": "Adhocracy Culture", "option_c": "Clan Culture duy nhất", "option_d": "Không cần văn hóa", "correct_option": "A", "explanation": "Hierarchy Culture phù hợp với những hoạt động đòi hỏi độ chính xác, quy trình và tính ổn định cao.", "topic": "Mục 2.11. Văn hóa thứ bậc."}, {"chapter_slug": "chuong-4", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty khuyến khích làm việc nhóm nhưng trưởng phòng luôn tự quyết mọi vấn đề và hiếm khi cho nhân viên phát biểu. Điều này sẽ:", "option_a": "Củng cố văn hóa tham gia", "option_b": "Làm giảm tính tin cậy của thông điệp văn hóa", "option_c": "Không ảnh hưởng gì", "option_d": "Tự động tạo văn hóa Clan", "correct_option": "B", "explanation": "Hành vi lãnh đạo có vai trò mạnh trong việc hình thành văn hóa. Nếu lời nói và hành động mâu thuẫn, nhân viên thường tin vào hành động.", "topic": "Mục 2.4.2 và 3.5."}, {"chapter_slug": "chuong-4", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty nói rằng “chất lượng quan trọng hơn tốc độ” nhưng nhân viên chỉ được thưởng theo số lượng sản phẩm hoàn thành. Hệ quả có khả năng nhất là:", "option_a": "Nhân viên ưu tiên số lượng hơn chất lượng", "option_b": "Văn hóa tự động trở nên mạnh", "option_c": "Nhân viên không quan tâm phần thưởng", "option_d": "Hệ thống đánh giá không liên quan văn hóa", "correct_option": "A", "explanation": "Những hành vi được đo lường và khen thưởng thường gửi tín hiệu rất mạnh về điều tổ chức thực sự coi trọng.", "topic": "Mục 3.6. Tác động đến động lực và quản trị nhân lực."}, {"chapter_slug": "chuong-4", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên phát hiện lỗi nghiêm trọng nhưng không báo cáo vì những người báo lỗi trước đây thường bị quản lý trách mắng. Vấn đề chính nằm ở:", "option_a": "Văn hóa giao tiếp và an toàn khi nêu vấn đề", "option_b": "Môi trường kinh tế", "option_c": "Định hướng dài hạn", "option_d": "Văn hóa quốc gia duy nhất", "correct_option": "A", "explanation": "Nếu văn hóa trừng phạt người đưa tin xấu, thông tin quan trọng có thể bị che giấu, làm giảm chất lượng quyết định quản trị.", "topic": "Mục 3.7. Tác động đến giao tiếp."}, {"chapter_slug": "chuong-4", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp không có người giám sát trực tiếp tại mọi vị trí nhưng nhân viên vẫn tuân thủ rất tốt nguyên tắc an toàn vì “ở đây ai cũng làm vậy”. Điều này thể hiện:", "option_a": "Văn hóa đang thực hiện chức năng kiểm soát xã hội", "option_b": "Không tồn tại quản trị", "option_c": "Nhân viên không có tự chủ", "option_d": "Văn hóa yếu", "correct_option": "A", "explanation": "Các chuẩn mực được chia sẻ mạnh có thể khiến thành viên tự điều chỉnh hành vi mà không cần kiểm soát trực tiếp liên tục.", "topic": "Mục 3.8. Tác động đến kiểm soát."}, {"chapter_slug": "chuong-4", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty muốn đổi mới nhưng nhân viên sợ thử nghiệm vì mọi sai sót đều bị ghi vào đánh giá cuối năm. Biện pháp phù hợp nhất là:", "option_a": "Chỉ yêu cầu nhân viên sáng tạo hơn", "option_b": "Điều chỉnh cơ chế đánh giá và cách xử lý sai lầm hợp lý", "option_c": "Tăng hình phạt", "option_d": "Giảm trao đổi thông tin", "correct_option": "B", "explanation": "Muốn xây dựng văn hóa đổi mới, hệ thống đánh giá phải không khiến nhân viên sợ mọi thử nghiệm.", "topic": "Mục 3.9 và 3.13."}, {"chapter_slug": "chuong-4", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty thay CEO và muốn xây dựng văn hóa minh bạch. CEO mới công khai sai lầm của chính mình, khuyến khích phản biện và thay đổi hệ thống thưởng để ghi nhận người phát hiện vấn đề. Điều này thể hiện:", "option_a": "Thay đổi văn hóa bằng hành vi lãnh đạo và hệ thống hỗ trợ", "option_b": "Chỉ thay đổi khẩu hiệu", "option_c": "Không liên quan văn hóa", "option_d": "Chỉ thay đổi cơ cấu", "correct_option": "A", "explanation": "Thay đổi văn hóa cần sự nhất quán giữa hành vi lãnh đạo và các hệ thống quản trị.", "topic": "Mục 3.13. Quản trị và thay đổi văn hóa."}, {"chapter_slug": "chuong-4", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty rất thành công trong nhiều năm nhờ văn hóa chú trọng quy trình. Khi ngành chuyển sang công nghệ mới, chính văn hóa đó làm nhân viên phản đối thay đổi. Bài học quan trọng nhất là:", "option_a": "Một văn hóa từng tạo lợi thế vẫn có thể trở thành rào cản khi môi trường thay đổi", "option_b": "Văn hóa mạnh luôn tốt", "option_c": "Công ty không nên có văn hóa", "option_d": "Quy trình luôn làm tổ chức thất bại", "correct_option": "A", "explanation": "Văn hóa chỉ tạo lợi thế khi còn phù hợp với chiến lược và môi trường. Giá trị từng giúp tổ chức thành công có thể trở thành lực cản nếu điều kiện thay đổi.", "topic": "Mục 3.10 và 3.12."}, {"chapter_slug": "chuong-5", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Thông tin quản trị được hiểu phù hợp nhất là:", "option_a": "Mọi dữ liệu được lưu trong máy tính", "option_b": "Dữ liệu đã được xử lý và có ý nghĩa phục vụ hoạt động quản trị", "option_c": "Chỉ những báo cáo tài chính", "option_d": "Chỉ thông tin từ bên ngoài", "correct_option": "B", "explanation": "Thông tin quản trị là dữ liệu đã được xử lý và đặt trong bối cảnh để hỗ trợ các chức năng quản trị và ra quyết định.", "topic": "Mục 1.1. Khái niệm thông tin quản trị."}, {"chapter_slug": "chuong-5", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Điểm khác biệt cơ bản giữa dữ liệu và thông tin là:", "option_a": "Dữ liệu luôn chính xác hơn", "option_b": "Thông tin là dữ liệu đã được xử lý để tạo ra ý nghĩa", "option_c": "Dữ liệu chỉ tồn tại bên ngoài", "option_d": "Thông tin không cần dữ liệu", "correct_option": "B", "explanation": "Dữ liệu là các sự kiện ban đầu; sau khi được xử lý và đặt trong bối cảnh mới tạo thành thông tin có ích.", "topic": "Mục 1.2. Phân biệt dữ liệu và thông tin."}, {"chapter_slug": "chuong-5", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Thuộc tính nào quan trọng đối với thông tin quản trị?", "option_a": "Chính xác", "option_b": "Càng dài càng tốt", "option_c": "Càng nhiều càng tốt", "option_d": "Chỉ sử dụng dữ liệu quá khứ", "correct_option": "A", "explanation": "Thông tin chất lượng cần chính xác, phù hợp, đầy đủ, kịp thời và có thể tiếp cận.", "topic": "Mục 1.5. Yêu cầu đối với thông tin quản trị."}, {"chapter_slug": "chuong-5", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quyết định quản trị là:", "option_a": "Lựa chọn một phương án hành động nhằm đạt mục tiêu", "option_b": "Mọi hoạt động của nhân viên", "option_c": "Chỉ quyết định của tổng giám đốc", "option_d": "Việc thu thập dữ liệu", "correct_option": "A", "explanation": "Bản chất của quyết định là lựa chọn một phương án trong số những phương án có thể có.", "topic": "Mục 2.1. Khái niệm quyết định quản trị."}, {"chapter_slug": "chuong-5", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quyết định lặp lại và có thể sử dụng quy tắc có sẵn được gọi là:", "option_a": "Quyết định không theo chương trình", "option_b": "Quyết định theo chương trình", "option_c": "Quyết định bất định", "option_d": "Quyết định chiến lược", "correct_option": "B", "explanation": "Programmed decision áp dụng cho các vấn đề tương đối quen thuộc và lặp lại.", "topic": "Mục 2.4.1. Quyết định theo chương trình."}, {"chapter_slug": "chuong-5", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quyết định mới, ít cấu trúc và đòi hỏi nhiều phán đoán là:", "option_a": "Programmed decision", "option_b": "Nonprogrammed decision", "option_c": "Quyết định chắc chắn", "option_d": "Quyết định tác nghiệp định kỳ", "correct_option": "B", "explanation": "Nonprogrammed decisions xuất hiện đối với vấn đề mới hoặc phức tạp, không có sẵn quy tắc xử lý.", "topic": "Mục 2.4.2. Quyết định không theo chương trình."}, {"chapter_slug": "chuong-5", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Trong điều kiện nào nhà quản trị có thể gán xác suất cho các kết quả?", "option_a": "Chắc chắn", "option_b": "Rủi ro", "option_c": "Bất định hoàn toàn", "option_d": "Không có thông tin", "correct_option": "B", "explanation": "Điều kiện rủi ro có đặc trưng là chưa biết kết quả chắc chắn nhưng có thể ước lượng xác suất.", "topic": "Mục 2.6.2. Quyết định trong điều kiện rủi ro."}, {"chapter_slug": "chuong-5", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Hợp lý giới hạn gắn liền với học giả nào?", "option_a": "Henri Fayol", "option_b": "Herbert A. Simon", "option_c": "Elton Mayo", "option_d": "Peter Senge", "correct_option": "B", "explanation": "Herbert Simon phát triển tư tưởng bounded rationality trong nghiên cứu quá trình ra quyết định.", "topic": "Mục 2.9. Hợp lý giới hạn."}, {"chapter_slug": "chuong-5", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Công cụ nào phù hợp để tạo ra số lượng lớn ý tưởng mà chưa phê bình ngay?", "option_a": "Brainstorming", "option_b": "Break-even analysis", "option_c": "Pay-off matrix", "option_d": "Decision tree", "correct_option": "A", "explanation": "Brainstorming tập trung vào tạo nhiều ý tưởng trước khi đánh giá.", "topic": "Mục 3.7. Brainstorming."}, {"chapter_slug": "chuong-5", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Bước cuối trong quy trình ra quyết định là:", "option_a": "Xác định vấn đề", "option_b": "Tạo phương án", "option_c": "Đánh giá kết quả quyết định", "option_d": "Xác định tiêu chí", "correct_option": "C", "explanation": "Sau khi triển khai, nhà quản trị cần đánh giá kết quả và rút kinh nghiệm.", "topic": "Mục 2.7.7. Đánh giá kết quả."}, {"chapter_slug": "chuong-5", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một báo cáo rất chính xác nhưng được gửi sau khi nhà quản trị đã phải quyết định. Thuộc tính nào của thông tin bị hạn chế?", "option_a": "Tính kịp thời", "option_b": "Tính chính xác", "option_c": "Tính đầy đủ", "option_d": "Tính bảo mật", "correct_option": "A", "explanation": "Thông tin chỉ có giá trị nếu đến vào thời điểm người quản trị còn có khả năng sử dụng nó.", "topic": "Mục 1.5.3. Kịp thời."}, {"chapter_slug": "chuong-5", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một quản lý cần lựa chọn nhà cung cấp dựa trên giá, chất lượng, thời gian giao hàng và uy tín. Công cụ phù hợp nhất là:", "option_a": "Ma trận đánh giá có trọng số", "option_b": "Brainstorming", "option_c": "Delphi", "option_d": "Satisficing", "correct_option": "A", "explanation": "Khi cần so sánh nhiều phương án trên nhiều tiêu chí có mức độ quan trọng khác nhau, ma trận có trọng số phù hợp.", "topic": "Mục 3.1. Ma trận đánh giá có trọng số."}, {"chapter_slug": "chuong-5", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Doanh nghiệp biết có 60% khả năng thị trường tăng trưởng và 40% khả năng thị trường suy giảm. Doanh nghiệp đang ra quyết định trong điều kiện:", "option_a": "Chắc chắn", "option_b": "Rủi ro", "option_c": "Bất định hoàn toàn", "option_d": "Không có phương án", "correct_option": "B", "explanation": "Nhà quản trị có thể gán xác suất cho các trạng thái thị trường nên đây là quyết định dưới rủi ro.", "topic": "Mục 2.6.2. Điều kiện rủi ro."}, {"chapter_slug": "chuong-5", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác biệt quan trọng giữa brainstorming và NGT là:", "option_a": "Brainstorming chỉ dùng một người", "option_b": "NGT tạo điều kiện cho các thành viên suy nghĩ độc lập và sau đó xếp hạng phương án", "option_c": "Brainstorming luôn cho quyết định cuối cùng", "option_d": "NGT không sử dụng nhóm", "correct_option": "B", "explanation": "NGT có cấu trúc hơn và hạn chế ảnh hưởng của các thành viên chi phối thông qua việc tạo ý tưởng độc lập và xếp hạng.", "topic": "Mục 3.7 và 3.8."}, {"chapter_slug": "chuong-5", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một nhà quản trị chọn phương án đầu tiên đáp ứng đầy đủ các tiêu chuẩn tối thiểu thay vì tiếp tục tìm kiếm phương án tốt nhất. Đây là:", "option_a": "Optimizing", "option_b": "Satisficing", "option_c": "Groupthink", "option_d": "Escalation of commitment", "correct_option": "B", "explanation": "Satisficing là lựa chọn một phương án đủ tốt trong điều kiện nguồn lực nhận thức và thời gian có giới hạn.", "topic": "Mục 2.10. Satisficing."}, {"chapter_slug": "chuong-5", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Doanh thu giảm 20%. Giám đốc ngay lập tức sa thải nhân viên bán hàng nhưng sau đó phát hiện nguyên nhân chính là sản phẩm lỗi thời. Sai lầm lớn nhất nằm ở:", "option_a": "Thiếu brainstorming", "option_b": "Xác định sai vấn đề và nhầm triệu chứng với nguyên nhân", "option_c": "Không dùng cây quyết định", "option_d": "Không áp dụng Delphi", "correct_option": "B", "explanation": "Doanh thu giảm là triệu chứng. Nếu chưa xác định nguyên nhân đã đưa ra giải pháp, nhà quản trị dễ giải quyết sai vấn đề.", "topic": "Mục 2.7.1 và 4.2. Xác định đúng vấn đề."}, {"chapter_slug": "chuong-5", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty đã đầu tư 30 tỷ vào dự án không hiệu quả. Ban lãnh đạo tiếp tục đầu tư thêm chủ yếu vì “đã bỏ quá nhiều tiền nên không thể dừng”. Đây là:", "option_a": "Confirmation bias", "option_b": "Escalation of commitment", "option_c": "Brainstorming", "option_d": "Satisficing", "correct_option": "B", "explanation": "Leo thang cam kết xảy ra khi người ra quyết định tiếp tục theo đuổi lựa chọn kém hiệu quả vì những nguồn lực đã đầu tư trong quá khứ.", "topic": "Mục 4.8. Tránh leo thang cam kết."}, {"chapter_slug": "chuong-5", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một giám đốc tin rằng dự án của mình chắc chắn thành công và chỉ đọc các báo cáo ủng hộ dự án, đồng thời bỏ qua các cảnh báo. Đây là:", "option_a": "Confirmation bias", "option_b": "Cost-benefit analysis", "option_c": "Delphi", "option_d": "Rational model", "correct_option": "A", "explanation": "Thiên kiến xác nhận làm người ra quyết định tìm kiếm và chú ý nhiều hơn tới thông tin phù hợp với niềm tin có sẵn.", "topic": "Mục 4.7. Tránh thiên kiến xác nhận."}, {"chapter_slug": "chuong-5", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một nhóm lãnh đạo nhanh chóng đồng thuận với CEO dù một số thành viên có nghi ngờ nhưng không dám phát biểu. Nguy cơ lớn nhất là:", "option_a": "Groupthink", "option_b": "Information overload", "option_c": "Programmed decision", "option_d": "Break-even analysis", "correct_option": "A", "explanation": "Mong muốn duy trì đồng thuận khiến thành viên tự kiểm duyệt và không phản biện có thể tạo ra groupthink.", "topic": "Mục 4.10. Hạn chế groupthink."}, {"chapter_slug": "chuong-5", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một quyết định có quy trình phân tích rất tốt nhưng thất bại vì một sự kiện thiên tai hoàn toàn bất ngờ. Nhận định phù hợp nhất là:", "option_a": "Quyết định chắc chắn là kém chất lượng", "option_b": "Chất lượng của quá trình quyết định và kết quả thực tế cần được phân biệt", "option_c": "Nhà quản trị phải dự báo được mọi sự kiện", "option_d": "Mọi quyết định thất bại đều do thiếu thông tin", "correct_option": "B", "explanation": "Một quá trình quyết định tốt chỉ nâng cao xác suất đạt kết quả mong muốn; nó không thể loại bỏ hoàn toàn rủi ro và bất định.", "topic": "Mục 4.1. Khái niệm quyết định quản trị hiệu quả."}, {"chapter_slug": "chuong-5", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một siêu thị có hàng triệu dòng dữ liệu bán hàng nhưng quản lý không biết sản phẩm nào đang giảm doanh số. Vấn đề chính là:", "option_a": "Có quá ít dữ liệu", "option_b": "Dữ liệu chưa được xử lý thành thông tin hữu ích", "option_c": "Không có khách hàng", "option_d": "Thiếu phân quyền", "correct_option": "B", "explanation": "Dữ liệu chỉ tạo giá trị khi được xử lý và phân tích để giúp nhà quản trị hiểu tình hình.", "topic": "Mục 1.2. Dữ liệu và thông tin."}, {"chapter_slug": "chuong-5", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một trưởng phòng nhận 25 báo cáo mỗi ngày nhưng chỉ có ba báo cáo thực sự liên quan đến quyết định của mình. Vấn đề gần nhất là:", "option_a": "Quá tải thông tin", "option_b": "Bounded rationality không tồn tại", "option_c": "Thiếu dữ liệu", "option_d": "Quyết định chắc chắn", "correct_option": "A", "explanation": "Lượng thông tin vượt quá khả năng chú ý và xử lý có thể làm giảm hiệu quả ra quyết định.", "topic": "Mục 1.7. Quá tải thông tin."}, {"chapter_slug": "chuong-5", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Doanh nghiệp tự động đặt thêm nguyên liệu khi tồn kho xuống dưới 500 đơn vị. Đây là ví dụ về:", "option_a": "Nonprogrammed decision", "option_b": "Programmed decision", "option_c": "Uncertainty", "option_d": "Delphi", "correct_option": "B", "explanation": "Quyết định được thực hiện lặp lại theo một quy tắc xác định trước.", "topic": "Mục 2.4.1. Quyết định theo chương trình."}, {"chapter_slug": "chuong-5", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một tập đoàn lần đầu cân nhắc mua lại một đối thủ lớn. Đây chủ yếu là:", "option_a": "Quyết định theo chương trình", "option_b": "Quyết định không theo chương trình", "option_c": "Quyết định tác nghiệp thường xuyên", "option_d": "Quyết định định kỳ", "correct_option": "B", "explanation": "Mua lại doanh nghiệp là vấn đề mới, phức tạp và cần nhiều phán đoán chiến lược.", "topic": "Mục 2.4.2. Quyết định không theo chương trình."}, {"chapter_slug": "chuong-5", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhà hàng biết chính xác giá nguyên liệu, doanh thu và chi phí của hai phương án mua thiết bị. Đây gần nhất với điều kiện:", "option_a": "Chắc chắn", "option_b": "Rủi ro", "option_c": "Bất định", "option_d": "Groupthink", "correct_option": "A", "explanation": "Khi các phương án và kết quả tương đối rõ ràng, quyết định được thực hiện trong điều kiện gần chắc chắn.", "topic": "Mục 2.6.1. Chắc chắn."}, {"chapter_slug": "chuong-5", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty có thể ước lượng xác suất thành công của sản phẩm mới từ dữ liệu 20 lần ra mắt trước. Công cụ phù hợp là:", "option_a": "Expected value", "option_b": "Chỉ brainstorming", "option_c": "Chỉ intuition", "option_d": "Unity of Command", "correct_option": "A", "explanation": "Khi có xác suất và kết quả, giá trị kỳ vọng có thể hỗ trợ so sánh các lựa chọn.", "topic": "Mục 3.3. Xác suất và giá trị kỳ vọng."}, {"chapter_slug": "chuong-5", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp phải quyết định đầu tư ngay vào một công nghệ hoàn toàn mới nhưng chưa có dữ liệu đủ đáng tin để xác định khả năng thành công. Đây là:", "option_a": "Certainty", "option_b": "Risk có xác suất rõ", "option_c": "Uncertainty", "option_d": "Programmed decision", "correct_option": "C", "explanation": "Không có đủ cơ sở để gán xác suất tin cậy cho các kết quả nên đây là điều kiện bất định.", "topic": "Mục 2.6.3. Bất định."}, {"chapter_slug": "chuong-5", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty muốn chọn vị trí cửa hàng dựa trên tiền thuê, lưu lượng khách, khoảng cách và cạnh tranh. Công cụ phù hợp nhất là:", "option_a": "Ma trận có trọng số", "option_b": "Brainstorming duy nhất", "option_c": "Satisficing bắt buộc", "option_d": "Groupthink", "correct_option": "A", "explanation": "Vấn đề có nhiều tiêu chí nên ma trận có trọng số giúp cấu trúc so sánh.", "topic": "Mục 3.1. Ma trận có trọng số."}, {"chapter_slug": "chuong-5", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp có ba phương án đầu tư, mỗi phương án cho kết quả khác nhau khi thị trường tăng hoặc giảm. Công cụ nào giúp trình bày các kết quả này rõ nhất?", "option_a": "Pay-off matrix", "option_b": "NGT", "option_c": "Brainstorming", "option_d": "Xã hội hóa", "correct_option": "A", "explanation": "Ma trận kết quả thể hiện lợi ích của mỗi phương án dưới các trạng thái khác nhau của môi trường.", "topic": "Mục 3.2. Pay-off matrix."}, {"chapter_slug": "chuong-5", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một dự án có nhiều bước, sau mỗi bước có thể xuất hiện các kết quả và xác suất khác nhau. Công cụ phù hợp nhất là:", "option_a": "Decision tree", "option_b": "Brainstorming", "option_c": "Delphi duy nhất", "option_d": "Break-even đơn thuần", "correct_option": "A", "explanation": "Cây quyết định phù hợp với các quyết định có nhiều giai đoạn và nhánh kết quả.", "topic": "Mục 3.4. Cây quyết định."}, {"chapter_slug": "chuong-5", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp muốn biết cần bán tối thiểu bao nhiêu sản phẩm để tổng doanh thu bằng tổng chi phí. Công cụ phù hợp là:", "option_a": "Break-even analysis", "option_b": "Delphi", "option_c": "NGT", "option_d": "Brainstorming", "correct_option": "A", "explanation": "Phân tích hòa vốn xác định mức sản lượng hoặc doanh thu tại đó doanh nghiệp không lãi cũng không lỗ.", "topic": "Mục 3.5. Phân tích hòa vốn."}, {"chapter_slug": "chuong-5", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhóm phát triển sản phẩm muốn tạo thật nhiều ý tưởng mới trong 30 phút và yêu cầu chưa đánh giá bất kỳ ý tưởng nào. Đây là:", "option_a": "Brainstorming", "option_b": "Delphi", "option_c": "Decision tree", "option_d": "Pay-off matrix", "correct_option": "A", "explanation": "Đây là nguyên tắc điển hình của brainstorming.", "topic": "Mục 3.7. Brainstorming."}, {"chapter_slug": "chuong-5", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trong cuộc họp, giám đốc thường nói trước nên mọi người có xu hướng đồng ý. Công ty muốn mỗi người trước tiên tự viết giải pháp rồi mới thảo luận và bỏ phiếu. Kỹ thuật phù hợp là:", "option_a": "NGT", "option_b": "Break-even", "option_c": "Expected value", "option_d": "DSS", "correct_option": "A", "explanation": "NGT hạn chế sự chi phối bằng việc tạo ý tưởng độc lập trước khi thảo luận.", "topic": "Mục 3.8. Kỹ thuật nhóm danh nghĩa."}, {"chapter_slug": "chuong-5", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp cần ý kiến của 20 chuyên gia ở nhiều quốc gia nhưng muốn tránh việc người có địa vị cao ảnh hưởng trực tiếp đến ý kiến người khác. Kỹ thuật phù hợp là:", "option_a": "Delphi", "option_b": "Brainstorming trực tiếp", "option_c": "Break-even", "option_d": "Pay-off matrix", "correct_option": "A", "explanation": "Delphi sử dụng nhiều vòng lấy ý kiến, thường ẩn danh, và không yêu cầu họp trực tiếp.", "topic": "Mục 3.9. Kỹ thuật Delphi."}, {"chapter_slug": "chuong-5", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một hệ thống phần mềm tổng hợp dữ liệu bán hàng, mô phỏng ba kịch bản và hiển thị ảnh hưởng lợi nhuận để giám đốc lựa chọn. Đây là:", "option_a": "Decision Support System", "option_b": "Programmed decision duy nhất", "option_c": "Văn hóa tổ chức", "option_d": "Unity of Command", "correct_option": "A", "explanation": "DSS sử dụng dữ liệu và mô hình để hỗ trợ người ra quyết định phân tích lựa chọn.", "topic": "Mục 3.10. Hệ thống hỗ trợ ra quyết định."}, {"chapter_slug": "chuong-5", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một giám đốc đã tin rằng nhân viên mới rất giỏi nên chỉ chú ý những kết quả tốt và luôn tìm lý do bỏ qua các sai sót. Đây là:", "option_a": "Confirmation bias", "option_b": "Delphi", "option_c": "Cost-benefit analysis", "option_d": "Satisficing", "correct_option": "A", "explanation": "Người quản trị đang chọn lọc thông tin phù hợp với niềm tin sẵn có.", "topic": "Mục 4.7. Thiên kiến xác nhận."}, {"chapter_slug": "chuong-5", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một dự án liên tục thất bại nhưng người quản lý vẫn tăng ngân sách vì sợ thừa nhận quyết định ban đầu sai. Đây là:", "option_a": "Escalation of commitment", "option_b": "Brainstorming", "option_c": "Bounded rationality đơn thuần", "option_d": "Delphi", "correct_option": "A", "explanation": "Tiếp tục đầu tư vào quyết định kém hiệu quả vì cam kết trước đó là leo thang cam kết.", "topic": "Mục 4.8. Leo thang cam kết."}, {"chapter_slug": "chuong-5", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trong ban điều hành, tất cả nhanh chóng đồng ý với tổng giám đốc vì không ai muốn tạo xung đột dù nhiều người nghi ngờ kế hoạch. Biện pháp phù hợp nhất là:", "option_a": "Khuyến khích phản biện và thu thập ý kiến độc lập", "option_b": "Yêu cầu mọi người đồng ý nhanh hơn", "option_c": "Giảm số phương án", "option_d": "Chỉ dùng dữ liệu của CEO", "correct_option": "A", "explanation": "Phản biện độc lập giúp giảm nguy cơ groupthink.", "topic": "Mục 4.10. Hạn chế groupthink."}, {"chapter_slug": "chuong-5", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp chọn phương án lợi nhuận cao nhất nhưng phương án đó có nguy cơ gây hại nghiêm trọng cho khách hàng. Nhà quản trị cần bổ sung yếu tố nào?", "option_a": "Đánh giá đạo đức và tác động đến các bên liên quan", "option_b": "Chỉ tăng trọng số lợi nhuận", "option_c": "Loại bỏ mọi thông tin phi tài chính", "option_d": "Quyết định càng nhanh càng tốt", "correct_option": "A", "explanation": "Hiệu quả quyết định không chỉ bao gồm lợi ích tài chính mà còn phải xem xét hậu quả đạo đức.", "topic": "Mục 4.13. Xem xét đạo đức."}, {"chapter_slug": "chuong-5", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Sau khi triển khai một quyết định, doanh nghiệp đo kết quả, so sánh với mục tiêu, xác định sai lệch và điều chỉnh. Đây là:", "option_a": "Đánh giá sau quyết định và học hỏi", "option_b": "Brainstorming", "option_c": "Xác định vấn đề ban đầu", "option_d": "Programmed decision", "correct_option": "A", "explanation": "Theo dõi kết quả là bước cuối của quá trình ra quyết định, giúp tạo phản hồi cho các quyết định tiếp theo.", "topic": "Mục 4.15. Đánh giá sau quyết định."}, {"chapter_slug": "chuong-6", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Hoạch định được hiểu phù hợp nhất là:", "option_a": "Kiểm tra kết quả sau khi công việc hoàn thành", "option_b": "Xác định mục tiêu và cách thức đạt được mục tiêu", "option_c": "Chỉ phân công công việc cho nhân viên", "option_d": "Chỉ dự báo môi trường", "correct_option": "B", "explanation": "Hoạch định bao gồm việc xác định điều tổ chức muốn đạt và lựa chọn phương án, nguồn lực, thời gian để đạt mục tiêu đó.", "topic": "Mục 1.1. Khái niệm hoạch định."}, {"chapter_slug": "chuong-6", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Kế hoạch khác hoạch định ở điểm nào?", "option_a": "Kế hoạch là quá trình, hoạch định là kết quả", "option_b": "Hai khái niệm hoàn toàn giống nhau", "option_c": "Hoạch định là quá trình, kế hoạch là kết quả cụ thể của quá trình đó", "option_d": "Kế hoạch chỉ dành cho cấp cao", "correct_option": "C", "explanation": "Planning là quá trình xác định mục tiêu và hành động; plan là sản phẩm được tạo ra từ quá trình đó.", "topic": "Mục 1.2. Khái niệm kế hoạch."}, {"chapter_slug": "chuong-6", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Vai trò nào của hoạch định tạo cơ sở trực tiếp cho chức năng kiểm soát?", "option_a": "Xác định mục tiêu và tiêu chuẩn", "option_b": "Tuyển dụng nhân viên", "option_c": "Tạo văn hóa", "option_d": "Xây dựng cơ cấu", "correct_option": "A", "explanation": "Kiểm soát cần so sánh kết quả thực tế với mục tiêu và tiêu chuẩn đã được xác lập trong hoạch định.", "topic": "Mục 1.4.5. Tạo cơ sở cho kiểm soát."}, {"chapter_slug": "chuong-6", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Mục tiêu được hiểu là:", "option_a": "Cách thức thực hiện công việc", "option_b": "Kết quả hoặc trạng thái mong muốn đạt được trong tương lai", "option_c": "Báo cáo về quá khứ", "option_d": "Quy trình bắt buộc", "correct_option": "B", "explanation": "Mục tiêu xác định kết quả mà cá nhân, bộ phận hoặc tổ chức muốn đạt.", "topic": "Mục 2.1. Khái niệm mục tiêu."}, {"chapter_slug": "chuong-6", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Thành phần nào của SMART yêu cầu mục tiêu phải có khả năng đo lường?", "option_a": "Specific", "option_b": "Measurable", "option_c": "Relevant", "option_d": "Time-bound", "correct_option": "B", "explanation": "Measurable yêu cầu có chỉ số hoặc tiêu chuẩn để xác định mức độ hoàn thành mục tiêu.", "topic": "Mục 2.11. Nguyên tắc SMART."}, {"chapter_slug": "chuong-6", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Sứ mệnh chủ yếu trả lời câu hỏi nào?", "option_a": "Công việc hôm nay giao cho ai?", "option_b": "Tổ chức tồn tại để làm gì và tạo giá trị gì?", "option_c": "Nhân viên được nghỉ bao nhiêu ngày?", "option_d": "Ngân sách tháng này là bao nhiêu?", "correct_option": "B", "explanation": "Sứ mệnh thể hiện lý do tồn tại, lĩnh vực hoạt động và giá trị tổ chức muốn tạo ra.", "topic": "Mục 2.3. Sứ mệnh."}, {"chapter_slug": "chuong-6", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Hoạch định chiến lược thường được thực hiện chủ yếu bởi:", "option_a": "Nhà quản trị cấp cao", "option_b": "Chỉ nhân viên tác nghiệp", "option_c": "Khách hàng", "option_d": "Nhà cung cấp", "correct_option": "A", "explanation": "Hoạch định chiến lược liên quan đến định hướng toàn tổ chức nên trách nhiệm chủ yếu thuộc quản trị cấp cao.", "topic": "Mục 3.1. Hoạch định chiến lược."}, {"chapter_slug": "chuong-6", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Loại kế hoạch nào được sử dụng cho các vấn đề lặp lại?", "option_a": "Standing plan", "option_b": "Single-use plan", "option_c": "Strategic objective", "option_d": "Vision", "correct_option": "A", "explanation": "Standing plans được xây dựng để xử lý những tình huống xuất hiện thường xuyên.", "topic": "Mục 3.8. Kế hoạch thường xuyên."}, {"chapter_slug": "chuong-6", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Chính sách, thủ tục và quy tắc thuộc nhóm:", "option_a": "Kế hoạch sử dụng một lần", "option_b": "Kế hoạch thường xuyên", "option_c": "Tầm nhìn", "option_d": "Mục tiêu chiến lược", "correct_option": "B", "explanation": "Đây là những kế hoạch hướng dẫn cách xử lý các vấn đề lặp lại.", "topic": "Mục 3.8. Kế hoạch thường xuyên."}, {"chapter_slug": "chuong-6", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Kế hoạch được chuẩn bị trước để ứng phó khi tình huống bất ngờ xảy ra là:", "option_a": "Kế hoạch dự phòng", "option_b": "Sứ mệnh", "option_c": "Tầm nhìn", "option_d": "Mục tiêu chính thức", "correct_option": "A", "explanation": "Contingency plan là phương án thay thế được chuẩn bị khi kế hoạch ban đầu bị gián đoạn.", "topic": "Mục 3.10. Kế hoạch dự phòng."}, {"chapter_slug": "chuong-6", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một mục tiêu ghi: “Cải thiện chất lượng dịch vụ trong tương lai”. Hạn chế lớn nhất là:", "option_a": "Quá nhiều số liệu", "option_b": "Thiếu tính cụ thể và khả năng đo lường", "option_c": "Quá khó", "option_d": "Quá liên quan đến chiến lược", "correct_option": "B", "explanation": "Không có mức cải thiện cụ thể, tiêu chí đo hoặc thời hạn nên mục tiêu chưa đáp ứng SMART.", "topic": "Mục 2.10 và 2.11."}, {"chapter_slug": "chuong-6", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Mục tiêu của phòng marketing giúp thực hiện mục tiêu doanh thu của toàn công ty thể hiện:", "option_a": "Hệ thống thứ bậc mục tiêu", "option_b": "Groupthink", "option_c": "Quy tắc", "option_d": "Kế hoạch dự phòng", "correct_option": "A", "explanation": "Mục tiêu cấp dưới phải liên kết và hỗ trợ mục tiêu ở cấp tổ chức.", "topic": "Mục 2.6. Hệ thống thứ bậc mục tiêu."}, {"chapter_slug": "chuong-6", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác biệt cơ bản giữa hoạch định chiến lược và tác nghiệp là:", "option_a": "Chiến lược chú trọng định hướng rộng, còn tác nghiệp chú trọng hành động cụ thể", "option_b": "Tác nghiệp luôn dài hạn hơn chiến lược", "option_c": "Chiến lược chỉ dành cho nhân viên", "option_d": "Tác nghiệp không liên quan mục tiêu", "correct_option": "A", "explanation": "Hoạch định chiến lược xác định định hướng tổng thể, còn tác nghiệp chuyển định hướng thành công việc cụ thể.", "topic": "Mục 3.11. So sánh hoạch định chiến lược và tác nghiệp."}, {"chapter_slug": "chuong-6", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Trong SWOT, yếu tố nào thuộc môi trường bên ngoài?", "option_a": "Strengths và Weaknesses", "option_b": "Opportunities và Threats", "option_c": "Strengths và Opportunities", "option_d": "Weaknesses và Threats", "correct_option": "B", "explanation": "Cơ hội và đe dọa đến từ môi trường bên ngoài; điểm mạnh và điểm yếu thuộc nội bộ.", "topic": "Mục 3.4. Phân tích SWOT."}, {"chapter_slug": "chuong-6", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm quan trọng của MBO là:", "option_a": "Chỉ cấp trên đặt mục tiêu", "option_b": "Kết hợp mục tiêu, sự tham gia, kế hoạch hành động và phản hồi", "option_c": "Không cần đánh giá kết quả", "option_d": "Không cần mục tiêu cá nhân", "correct_option": "B", "explanation": "MBO nhấn mạnh việc nhà quản trị và nhân viên cùng xác định mục tiêu, theo dõi và đánh giá kết quả.", "topic": "Mục 2.13. Quản trị theo mục tiêu."}, {"chapter_slug": "chuong-6", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Công ty đặt mục tiêu giảm 20% chi phí mua hàng. Phòng mua hàng đạt mục tiêu bằng cách chọn nguyên liệu rẻ hơn nhưng tỷ lệ sản phẩm lỗi tăng mạnh. Vấn đề chính là:", "option_a": "Mục tiêu mua hàng chưa được liên kết tốt với mục tiêu chung của tổ chức", "option_b": "Mục tiêu quá cụ thể", "option_c": "Công ty không cần hoạch định", "option_d": "Phòng mua hàng cần giảm chi phí mạnh hơn", "correct_option": "A", "explanation": "Mục tiêu bộ phận được tối ưu nhưng làm tổn hại chất lượng và hiệu quả chung. Đây là vấn đề liên kết mục tiêu.", "topic": "Mục 2.6 và 2.12."}, {"chapter_slug": "chuong-6", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp có bản kế hoạch 5 năm rất chi tiết và từ chối điều chỉnh dù công nghệ ngành đã thay đổi hoàn toàn. Hạn chế của hoạch định thể hiện rõ nhất là:", "option_a": "Kế hoạch quá linh hoạt", "option_b": "Sự cứng nhắc trong hoạch định", "option_c": "Không có mục tiêu", "option_d": "Có quá nhiều phản hồi", "correct_option": "B", "explanation": "Kế hoạch trở thành rào cản khi nhà quản trị xem nó là bất biến dù giả định môi trường đã thay đổi.", "topic": "Mục 1.6.3. Kế hoạch quá cứng nhắc."}, {"chapter_slug": "chuong-6", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp xây dựng mục tiêu “tăng số cuộc gọi bán hàng lên 50%”. Nhân viên gọi nhiều hơn nhưng doanh thu không tăng và khách hàng phàn nàn nhiều hơn. Sai lầm nằm ở:", "option_a": "Mục tiêu hoạt động không phản ánh tốt kết quả thực sự tổ chức muốn đạt", "option_b": "Mục tiêu có thời hạn", "option_c": "Nhân viên được đo lường", "option_d": "Có quá nhiều chiến lược", "correct_option": "A", "explanation": "Chỉ tiêu số cuộc gọi trở thành mục tiêu thay thế trong khi mục tiêu thật là tạo doanh thu và giá trị khách hàng.", "topic": "Mục 2.12. Những sai lầm khi xây dựng mục tiêu."}, {"chapter_slug": "chuong-6", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một tổ chức có chiến lược mở rộng sang thị trường mới nhưng không có ngân sách, kế hoạch tuyển người hay thời hạn triển khai. Hạn chế lớn nhất là:", "option_a": "Hoạch định chiến lược chưa được chuyển thành hoạch định chiến thuật và tác nghiệp", "option_b": "Chiến lược quá cụ thể", "option_c": "Tổ chức có quá nhiều thủ tục", "option_d": "Sứ mệnh quá rõ", "correct_option": "A", "explanation": "Chiến lược chỉ tạo kết quả khi được chuyển thành kế hoạch bộ phận và hành động cụ thể.", "topic": "Mục 3.5, 3.6 và 3.12."}, {"chapter_slug": "chuong-6", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp trong ngành biến động cao xây dựng một kế hoạch duy nhất và không chuẩn bị phương án thay thế. Cải tiến phù hợp nhất là:", "option_a": "Tăng tính linh hoạt và xây dựng kế hoạch dự phòng", "option_b": "Làm kế hoạch dài hơn nhưng không thay đổi", "option_c": "Loại bỏ toàn bộ mục tiêu", "option_d": "Chỉ tập trung vào dữ liệu quá khứ", "correct_option": "A", "explanation": "Môi trường bất trắc cao đòi hỏi kế hoạch có khả năng điều chỉnh và phương án dự phòng.", "topic": "Mục 3.10 và 3.13."}, {"chapter_slug": "chuong-6", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một chủ cửa hàng nói: “Năm tới tôi muốn kinh doanh tốt hơn” nhưng không xác định doanh thu, khách hàng hay thời hạn. Vấn đề chủ yếu là:", "option_a": "Mục tiêu chưa cụ thể", "option_b": "Kế hoạch quá chi tiết", "option_c": "Quá nhiều kiểm soát", "option_d": "Phân quyền quá cao", "correct_option": "A", "explanation": "“Kinh doanh tốt hơn” không cho biết kết quả cụ thể cần đạt.", "topic": "Mục 2.10 và 2.11. SMART."}, {"chapter_slug": "chuong-6", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Doanh nghiệp đặt mục tiêu “tăng doanh thu 10% trước ngày 31/12”. Mục tiêu này thể hiện rõ nhất hai thành phần SMART nào?", "option_a": "Specific và Time-bound", "option_b": "Achievable và Relevant duy nhất", "option_c": "Mission và Vision", "option_d": "Policy và Procedure", "correct_option": "A", "explanation": "Mức tăng 10% làm mục tiêu cụ thể, còn ngày 31/12 tạo thời hạn rõ ràng.", "topic": "Mục 2.11. SMART."}, {"chapter_slug": "chuong-6", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một trường đại học tuyên bố: “Đào tạo nguồn nhân lực có chất lượng phục vụ xã hội”. Nội dung này gần nhất với:", "option_a": "Sứ mệnh", "option_b": "Lịch tác nghiệp", "option_c": "Quy tắc", "option_d": "Ngân sách", "correct_option": "A", "explanation": "Tuyên bố mô tả lý do tồn tại và giá trị mà tổ chức muốn tạo ra nên gần với sứ mệnh.", "topic": "Mục 2.3. Sứ mệnh."}, {"chapter_slug": "chuong-6", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty xác định muốn trở thành thương hiệu dẫn đầu ngành trong tương lai. Nội dung này gần nhất với:", "option_a": "Tầm nhìn", "option_b": "Thủ tục", "option_c": "Kế hoạch hằng ngày", "option_d": "Ngân sách", "correct_option": "A", "explanation": "Tầm nhìn mô tả trạng thái hoặc vị thế tương lai mà tổ chức mong muốn.", "topic": "Mục 2.2. Tầm nhìn."}, {"chapter_slug": "chuong-6", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Tổng giám đốc đặt mục tiêu tăng thị phần 10%. Phòng marketing sau đó đặt mục tiêu tăng nhận biết thương hiệu 20%. Đây là:", "option_a": "Sự liên kết theo hệ thống thứ bậc mục tiêu", "option_b": "Quyết định không theo chương trình", "option_c": "Groupthink", "option_d": "Văn hóa bộ phận", "correct_option": "A", "explanation": "Mục tiêu bộ phận được hình thành để hỗ trợ mục tiêu của toàn công ty.", "topic": "Mục 2.6. Hệ thống thứ bậc mục tiêu."}, {"chapter_slug": "chuong-6", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một quản lý giao cho nhân viên mục tiêu “cố gắng bán hàng nhiều nhất có thể”. Cách cải tiến tốt nhất là:", "option_a": "Chuyển thành mục tiêu cụ thể, đo được và có thời hạn", "option_b": "Bỏ mục tiêu", "option_c": "Chỉ tăng áp lực", "option_d": "Không cho nhân viên biết mục tiêu", "correct_option": "A", "explanation": "Goal-setting theory và SMART đều nhấn mạnh giá trị của mục tiêu cụ thể.", "topic": "Mục 2.10 và 2.11."}, {"chapter_slug": "chuong-6", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty tổ chức cuộc họp trong đó quản lý và nhân viên cùng thống nhất chỉ tiêu công việc rồi định kỳ xem xét kết quả. Đây là:", "option_a": "Management by Objectives", "option_b": "SWOT", "option_c": "Policy", "option_d": "Rule", "correct_option": "A", "explanation": "Sự tham gia vào xây dựng mục tiêu và phản hồi kết quả là đặc điểm cốt lõi của MBO.", "topic": "Mục 2.13. MBO."}, {"chapter_slug": "chuong-6", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Ban giám đốc quyết định trong 5 năm tới công ty sẽ chuyển từ kinh doanh trong nước sang thị trường Đông Nam Á. Đây chủ yếu là:", "option_a": "Hoạch định chiến lược", "option_b": "Hoạch định tác nghiệp", "option_c": "Thủ tục", "option_d": "Quy tắc", "correct_option": "A", "explanation": "Quyết định có phạm vi toàn tổ chức, dài hạn và liên quan đến vị thế trong môi trường.", "topic": "Mục 3.1. Hoạch định chiến lược."}, {"chapter_slug": "chuong-6", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Sau quyết định mở rộng thị trường, phòng nhân sự xây dựng kế hoạch tuyển 40 nhân viên cho khu vực mới trong năm tới. Đây gần nhất với:", "option_a": "Hoạch định chiến thuật", "option_b": "Tầm nhìn", "option_c": "Sứ mệnh", "option_d": "Quy tắc", "correct_option": "A", "explanation": "Kế hoạch của phòng nhân sự chuyển định hướng chiến lược thành mục tiêu của bộ phận.", "topic": "Mục 3.5. Hoạch định chiến thuật."}, {"chapter_slug": "chuong-6", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trưởng cửa hàng lập lịch làm việc cụ thể cho 15 nhân viên trong tuần tới. Đây là:", "option_a": "Hoạch định tác nghiệp", "option_b": "Hoạch định chiến lược", "option_c": "Tầm nhìn", "option_d": "Sứ mệnh", "correct_option": "A", "explanation": "Lịch làm việc ngắn hạn và cụ thể là hoạt động tác nghiệp.", "topic": "Mục 3.6 và 3.7."}, {"chapter_slug": "chuong-6", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp xác định “thương hiệu mạnh” là điểm mạnh, “công nghệ cũ” là điểm yếu, “thị trường tăng trưởng” là cơ hội và “đối thủ mới” là đe dọa. Công ty đang sử dụng:", "option_a": "SWOT", "option_b": "MBO", "option_c": "NGT", "option_d": "Decision tree", "correct_option": "A", "explanation": "Đây chính là bốn thành phần của phân tích SWOT.", "topic": "Mục 3.4. Phân tích SWOT."}, {"chapter_slug": "chuong-6", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Công ty quy định: “Nhân viên phải sử dụng thiết bị bảo hộ khi vào khu vực sản xuất.” Đây là:", "option_a": "Quy tắc", "option_b": "Chính sách", "option_c": "Tầm nhìn", "option_d": "Chiến lược", "correct_option": "A", "explanation": "Quy tắc xác định rõ hành vi phải hoặc không được thực hiện.", "topic": "Mục 3.8.3. Quy tắc."}, {"chapter_slug": "chuong-6", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Công ty quy định chung: “Ưu tiên giải quyết quyền lợi khách hàng khi xảy ra sai sót do công ty.” Đây gần nhất với:", "option_a": "Chính sách", "option_b": "Thủ tục", "option_c": "Dự án", "option_d": "Ngân sách", "correct_option": "A", "explanation": "Chính sách đưa ra định hướng chung nhưng vẫn cho phép người quản trị sử dụng phán đoán trong từng tình huống.", "topic": "Mục 3.8.1. Chính sách."}, {"chapter_slug": "chuong-6", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Bộ phận chăm sóc khách hàng quy định năm bước cụ thể để xử lý khiếu nại. Đây là:", "option_a": "Thủ tục", "option_b": "Tầm nhìn", "option_c": "Mục tiêu chiến lược", "option_d": "Sứ mệnh", "correct_option": "A", "explanation": "Procedure là chuỗi bước được quy định để thực hiện một hoạt động.", "topic": "Mục 3.8.2. Thủ tục."}, {"chapter_slug": "chuong-6", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp xây dựng kế hoạch tổ chức lễ kỷ niệm 30 năm thành lập chỉ diễn ra một lần. Đây là:", "option_a": "Kế hoạch sử dụng một lần", "option_b": "Standing plan", "option_c": "Chính sách", "option_d": "Quy tắc", "correct_option": "A", "explanation": "Hoạt động riêng biệt, không lặp lại thường xuyên phù hợp với single-use plan.", "topic": "Mục 3.9. Kế hoạch sử dụng một lần."}, {"chapter_slug": "chuong-6", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Doanh nghiệp xây dựng trước phương án chuyển sang nhà cung cấp B nếu nhà cung cấp A không giao được nguyên liệu. Đây là:", "option_a": "Kế hoạch dự phòng", "option_b": "Tầm nhìn", "option_c": "Mục tiêu tác nghiệp", "option_d": "Chính sách thưởng", "correct_option": "A", "explanation": "Phương án được chuẩn bị trước khi kế hoạch chính gặp sự cố là contingency plan.", "topic": "Mục 3.10. Kế hoạch dự phòng."}, {"chapter_slug": "chuong-6", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty có chiến lược “khác biệt hóa bằng dịch vụ cao cấp” nhưng phòng chăm sóc khách hàng bị cắt giảm nhân viên đến mức khách phải chờ rất lâu. Vấn đề là:", "option_a": "Kế hoạch tác nghiệp không phù hợp chiến lược", "option_b": "Chiến lược quá cụ thể", "option_c": "Có quá nhiều phản hồi", "option_d": "Công ty không cần mục tiêu", "correct_option": "A", "explanation": "Hoạt động tác nghiệp đang mâu thuẫn với định hướng chiến lược về dịch vụ cao cấp.", "topic": "Mục 3.12. Mối quan hệ giữa các cấp hoạch định."}, {"chapter_slug": "chuong-6", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một startup hoạt động trong ngành thay đổi nhanh nên chỉ xây dựng kế hoạch ngắn theo quý và xem xét lại thường xuyên. Điều này thể hiện:", "option_a": "Hoạch định linh hoạt theo môi trường", "option_b": "Không có hoạch định", "option_c": "Không có mục tiêu", "option_d": "Chỉ sử dụng kế hoạch thường xuyên", "correct_option": "A", "explanation": "Trong môi trường biến động, chu kỳ hoạch định có thể được rút ngắn để tăng khả năng thích nghi.", "topic": "Mục 3.13. Sự linh hoạt trong hoạch định."}, {"chapter_slug": "chuong-6", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Doanh nghiệp đạt toàn bộ mục tiêu doanh thu quý nhưng khách hàng giảm mạnh và thương hiệu bị ảnh hưởng vì bán hàng quá mức. Bài học quan trọng nhất là:", "option_a": "Mục tiêu ngắn hạn phải được xem xét trong quan hệ với mục tiêu dài hạn", "option_b": "Chỉ nên sử dụng mục tiêu ngắn hạn", "option_c": "Không nên đo kết quả", "option_d": "Hoạch định không có giá trị", "correct_option": "A", "explanation": "Tối ưu kết quả ngắn hạn có thể gây tổn hại định hướng dài hạn nếu các mục tiêu không được cân bằng.", "topic": "Mục 2.9 và 2.12."}, {"chapter_slug": "chuong-6", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Sau mỗi quý, công ty so sánh kết quả với mục tiêu, cập nhật tình hình thị trường và điều chỉnh kế hoạch quý tiếp theo. Hoạt động này thể hiện:", "option_a": "Hoạch định là quá trình liên tục có phản hồi", "option_b": "Kế hoạch phải bất biến", "option_c": "Công ty không có chiến lược", "option_d": "Chỉ đang thực hiện kiểm soát, không liên quan hoạch định", "correct_option": "A", "explanation": "Theo dõi kết quả và điều chỉnh kế hoạch phản ánh bản chất liên tục của hoạch định.", "topic": "Mục 1.3.5, 1.7 và 3.13."}, {"chapter_slug": "chuong-7", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Chức năng tổ chức được hiểu phù hợp nhất là:", "option_a": "Chỉ lập sơ đồ phòng ban", "option_b": "Quá trình bố trí công việc, con người, quyền hạn và quan hệ để thực hiện mục tiêu", "option_c": "Chỉ tuyển dụng nhân viên", "option_d": "Chỉ kiểm tra kết quả", "correct_option": "B", "explanation": "Tổ chức bao gồm phân chia công việc, nhóm công việc, bố trí nguồn lực và xác lập quyền hạn – trách nhiệm để thực hiện kế hoạch.", "topic": "Mục 1.1. Khái niệm công tác tổ chức."}, {"chapter_slug": "chuong-7", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Kết quả chủ yếu của quá trình tổ chức là:", "option_a": "Cơ cấu tổ chức", "option_b": "Mục tiêu", "option_c": "Tầm nhìn", "option_d": "Dự báo", "correct_option": "A", "explanation": "Cơ cấu tổ chức thể hiện cách các công việc, đơn vị và quan hệ quyền hạn được sắp xếp sau quá trình thiết kế tổ chức.", "topic": "Mục 1.2. Phân biệt công tác tổ chức và cơ cấu tổ chức."}, {"chapter_slug": "chuong-7", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Việc chia toàn bộ công việc thành những nhiệm vụ nhỏ hơn được gọi là:", "option_a": "Phân công lao động", "option_b": "Phân quyền", "option_c": "Kiểm soát", "option_d": "Hoạch định", "correct_option": "A", "explanation": "Division of labor là quá trình chia công việc thành các nhiệm vụ riêng và giao cho cá nhân hoặc đơn vị thực hiện.", "topic": "Mục 2.1. Phân công lao động và chuyên môn hóa."}, {"chapter_slug": "chuong-7", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Departmentalization là:", "option_a": "Xây dựng sứ mệnh", "option_b": "Nhóm các công việc có liên quan thành đơn vị", "option_c": "Kiểm tra kết quả", "option_d": "Dự báo thị trường", "correct_option": "B", "explanation": "Phân chia bộ phận là quá trình nhóm những công việc và con người có mối liên hệ để thuận lợi cho quản lý.", "topic": "Mục 2.2. Phân chia bộ phận."}, {"chapter_slug": "chuong-7", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Quyền lực chính thức được tổ chức trao cho một vị trí được gọi là:", "option_a": "Authority", "option_b": "Culture", "option_c": "Motivation", "option_d": "Strategy", "correct_option": "A", "explanation": "Authority là quyền chính thức cho phép cá nhân ra quyết định và yêu cầu hành động trong phạm vi được giao.", "topic": "Mục 2.8.1. Quyền hạn."}, {"chapter_slug": "chuong-7", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Số cấp dưới trực tiếp mà nhà quản trị giám sát được gọi là:", "option_a": "Chain of Command", "option_b": "Span of Control", "option_c": "Departmentalization", "option_d": "Formalization", "correct_option": "B", "explanation": "Span of control hay span of management là tầm hạn quản trị.", "topic": "Mục 2.12. Tầm hạn quản trị."}, {"chapter_slug": "chuong-7", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Việc chuyển quyền ra quyết định xuống các cấp thấp hơn được gọi là:", "option_a": "Tập trung", "option_b": "Phân quyền", "option_c": "Chính thức hóa", "option_d": "Chuyên môn hóa", "correct_option": "B", "explanation": "Decentralization là việc phân bổ quyền quyết định xuống các cấp thấp hơn trong tổ chức.", "topic": "Mục 2.11.2. Phân quyền."}, {"chapter_slug": "chuong-7", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Cơ cấu nào nhóm nhân viên theo các lĩnh vực như marketing, tài chính và nhân sự?", "option_a": "Chức năng", "option_b": "Ma trận", "option_c": "Địa lý", "option_d": "Dự án", "correct_option": "A", "explanation": "Functional structure nhóm nhân viên dựa trên chuyên môn hoặc chức năng.", "topic": "Mục 3.4. Cơ cấu chức năng."}, {"chapter_slug": "chuong-7", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Cơ cấu trong đó nhân viên có thể đồng thời báo cáo cho quản lý chức năng và quản lý dự án là:", "option_a": "Ma trận", "option_b": "Trực tuyến", "option_c": "Chức năng thuần túy", "option_d": "Địa lý", "correct_option": "A", "explanation": "Matrix structure kết hợp hai chiều quyền hạn, thường là chức năng và dự án/sản phẩm.", "topic": "Mục 3.9. Cơ cấu ma trận."}, {"chapter_slug": "chuong-7", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Cơ cấu hữu cơ thường phù hợp hơn với:", "option_a": "Môi trường biến động", "option_b": "Mọi môi trường", "option_c": "Chỉ doanh nghiệp nhỏ", "option_d": "Công việc không thay đổi", "correct_option": "A", "explanation": "Cơ cấu hữu cơ có mức linh hoạt và phân quyền cao hơn nên thường thích hợp khi môi trường thay đổi nhanh.", "topic": "Mục 2.16. Cơ cấu cơ học và hữu cơ."}, {"chapter_slug": "chuong-7", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một trưởng phòng chịu trách nhiệm về kết quả kinh doanh nhưng không có quyền quyết định những vấn đề cần thiết để đạt mục tiêu. Nguyên tắc nào đang bị vi phạm?", "option_a": "Cân đối quyền hạn và trách nhiệm", "option_b": "Chuyên môn hóa", "option_c": "Tầm hạn quản trị", "option_d": "Chính thức hóa", "correct_option": "A", "explanation": "Một cá nhân không thể chịu trách nhiệm hiệu quả nếu không được trao quyền tương xứng để thực hiện nhiệm vụ.", "topic": "Mục 1.7. Quyền hạn gắn với trách nhiệm."}, {"chapter_slug": "chuong-7", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một doanh nghiệp phân chia thành bộ phận khách hàng cá nhân, khách hàng doanh nghiệp và khách hàng tổ chức. Đây là:", "option_a": "Phân chia theo khách hàng", "option_b": "Theo chức năng", "option_c": "Theo quá trình", "option_d": "Theo địa lý", "correct_option": "A", "explanation": "Các đơn vị được thiết kế theo nhóm khách hàng mà doanh nghiệp phục vụ.", "topic": "Mục 2.6. Phân chia theo khách hàng."}, {"chapter_slug": "chuong-7", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Việc mở rộng tầm hạn quản trị thường có xu hướng:", "option_a": "Làm giảm số tầng quản trị", "option_b": "Làm tăng số tầng quản trị", "option_c": "Loại bỏ phân quyền", "option_d": "Tăng chiều dài chuỗi quyền lực", "correct_option": "A", "explanation": "Khi mỗi nhà quản trị giám sát nhiều nhân viên hơn, tổ chức thường cần ít tầng quản lý hơn và trở nên phẳng hơn.", "topic": "Mục 2.12 và 2.13."}, {"chapter_slug": "chuong-7", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Lợi ích lớn của phân quyền là:", "option_a": "Mọi quyết định đều tập trung vào giám đốc", "option_b": "Tăng khả năng ra quyết định gần nơi vấn đề xảy ra", "option_c": "Loại bỏ trách nhiệm của cấp cao", "option_d": "Không cần kiểm soát", "correct_option": "B", "explanation": "Phân quyền giúp những người gần khách hàng hoặc vấn đề có thể phản ứng nhanh hơn.", "topic": "Mục 2.11. Tập trung và phân quyền."}, {"chapter_slug": "chuong-7", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác biệt nổi bật giữa cơ cấu chức năng và cơ cấu bộ phận là:", "option_a": "Cơ cấu chức năng nhóm theo chuyên môn, còn cơ cấu bộ phận có thể nhóm theo sản phẩm hoặc thị trường", "option_b": "Hai cơ cấu giống nhau hoàn toàn", "option_c": "Cơ cấu bộ phận không có phòng chức năng", "option_d": "Cơ cấu chức năng không có quản lý", "correct_option": "A", "explanation": "Functional structure tập trung chuyên môn, trong khi divisional structure tạo các đơn vị hướng vào sản phẩm, khách hàng hoặc địa lý.", "topic": "Mục 3.4 và 3.6."}, {"chapter_slug": "chuong-7", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty có quá nhiều tầng quản lý. Thông tin từ nhân viên lên giám đốc phải đi qua sáu cấp và quyết định thường chậm. Giải pháp phù hợp nhất về mặt thiết kế tổ chức là:", "option_a": "Xem xét mở rộng tầm hạn quản trị và giảm các tầng không cần thiết", "option_b": "Thu hẹp tầm hạn hơn nữa", "option_c": "Tạo thêm cấp phó", "option_d": "Tập trung thêm mọi quyết định", "correct_option": "A", "explanation": "Cơ cấu quá cao có thể làm thông tin và quyết định chậm. Mở rộng tầm hạn hợp lý có thể giúp làm phẳng cơ cấu.", "topic": "Mục 2.12 và 2.13."}, {"chapter_slug": "chuong-7", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp công nghệ hoạt động trong môi trường thay đổi nhanh nhưng mọi công việc được quy định cực kỳ chi tiết và quyết định phải xin cấp cao. Vấn đề lớn nhất là:", "option_a": "Cơ cấu quá cơ học so với yêu cầu môi trường", "option_b": "Cơ cấu quá hữu cơ", "option_c": "Có quá nhiều phân quyền", "option_d": "Tầm hạn quá rộng chắc chắn", "correct_option": "A", "explanation": "Môi trường đổi mới nhanh thường đòi hỏi linh hoạt và phân quyền hơn; cơ cấu cơ học quá cứng có thể làm chậm thích nghi.", "topic": "Mục 2.16–2.17."}, {"chapter_slug": "chuong-7", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một nhân viên trong cơ cấu ma trận nhận hai yêu cầu trái ngược từ trưởng phòng chức năng và trưởng dự án. Đây là:", "option_a": "Một hạn chế điển hình của cơ cấu ma trận", "option_b": "Lợi thế chính của cơ cấu chức năng", "option_c": "Minh chứng rằng không cần xác định quyền hạn", "option_d": "Hệ quả của phân công lao động thấp", "correct_option": "A", "explanation": "Quan hệ quyền hạn kép trong matrix có thể tạo xung đột ưu tiên nếu trách nhiệm và quyền quyết định không được phân định rõ.", "topic": "Mục 3.9. Cơ cấu ma trận."}, {"chapter_slug": "chuong-7", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một tập đoàn có nhiều dòng sản phẩm rất khác nhau nhưng vẫn quản lý mọi hoạt động bằng một cơ cấu chức năng tập trung duy nhất. Việc phối hợp sản phẩm ngày càng khó. Phương án đáng xem xét nhất là:", "option_a": "Cơ cấu theo bộ phận/sản phẩm", "option_b": "Tăng thêm chuyên môn hóa chức năng duy nhất", "option_c": "Loại bỏ mọi đơn vị", "option_d": "Chỉ dùng cơ cấu trực tuyến đơn giản", "correct_option": "A", "explanation": "Divisional structure có thể giúp mỗi ngành hàng tập trung vào thị trường và kết quả riêng khi danh mục sản phẩm trở nên đa dạng.", "topic": "Mục 3.6 và 3.7."}, {"chapter_slug": "chuong-7", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một tổ chức muốn trao quyền mạnh cho nhóm nhưng nhân viên chưa có kỹ năng, thông tin và kinh nghiệm cần thiết. Kết luận phù hợp nhất là:", "option_a": "Phân quyền phải đi kèm năng lực và cơ chế hỗ trợ", "option_b": "Phân quyền luôn tạo kết quả tốt", "option_c": "Cần loại bỏ toàn bộ quản lý", "option_d": "Trao quyền càng nhiều càng tốt trong mọi trường hợp", "correct_option": "A", "explanation": "Mức độ phân quyền phải phù hợp với năng lực con người, loại quyết định, rủi ro và hệ thống kiểm soát.", "topic": "Mục 2.11.6. Các yếu tố ảnh hưởng đến phân quyền."}, {"chapter_slug": "chuong-7", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một cửa hàng nhỏ có 8 nhân viên. Chủ cửa hàng trực tiếp phân công và giám sát tất cả mọi người, quan hệ quyền hạn rất đơn giản. Cơ cấu gần nhất là:", "option_a": "Trực tuyến", "option_b": "Ma trận", "option_c": "Mạng lưới", "option_d": "Bộ phận", "correct_option": "A", "explanation": "Cơ cấu trực tuyến phù hợp với tổ chức nhỏ, có chuỗi quyền hạn đơn giản và rõ.", "topic": "Mục 3.3. Cơ cấu trực tuyến."}, {"chapter_slug": "chuong-7", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty chia nhân viên thành phòng Marketing, Nhân sự, Tài chính và Sản xuất. Công ty đang sử dụng:", "option_a": "Cơ cấu chức năng", "option_b": "Cơ cấu theo khách hàng", "option_c": "Cơ cấu dự án", "option_d": "Cơ cấu địa lý", "correct_option": "A", "explanation": "Các đơn vị được nhóm theo lĩnh vực chuyên môn nên đây là cơ cấu chức năng.", "topic": "Mục 3.4. Cơ cấu chức năng."}, {"chapter_slug": "chuong-7", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một tập đoàn có ba division: Điện tử, Thực phẩm và Dược phẩm; mỗi division có marketing, tài chính và sản xuất riêng. Đây là:", "option_a": "Cơ cấu bộ phận theo sản phẩm", "option_b": "Cơ cấu chức năng thuần túy", "option_c": "Cơ cấu trực tuyến đơn giản", "option_d": "Cơ cấu theo quá trình", "correct_option": "A", "explanation": "Các đơn vị được tổ chức quanh từng dòng sản phẩm.", "topic": "Mục 3.6 và 3.7."}, {"chapter_slug": "chuong-7", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp chia bộ phận kinh doanh thành Miền Bắc, Miền Trung và Miền Nam. Đây là:", "option_a": "Phân chia theo địa lý", "option_b": "Theo chức năng", "option_c": "Theo quá trình", "option_d": "Theo khách hàng", "correct_option": "A", "explanation": "Các đơn vị được xác định theo khu vực thị trường.", "topic": "Mục 2.5 và 3.8."}, {"chapter_slug": "chuong-7", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Ngân hàng chia hoạt động thành khách hàng cá nhân, doanh nghiệp vừa và nhỏ, và doanh nghiệp lớn. Đây là:", "option_a": "Phân chia theo khách hàng", "option_b": "Theo địa lý", "option_c": "Theo quá trình", "option_d": "Theo chức năng", "correct_option": "A", "explanation": "Mỗi đơn vị tập trung phục vụ một nhóm khách hàng có nhu cầu khác nhau.", "topic": "Mục 2.6. Phân chia theo khách hàng."}, {"chapter_slug": "chuong-7", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhà máy chia thành công đoạn cắt, gia công, lắp ráp và đóng gói. Đây là:", "option_a": "Phân chia theo quá trình", "option_b": "Theo khách hàng", "option_c": "Theo địa lý", "option_d": "Theo sản phẩm", "correct_option": "A", "explanation": "Các bộ phận được xây dựng theo từng bước trong quá trình sản xuất.", "topic": "Mục 2.7. Phân chia theo quá trình."}, {"chapter_slug": "chuong-7", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trưởng phòng giao cho nhân viên xử lý khiếu nại nhưng mọi phương án bồi thường dù rất nhỏ đều phải xin trưởng phòng phê duyệt. Vấn đề là:", "option_a": "Giao trách nhiệm nhưng chưa giao đủ quyền hạn", "option_b": "Phân quyền quá mức", "option_c": "Tầm hạn quá rộng", "option_d": "Chuyên môn hóa quá thấp", "correct_option": "A", "explanation": "Ủy quyền hiệu quả cần trao đủ quyền hạn để người nhận nhiệm vụ thực hiện trách nhiệm được giao.", "topic": "Mục 2.10. Ủy quyền."}, {"chapter_slug": "chuong-7", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Sau khi giao dự án cho nhân viên, trưởng phòng không can thiệp vào từng việc nhỏ nhưng yêu cầu báo cáo theo các mốc quan trọng. Đây là:", "option_a": "Ủy quyền kết hợp kiểm soát hợp lý", "option_b": "Bỏ mặc nhân viên", "option_c": "Tập trung tuyệt đối", "option_d": "Không giao trách nhiệm", "correct_option": "A", "explanation": "Ủy quyền không có nghĩa từ bỏ kiểm soát; cấp trên cần xác định kết quả và các mốc theo dõi phù hợp.", "topic": "Mục 2.10.2–2.10.4."}, {"chapter_slug": "chuong-7", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Mọi cửa hàng của một chuỗi bán lẻ phải xin tổng giám đốc phê duyệt ngay cả việc giảm giá một sản phẩm bị lỗi nhẹ. Điều này cho thấy:", "option_a": "Mức tập trung cao", "option_b": "Mức phân quyền cao", "option_c": "Cơ cấu hữu cơ", "option_d": "Tổ chức ảo", "correct_option": "A", "explanation": "Quyền quyết định được giữ chủ yếu ở cấp trên cho thấy tổ chức có mức tập trung cao.", "topic": "Mục 2.11.1. Tập trung."}, {"chapter_slug": "chuong-7", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một chuỗi nhà hàng cho phép quản lý từng cửa hàng tự xử lý khiếu nại khách hàng trong giới hạn ngân sách nhất định. Điều này thể hiện:", "option_a": "Phân quyền có giới hạn", "option_b": "Tập trung tuyệt đối", "option_c": "Không có quyền hạn", "option_d": "Không có kiểm soát", "correct_option": "A", "explanation": "Quyền quyết định được giao xuống cấp gần khách hàng nhưng vẫn có giới hạn rõ.", "topic": "Mục 2.11. Phân quyền."}, {"chapter_slug": "chuong-7", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một trưởng nhóm đang trực tiếp quản lý 35 nhân viên mới, công việc phức tạp và phải hướng dẫn liên tục. Vấn đề có khả năng nhất là:", "option_a": "Tầm hạn quản trị quá rộng so với điều kiện công việc", "option_b": "Tầm hạn chắc chắn quá hẹp", "option_c": "Có quá nhiều cấp quản lý", "option_d": "Nhân viên bị chuyên môn hóa quá mức chắc chắn", "correct_option": "A", "explanation": "Công việc phức tạp và nhân viên mới cần nhiều hướng dẫn nên tầm hạn quá rộng có thể làm quản lý quá tải.", "topic": "Mục 2.12. Tầm hạn quản trị."}, {"chapter_slug": "chuong-7", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một quản lý giám sát 12 kỹ sư giàu kinh nghiệm, công việc được tiêu chuẩn hóa và hệ thống báo cáo rất tốt. Công ty có thể cân nhắc:", "option_a": "Tầm hạn quản trị tương đối rộng", "option_b": "Bắt buộc giảm xuống còn 2 người", "option_c": "Tạo nhiều cấp quản lý hơn", "option_d": "Loại bỏ ủy quyền", "correct_option": "A", "explanation": "Năng lực nhân viên cao và công việc có hệ thống hỗ trợ cho phép một nhà quản trị giám sát số người lớn hơn.", "topic": "Mục 2.12.3. Các yếu tố ảnh hưởng tầm hạn."}, {"chapter_slug": "chuong-7", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty quy định rất chi tiết từng bước công việc, có nhiều biểu mẫu và nhân viên ít được tự điều chỉnh cách làm. Công ty có:", "option_a": "Mức chính thức hóa cao", "option_b": "Mức chính thức hóa thấp", "option_c": "Không có cơ cấu", "option_d": "Phân quyền tuyệt đối", "correct_option": "A", "explanation": "Nhiều quy định, thủ tục và vai trò được xác định chi tiết là biểu hiện của formalization cao.", "topic": "Mục 2.14. Chính thức hóa."}, {"chapter_slug": "chuong-7", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên phòng marketing thường hỏi trực tiếp bạn mình ở kho để lấy thông tin tồn hàng nhanh dù sơ đồ chính thức không quy định quan hệ này. Đây là:", "option_a": "Quan hệ tổ chức không chính thức", "option_b": "Chuỗi quyền lực chính thức", "option_c": "Cơ cấu trực tuyến", "option_d": "Centralization", "correct_option": "A", "explanation": "Quan hệ hình thành tự nhiên giữa thành viên bên ngoài hệ thống báo cáo chính thức thuộc tổ chức không chính thức.", "topic": "Mục 2.15. Tổ chức chính thức và không chính thức."}, {"chapter_slug": "chuong-7", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty sản xuất hàng tiêu chuẩn trong môi trường ổn định, yêu cầu độ chính xác rất cao. Cơ cấu nào có thể phù hợp hơn?", "option_a": "Cơ cấu thiên về cơ học", "option_b": "Cơ cấu hoàn toàn không có quy tắc", "option_c": "Cơ cấu ảo bắt buộc", "option_d": "Không cần phân công", "correct_option": "A", "explanation": "Môi trường ổn định và yêu cầu nhất quán thường phù hợp hơn với chính thức hóa, chuyên môn hóa và kiểm soát tương đối cao.", "topic": "Mục 2.16. Cơ cấu cơ học."}, {"chapter_slug": "chuong-7", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty phát triển phần mềm cần liên tục thử nghiệm sản phẩm, nhân viên phải phối hợp ngang và đưa ra quyết định nhanh. Dạng thiết kế phù hợp hơn là:", "option_a": "Cơ cấu thiên về hữu cơ", "option_b": "Cơ cấu cơ học rất cứng", "option_c": "Tăng tối đa các tầng quản lý", "option_d": "Tập trung mọi quyết định vào CEO", "correct_option": "A", "explanation": "Cơ cấu hữu cơ hỗ trợ giao tiếp ngang, phân quyền và linh hoạt trong môi trường đổi mới.", "topic": "Mục 2.16.2. Cơ cấu hữu cơ."}, {"chapter_slug": "chuong-7", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một kỹ sư thuộc phòng kỹ thuật đồng thời làm cho dự án xây dựng nhà máy mới và báo cáo cho cả trưởng phòng kỹ thuật lẫn giám đốc dự án. Đây là:", "option_a": "Cơ cấu ma trận", "option_b": "Cơ cấu trực tuyến", "option_c": "Cơ cấu chức năng thuần túy", "option_d": "Cơ cấu địa lý", "correct_option": "A", "explanation": "Quan hệ báo cáo kép theo chức năng và dự án là đặc điểm điển hình của matrix structure.", "topic": "Mục 3.9. Cơ cấu ma trận."}, {"chapter_slug": "chuong-7", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty thời trang tự thiết kế và marketing nhưng thuê các doanh nghiệp khác sản xuất, vận chuyển và vận hành hệ thống CNTT. Cơ cấu này gần nhất với:", "option_a": "Cơ cấu mạng lưới", "option_b": "Trực tuyến", "option_c": "Chức năng truyền thống", "option_d": "Cơ học tuyệt đối", "correct_option": "A", "explanation": "Doanh nghiệp tập trung vào năng lực cốt lõi và liên kết với nhiều đối tác bên ngoài để thực hiện các hoạt động khác.", "topic": "Mục 3.12. Cơ cấu mạng lưới."}, {"chapter_slug": "chuong-7", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một doanh nghiệp có nhân viên tại nhiều quốc gia làm việc chủ yếu trực tuyến, sử dụng nền tảng số và rất ít phụ thuộc vào văn phòng vật lý. Cơ cấu gần nhất là:", "option_a": "Tổ chức ảo", "option_b": "Cơ cấu tuyến đơn giản", "option_c": "Cơ cấu chức năng cơ học", "option_d": "Phân chia theo quá trình", "correct_option": "A", "explanation": "Virtual organization dựa mạnh vào công nghệ để liên kết con người và hoạt động ở nhiều địa điểm.", "topic": "Mục 3.13. Tổ chức ảo."}, {"chapter_slug": "chuong-7", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một startup ban đầu có 15 người và cơ cấu rất đơn giản. Sau 5 năm công ty có 2.000 nhân viên, hoạt động tại nhiều quốc gia nhưng vẫn giữ nguyên cơ cấu cũ khiến CEO phải phê duyệt quá nhiều việc. Bài học quan trọng nhất là:", "option_a": "Cơ cấu tổ chức phải được điều chỉnh khi quy mô, chiến lược và môi trường thay đổi", "option_b": "Một cơ cấu tốt phải được giữ nguyên mãi mãi", "option_c": "Tổ chức càng lớn càng nên tập trung mọi quyết định", "option_d": "Cơ cấu không liên quan hiệu quả quản trị", "correct_option": "A", "explanation": "Cơ cấu phải phù hợp với đặc điểm tổ chức. Khi quy mô và độ phức tạp thay đổi, thiết kế tổ chức cũng cần được xem xét lại.", "topic": "Mục 1.11 và 3.15. Lựa chọn cơ cấu tổ chức."}, {"chapter_slug": "chuong-8", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Lãnh đạo được hiểu phù hợp nhất là:", "option_a": "Chỉ sử dụng quyền lực chính thức", "option_b": "Quá trình gây ảnh hưởng đến người khác để hướng đến mục tiêu chung", "option_c": "Chỉ kiểm tra công việc", "option_d": "Chỉ xây dựng cơ cấu", "correct_option": "B", "explanation": "Bản chất của lãnh đạo là tạo ảnh hưởng trong mối quan hệ với người theo nhằm đạt mục tiêu.", "topic": "Mục 1.2. Khái niệm lãnh đạo."}, {"chapter_slug": "chuong-8", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Phong cách trong đó nhà lãnh đạo giữ phần lớn quyền quyết định được gọi là:", "option_a": "Dân chủ", "option_b": "Độc đoán", "option_c": "Tự do", "option_d": "Chuyển đổi", "correct_option": "B", "explanation": "Autocratic leadership đặc trưng bởi mức tập trung quyền lực cao ở người lãnh đạo.", "topic": "Mục 1.7. Phong cách lãnh đạo độc đoán."}, {"chapter_slug": "chuong-8", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Phong cách khuyến khích nhân viên tham gia quyết định là:", "option_a": "Lãnh đạo dân chủ", "option_b": "Lãnh đạo độc đoán", "option_c": "Cưỡng chế", "option_d": "Tự do hoàn toàn", "correct_option": "A", "explanation": "Democratic/participative leadership khuyến khích ý kiến và sự tham gia của cấp dưới.", "topic": "Mục 1.8. Lãnh đạo dân chủ."}, {"chapter_slug": "chuong-8", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Theo Herzberg, yếu tố nào thuộc nhóm động viên?", "option_a": "Thành tựu", "option_b": "Điều kiện làm việc", "option_c": "Chính sách công ty", "option_d": "An toàn việc làm", "correct_option": "A", "explanation": "Thành tựu liên quan đến nội dung công việc và thuộc nhóm motivators.", "topic": "Mục 2.6. Lý thuyết hai nhân tố."}, {"chapter_slug": "chuong-8", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Theo Maslow, nhu cầu được ghi nhận và có địa vị thuộc nhóm:", "option_a": "Sinh lý", "option_b": "An toàn", "option_c": "Tôn trọng", "option_d": "Xã hội", "correct_option": "C", "explanation": "Nhu cầu esteem bao gồm thành tựu, công nhận, địa vị và tự trọng.", "topic": "Mục 2.4. Maslow."}, {"chapter_slug": "chuong-8", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Lý thuyết nào tập trung vào nhận thức về công bằng giữa đóng góp và kết quả?", "option_a": "Equity Theory", "option_b": "Maslow", "option_c": "Herzberg", "option_d": "Reinforcement Theory", "correct_option": "A", "explanation": "Equity Theory xem sự so sánh giữa input và outcome của cá nhân với người tham chiếu là cơ sở quan trọng của nhận thức công bằng.", "topic": "Mục 2.9. Lý thuyết công bằng."}, {"chapter_slug": "chuong-8", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Trong Expectancy Theory, nhân viên tin rằng nỗ lực sẽ dẫn đến thành tích phản ánh:", "option_a": "Expectancy", "option_b": "Valence", "option_c": "Equity", "option_d": "Affiliation", "correct_option": "A", "explanation": "Expectancy là mối liên hệ nhận thức giữa effort và performance.", "topic": "Mục 2.12.2. Expectancy."}, {"chapter_slug": "chuong-8", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Xung đột có thể:", "option_a": "Chỉ gây hại", "option_b": "Chỉ có lợi", "option_c": "Có thể chức năng hoặc phi chức năng", "option_d": "Luôn phải loại bỏ", "correct_option": "C", "explanation": "Xung đột có thể hỗ trợ hoặc cản trở tổ chức tùy loại, mức độ và cách quản trị.", "topic": "Mục 3.2–3.4."}, {"chapter_slug": "chuong-8", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Phương thức xử lý xung đột nhằm tìm giải pháp đáp ứng lợi ích quan trọng của cả hai bên là:", "option_a": "Collaborating", "option_b": "Avoiding", "option_c": "Competing", "option_d": "Accommodating", "correct_option": "A", "explanation": "Collaborating hướng đến giải pháp tích hợp và lợi ích đôi bên.", "topic": "Mục 3.12. Hợp tác."}, {"chapter_slug": "chuong-8", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Xung đột xảy ra giữa hai phòng ban được gọi là:", "option_a": "Intrapersonal", "option_b": "Intergroup", "option_c": "Interorganizational", "option_d": "Internal motivation", "correct_option": "B", "explanation": "Intergroup conflict là xung đột giữa các nhóm hoặc bộ phận.", "topic": "Mục 3.6. Các cấp độ xung đột."}, {"chapter_slug": "chuong-8", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một nhóm chuyên gia nhiều kinh nghiệm, có khả năng tự quản và động lực cao thường phù hợp hơn với:", "option_a": "Mức tự chủ lãnh đạo cao hơn", "option_b": "Kiểm soát từng bước chặt chẽ nhất", "option_c": "Luôn dùng phong cách độc đoán", "option_d": "Không được ra quyết định", "correct_option": "A", "explanation": "Phong cách tự do hoặc trao quyền có thể phù hợp hơn khi nhân viên giàu kinh nghiệm và có khả năng tự quản.", "topic": "Mục 1.9 và 1.13."}, {"chapter_slug": "chuong-8", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một nhân viên được tăng lương nhưng vẫn bất mãn sau khi biết đồng nghiệp có cùng công việc và kinh nghiệm thấp hơn lại nhận mức lương cao hơn. Lý thuyết giải thích phù hợp nhất là:", "option_a": "Equity Theory", "option_b": "Maslow", "option_c": "Reinforcement Theory", "option_d": "Path-Goal", "correct_option": "A", "explanation": "Sự bất mãn xuất hiện do so sánh tương quan input–outcome với người khác chứ không chỉ từ mức lương tuyệt đối.", "topic": "Mục 2.9. Lý thuyết công bằng."}, {"chapter_slug": "chuong-8", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Theo Herzberg, tăng lương có thể giảm bất mãn nhưng chưa chắc tạo động lực lâu dài vì:", "option_a": "Lương thường được xem là yếu tố duy trì", "option_b": "Lương không có giá trị", "option_c": "Mọi nhân viên chỉ muốn thăng chức", "option_d": "Herzberg cho rằng không cần trả lương", "correct_option": "A", "explanation": "Herzberg phân biệt yếu tố bối cảnh giúp giảm bất mãn với motivators gắn với nội dung công việc và sự phát triển.", "topic": "Mục 2.6. Lý thuyết Herzberg."}, {"chapter_slug": "chuong-8", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một nhân viên tin rằng dù làm tốt hay kém thì tiền thưởng cuối năm đều giống nhau. Theo Expectancy Theory, yếu tố yếu nhất là:", "option_a": "Mối liên hệ thành tích – kết quả", "option_b": "Nhu cầu sinh lý", "option_c": "Affiliation", "option_d": "Power Distance", "correct_option": "A", "explanation": "Nhân viên không tin performance tốt sẽ dẫn đến outcome khác biệt, tức instrumentality thấp.", "topic": "Mục 2.12.3. Instrumentality."}, {"chapter_slug": "chuong-8", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Hai phòng tranh giành cùng một ngân sách hạn chế. Nguyên nhân xung đột gần nhất là:", "option_a": "Nguồn lực khan hiếm", "option_b": "Quá nhiều nguồn lực", "option_c": "Không có sự phụ thuộc", "option_d": "Không có mục tiêu", "correct_option": "A", "explanation": "Cạnh tranh đối với một nguồn lực hữu hạn là nguyên nhân phổ biến của xung đột tổ chức.", "topic": "Mục 3.7.2. Nguồn lực khan hiếm."}, {"chapter_slug": "chuong-8", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một quản lý luôn sử dụng phong cách dân chủ kể cả khi xảy ra sự cố an toàn đòi hỏi quyết định ngay lập tức. Vấn đề chính là:", "option_a": "Không điều chỉnh phong cách theo tình huống", "option_b": "Dân chủ luôn sai", "option_c": "Độc đoán luôn tốt", "option_d": "Nhân viên có quá nhiều động lực", "correct_option": "A", "explanation": "Không có phong cách lãnh đạo hiệu quả nhất trong mọi hoàn cảnh. Tình huống khẩn cấp có thể yêu cầu quyết định trực tiếp và nhanh hơn.", "topic": "Mục 1.13. Cách tiếp cận tình huống."}, {"chapter_slug": "chuong-8", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một công ty thưởng rất cao cho nhân viên đạt mục tiêu nhưng nhân viên vẫn không nỗ lực vì cho rằng hệ thống và thiết bị hiện tại khiến họ không thể đạt chỉ tiêu. Theo Expectancy Theory, vấn đề chính là:", "option_a": "Expectancy thấp", "option_b": "Valence thấp", "option_c": "Instrumentality thấp", "option_d": "Equity quá cao", "correct_option": "A", "explanation": "Phần thưởng có thể hấp dẫn nhưng nếu nhân viên không tin nỗ lực sẽ dẫn đến thành tích thì động lực vẫn thấp.", "topic": "Mục 2.12.2. Expectancy."}, {"chapter_slug": "chuong-8", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp đặt mục tiêu bán hàng rất cao. Nhân viên đạt doanh số nhưng dùng cách gây áp lực khiến khách hàng mất niềm tin. Bài học từ Goal-Setting Theory là:", "option_a": "Mục tiêu phải được thiết kế cùng các tiêu chí chất lượng phù hợp", "option_b": "Không nên có mục tiêu", "option_c": "Mục tiêu càng cao càng tốt trong mọi trường hợp", "option_d": "Chỉ cần thưởng tiền", "correct_option": "A", "explanation": "Mục tiêu không phù hợp hoặc xung đột có thể khiến nhân viên tối ưu một chỉ số và bỏ qua những kết quả quan trọng khác.", "topic": "Mục 2.11. Lý thuyết thiết lập mục tiêu."}, {"chapter_slug": "chuong-8", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Hai trưởng phòng có tranh luận mạnh về chiến lược nhưng vẫn tôn trọng nhau, trao đổi dữ liệu và cuối cùng tạo ra phương án tốt hơn. Xung đột này gần nhất với:", "option_a": "Xung đột chức năng", "option_b": "Xung đột phi chức năng", "option_c": "Xung đột tình cảm phá hoại", "option_d": "Không phải xung đột", "correct_option": "A", "explanation": "Xung đột tạo ra phản biện và nâng cao chất lượng quyết định mà không làm hỏng quan hệ có thể mang tính chức năng.", "topic": "Mục 3.3. Xung đột chức năng."}, {"chapter_slug": "chuong-8", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một trưởng phòng luôn nhường mọi yêu cầu của phòng khác để tránh căng thẳng. Sau thời gian dài, nguồn lực của phòng mình thiếu nghiêm trọng. Vấn đề là:", "option_a": "Lạm dụng accommodating", "option_b": "Lạm dụng collaborating", "option_c": "Quá nhiều competing", "option_d": "Quá nhiều goal setting", "correct_option": "A", "explanation": "Nhường nhịn có thể hữu ích trong một số tình huống nhưng nếu sử dụng liên tục sẽ khiến lợi ích chính đáng của bên mình bị bỏ qua.", "topic": "Mục 3.15. Accommodating."}, {"chapter_slug": "chuong-8", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Nhà máy xảy ra sự cố có nguy cơ gây tai nạn. Quản lý lập tức ra lệnh dừng dây chuyền mà không tổ chức họp lấy ý kiến. Phong cách này phù hợp nhất với:", "option_a": "Độc đoán trong tình huống khẩn cấp", "option_b": "Laissez-faire", "option_c": "Không lãnh đạo", "option_d": "Luôn sai vì không dân chủ", "correct_option": "A", "explanation": "Khi an toàn đòi hỏi hành động nhanh và quyết đoán, phong cách chỉ đạo trực tiếp có thể phù hợp.", "topic": "Mục 1.7 và 1.13."}, {"chapter_slug": "chuong-8", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhóm R&D gồm các chuyên gia lâu năm được trưởng nhóm giao mục tiêu rồi tự quyết phương pháp thực hiện. Đây gần nhất với:", "option_a": "Lãnh đạo tự do/trao quyền", "option_b": "Lãnh đạo độc đoán", "option_c": "Cưỡng chế", "option_d": "Tập trung tuyệt đối", "correct_option": "A", "explanation": "Nhóm có chuyên môn và khả năng tự quản có thể được trao mức tự chủ cao.", "topic": "Mục 1.9. Lãnh đạo tự do."}, {"chapter_slug": "chuong-8", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một trưởng phòng không có chức vụ cao trong công ty nhưng mọi người thường tìm đến ông để hỏi vì ông có kiến thức kỹ thuật vượt trội. Nguồn quyền lực chủ yếu là:", "option_a": "Expert Power", "option_b": "Coercive Power", "option_c": "Legitimate Power", "option_d": "Reward Power", "correct_option": "A", "explanation": "Ảnh hưởng xuất phát từ kiến thức và năng lực chuyên môn là quyền lực chuyên môn.", "topic": "Mục 1.5.4. Expert Power."}, {"chapter_slug": "chuong-8", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một CEO truyền đạt tầm nhìn mới, khuyến khích nhân viên đặt câu hỏi về cách làm cũ và đầu tư vào phát triển từng cá nhân. Đây gần nhất với:", "option_a": "Transformational Leadership", "option_b": "Lãnh đạo giao dịch thuần túy", "option_c": "Laissez-faire", "option_d": "Coercive Leadership", "correct_option": "A", "explanation": "Truyền cảm hứng, kích thích trí tuệ và phát triển người theo là những đặc trưng của lãnh đạo chuyển đổi.", "topic": "Mục 1.17. Lãnh đạo chuyển đổi."}, {"chapter_slug": "chuong-8", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một trưởng phòng nói: “Nếu đạt 110% chỉ tiêu quý, mỗi người nhận thêm 10 triệu đồng.” Đây gần nhất với:", "option_a": "Lãnh đạo giao dịch", "option_b": "Lãnh đạo chuyển đổi duy nhất", "option_c": "Laissez-faire", "option_d": "Avoiding", "correct_option": "A", "explanation": "Nhà lãnh đạo đang thiết lập trao đổi trực tiếp giữa thành tích và phần thưởng.", "topic": "Mục 1.16. Lãnh đạo giao dịch."}, {"chapter_slug": "chuong-8", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên có lương tốt nhưng muốn được giao công việc thách thức hơn và được công nhận thành tích. Theo Maslow, nhu cầu nổi bật có thể liên quan đến:", "option_a": "Tôn trọng và tự hoàn thiện", "option_b": "Sinh lý duy nhất", "option_c": "Chỉ an toàn", "option_d": "Không có nhu cầu", "correct_option": "A", "explanation": "Công nhận liên quan đến esteem, còn phát triển và khai thác tiềm năng liên quan đến self-actualization.", "topic": "Mục 2.4. Maslow."}, {"chapter_slug": "chuong-8", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên phàn nàn văn phòng nóng và thiết bị thường xuyên hỏng. Công ty sửa điều hòa và máy móc, nhân viên hết bất mãn nhưng chưa làm việc nhiệt tình hơn. Herzberg giải thích rằng:", "option_a": "Yếu tố duy trì đã được cải thiện nhưng motivators chưa chắc được tạo ra", "option_b": "Công ty phải giảm lương", "option_c": "Điều kiện làm việc là motivator mạnh nhất", "option_d": "Herzberg cho rằng thiết bị không quan trọng", "correct_option": "A", "explanation": "Cải thiện hygiene factors có thể loại bỏ bất mãn nhưng chưa chắc tạo hài lòng và động lực tích cực lâu dài.", "topic": "Mục 2.6. Herzberg."}, {"chapter_slug": "chuong-8", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhân viên thích nhận các dự án khó, muốn tự chịu trách nhiệm và luôn yêu cầu phản hồi về kết quả. Theo McClelland, người này có khả năng có:", "option_a": "Nhu cầu thành tựu cao", "option_b": "Nhu cầu liên kết cao nhất chắc chắn", "option_c": "Không có động lực", "option_d": "Nhu cầu an toàn duy nhất", "correct_option": "A", "explanation": "Người có nhu cầu thành tựu cao thường thích mục tiêu thách thức hợp lý, trách nhiệm và phản hồi.", "topic": "Mục 2.7. McClelland."}, {"chapter_slug": "chuong-8", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Công ty tuyên dương công khai nhân viên mỗi khi họ nhận được phản hồi xuất sắc từ khách hàng. Mục tiêu là làm hành vi phục vụ tốt lặp lại. Đây là:", "option_a": "Củng cố tích cực", "option_b": "Hình phạt", "option_c": "Extinction", "option_d": "Accommodating", "correct_option": "A", "explanation": "Một hậu quả tích cực được cung cấp sau hành vi mong muốn để làm tăng khả năng hành vi lặp lại.", "topic": "Mục 2.8.2. Củng cố tích cực."}, {"chapter_slug": "chuong-8", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Hai nhân viên làm cùng công việc. Người có kinh nghiệm hơn phát hiện người mới vào nhận lương cao hơn mình và bắt đầu giảm nỗ lực. Lý thuyết phù hợp nhất là:", "option_a": "Equity Theory", "option_b": "Maslow duy nhất", "option_c": "Path-Goal", "option_d": "Fiedler", "correct_option": "A", "explanation": "Nhân viên đang so sánh tương quan đóng góp – kết quả giữa mình và người tham chiếu.", "topic": "Mục 2.9. Equity Theory."}, {"chapter_slug": "chuong-8", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Nhân viên rất thích phần thưởng cuối năm nhưng tin rằng trưởng phòng thưởng theo cảm tính, không liên quan thành tích. Theo Expectancy Theory, vấn đề là:", "option_a": "Instrumentality thấp", "option_b": "Valence thấp", "option_c": "Expectancy chắc chắn bằng 0", "option_d": "Không có nhu cầu", "correct_option": "A", "explanation": "Phần thưởng có giá trị nhưng nhân viên không tin performance tốt sẽ dẫn đến phần thưởng.", "topic": "Mục 2.12.3. Instrumentality."}, {"chapter_slug": "chuong-8", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Công ty tặng chuyến du lịch cho người đạt thành tích cao nhưng một nhân viên không thích du lịch và muốn được học chứng chỉ nghề nghiệp. Theo Expectancy Theory:", "option_a": "Valence của phần thưởng đối với nhân viên đó thấp", "option_b": "Expectancy chắc chắn thấp", "option_c": "Equity luôn thấp", "option_d": "Nhân viên không có động lực nào", "correct_option": "A", "explanation": "Outcome không có giá trị cao đối với cá nhân nên khả năng tạo động viên bị giảm.", "topic": "Mục 2.12.4. Valence."}, {"chapter_slug": "chuong-8", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Phòng kinh doanh muốn nhận mọi đơn hàng, trong khi sản xuất muốn hạn chế đơn để bảo đảm tiến độ. Đây chủ yếu là:", "option_a": "Xung đột mục tiêu", "option_b": "Xung đột intrapersonal", "option_c": "Không phải xung đột", "option_d": "Xung đột hành vi duy nhất", "correct_option": "A", "explanation": "Hai bộ phận đang theo đuổi các kết quả ưu tiên khác nhau.", "topic": "Mục 3.5.1. Xung đột mục tiêu."}, {"chapter_slug": "chuong-8", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Hai nhân viên tranh luận về phương pháp phân tích dữ liệu nhưng không có mâu thuẫn cá nhân. Đây gần nhất với:", "option_a": "Xung đột nhận thức", "option_b": "Xung đột tình cảm", "option_c": "Xung đột intrapersonal", "option_d": "Không có xung đột", "correct_option": "A", "explanation": "Sự khác nhau nằm ở ý tưởng và cách hiểu về phương pháp.", "topic": "Mục 3.5.2. Xung đột nhận thức."}, {"chapter_slug": "chuong-8", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Hai phòng cùng cần một nhân viên IT duy nhất cho hai dự án quan trọng và không thể thống nhất ai được ưu tiên. Nguyên nhân xung đột là:", "option_a": "Nguồn lực khan hiếm", "option_b": "Quá nhiều nguồn lực", "option_c": "Không có sự phụ thuộc", "option_d": "Chỉ do văn hóa dân tộc", "correct_option": "A", "explanation": "Hai nhóm cạnh tranh một nguồn lực hữu hạn.", "topic": "Mục 3.7.2. Nguồn lực khan hiếm."}, {"chapter_slug": "chuong-8", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Hai phòng đang xung đột về một vấn đề nhỏ. Một bên nhận thấy chi phí tranh luận lớn hơn lợi ích nên tạm thời không theo đuổi vấn đề. Đây gần nhất với:", "option_a": "Avoiding", "option_b": "Competing", "option_c": "Collaborating", "option_d": "Transformational Leadership", "correct_option": "A", "explanation": "Né tránh có thể phù hợp khi vấn đề có tầm quan trọng thấp và việc đối đầu không tạo đủ giá trị.", "topic": "Mục 3.14. Avoiding."}, {"chapter_slug": "chuong-8", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Hai bộ phận có lợi ích đều rất quan trọng. Họ cùng phân tích nhu cầu thật sự và thiết kế một phương án mới giúp cả hai đạt mục tiêu. Đây là:", "option_a": "Collaborating", "option_b": "Competing", "option_c": "Avoiding", "option_d": "Accommodating", "correct_option": "A", "explanation": "Hợp tác nhằm tìm giải pháp tích hợp đáp ứng mối quan tâm quan trọng của cả hai bên.", "topic": "Mục 3.12. Collaborating."}, {"chapter_slug": "chuong-8", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Hai bên có quyền lực tương đương, thời gian gấp và thống nhất mỗi bên nhượng một phần yêu cầu. Đây là:", "option_a": "Compromising", "option_b": "Collaborating hoàn toàn", "option_c": "Avoiding", "option_d": "Competing", "correct_option": "A", "explanation": "Thỏa hiệp tạo giải pháp trung gian trong đó mỗi bên được và mất một phần.", "topic": "Mục 3.13. Compromising."}, {"chapter_slug": "chuong-8", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trong một cuộc thương lượng, hai bên ban đầu tranh giành ngân sách cố định. Sau đó họ tìm cách chia sẻ hệ thống và giảm tổng chi phí để cả hai cùng có lợi. Cách tiếp cận sau gần nhất với:", "option_a": "Thương lượng tích hợp", "option_b": "Thương lượng phân phối thuần túy", "option_c": "Competing duy nhất", "option_d": "Avoiding", "correct_option": "A", "explanation": "Hai bên đang tìm cách tạo thêm giá trị thay vì chỉ tranh giành một nguồn lực cố định.", "topic": "Mục 3.17. Thương lượng tích hợp."}, {"chapter_slug": "chuong-8", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một quản lý thấy hai nhân viên tranh cãi, lập tức yêu cầu “đừng cãi nữa” mà không tìm nguyên nhân. Vài tuần sau xung đột tái diễn mạnh hơn. Bài học phù hợp nhất là:", "option_a": "Quản trị xung đột phải tìm nguyên nhân chứ không chỉ dập biểu hiện", "option_b": "Mọi xung đột phải bị cấm", "option_c": "Luôn nên competing", "option_d": "Chỉ cần thay đổi tiền lương", "correct_option": "A", "explanation": "Ngăn hành vi tranh luận tạm thời không xử lý được mục tiêu, quyền hạn, nguồn lực hay vấn đề quan hệ đang tạo ra xung đột.", "topic": "Mục 3.18. Quy trình quản trị xung đột."}, {"chapter_slug": "chuong-9", "question_no": 1, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Kiểm tra trong quản trị được hiểu phù hợp nhất là:", "option_a": "Chỉ tìm kiếm sai phạm của nhân viên", "option_b": "Theo dõi kết quả, so sánh với tiêu chuẩn và điều chỉnh khi cần thiết", "option_c": "Chỉ kiểm tra tài chính cuối năm", "option_d": "Chỉ giám sát công việc của cấp dưới", "correct_option": "B", "explanation": "Kiểm tra là một quá trình quản trị gồm đo lường, so sánh, xác định sai lệch và thực hiện hành động điều chỉnh nhằm bảo đảm mục tiêu.", "topic": "Mục 1.1. Khái niệm kiểm tra."}, {"chapter_slug": "chuong-9", "question_no": 2, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Mối quan hệ đúng giữa hoạch định và kiểm tra là:", "option_a": "Hai chức năng hoàn toàn độc lập", "option_b": "Kiểm tra phải thực hiện trước hoạch định", "option_c": "Hoạch định tạo tiêu chuẩn cho kiểm tra, còn kiểm tra tạo phản hồi cho hoạch định", "option_d": "Khi có hoạch định thì không cần kiểm tra", "correct_option": "C", "explanation": "Mục tiêu và kế hoạch cung cấp cơ sở so sánh; kết quả kiểm tra lại cung cấp thông tin để điều chỉnh kế hoạch.", "topic": "Mục 1.3. Hoạch định và kiểm tra."}, {"chapter_slug": "chuong-9", "question_no": 3, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Bước đầu tiên của tiến trình kiểm tra là:", "option_a": "Xác định mục tiêu và tiêu chuẩn", "option_b": "Xử phạt người thực hiện", "option_c": "Thay đổi cơ cấu", "option_d": "Đánh giá nhân sự", "correct_option": "A", "explanation": "Không thể kiểm tra nếu chưa có một tiêu chuẩn để làm cơ sở đánh giá.", "topic": "Mục 3.2. Xác định mục tiêu và tiêu chuẩn."}, {"chapter_slug": "chuong-9", "question_no": 4, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Việc kiểm tra nguyên liệu trước khi đưa vào sản xuất là:", "option_a": "Kiểm tra tác nghiệp sau", "option_b": "Kiểm tra chiến lược", "option_c": "Kiểm tra đồng thời", "option_d": "Kiểm tra trước", "correct_option": "D", "explanation": "Hoạt động diễn ra trước quá trình sản xuất và nhằm phòng ngừa lỗi đầu vào.", "topic": "Mục 4.1. Kiểm tra trước."}, {"chapter_slug": "chuong-9", "question_no": 5, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Kiểm tra được thực hiện trong khi công việc đang diễn ra được gọi là:", "option_a": "Kiểm tra sau", "option_b": "Kiểm tra đồng thời", "option_c": "Kiểm tra chiến lược", "option_d": "Kiểm tra tài chính", "correct_option": "B", "explanation": "Concurrent control theo dõi hoạt động khi nó đang diễn ra để phát hiện và điều chỉnh sai lệch sớm.", "topic": "Mục 4.2. Kiểm tra đồng thời."}, {"chapter_slug": "chuong-9", "question_no": 6, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Báo cáo kết quả kinh doanh cuối quý là ví dụ gần nhất của:", "option_a": "Kiểm tra trước", "option_b": "Screening control", "option_c": "Kiểm tra sau", "option_d": "Steering control", "correct_option": "C", "explanation": "Kết quả được đánh giá sau khi kỳ hoạt động đã hoàn thành.", "topic": "Mục 4.5. Kiểm tra sau."}, {"chapter_slug": "chuong-9", "question_no": 7, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Loại kiểm tra tập trung vào chiến lược và mục tiêu dài hạn là:", "option_a": "Kiểm tra chiến lược", "option_b": "Kiểm tra tác nghiệp", "option_c": "Kiểm tra tồn kho", "option_d": "Kiểm tra ca làm việc", "correct_option": "A", "explanation": "Strategic control đánh giá định hướng dài hạn và việc thực hiện chiến lược của toàn tổ chức.", "topic": "Mục 5.1. Kiểm tra chiến lược."}, {"chapter_slug": "chuong-9", "question_no": 8, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Loại kiểm tra liên quan trực tiếp đến hoạt động hằng ngày là:", "option_a": "Kiểm tra chiến lược", "option_b": "Hoạch định dài hạn", "option_c": "Kiểm tra môi trường", "option_d": "Kiểm tra tác nghiệp", "correct_option": "D", "explanation": "Operational control tập trung vào những công việc cụ thể, thường xuyên và ngắn hạn.", "topic": "Mục 5.3. Kiểm tra tác nghiệp."}, {"chapter_slug": "chuong-9", "question_no": 9, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Thông tin kiểm tra có chất lượng cần:", "option_a": "Càng nhiều càng tốt", "option_b": "Chính xác và kịp thời", "option_c": "Chỉ do cấp cao tạo ra", "option_d": "Chỉ là thông tin tài chính", "correct_option": "B", "explanation": "Thông tin sai hoặc đến quá muộn có thể dẫn tới đánh giá và điều chỉnh không phù hợp.", "topic": "Mục 2.4 và 2.5."}, {"chapter_slug": "chuong-9", "question_no": 10, "section_label": "PHẦN I. 10 CÂU TRẮC NGHIỆM CƠ BẢN", "question_text": "Mục đích của hành động điều chỉnh là:", "option_a": "Tăng số lượng báo cáo", "option_b": "Tìm người chịu lỗi bằng mọi giá", "option_c": "Đưa hoạt động trở lại phù hợp với mục tiêu hoặc điều chỉnh mục tiêu khi cần", "option_d": "Loại bỏ mọi quyền tự chủ", "correct_option": "C", "explanation": "Hành động điều chỉnh nhằm xử lý nguyên nhân sai lệch và bảo đảm tổ chức tiếp tục hướng tới mục tiêu.", "topic": "Mục 3.8. Hành động điều chỉnh."}, {"chapter_slug": "chuong-9", "question_no": 11, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một doanh nghiệp kiểm tra hàng trăm chỉ số nhưng nhà quản trị không còn thời gian xem những chỉ số quan trọng. Nguyên tắc nào chưa được thực hiện tốt?", "option_a": "Tập trung vào những điểm quan trọng", "option_b": "Tăng tối đa số lượng kiểm tra", "option_c": "Tập trung hóa quyền lực", "option_d": "Chuyên môn hóa", "correct_option": "A", "explanation": "Cơ chế kiểm tra phải tập trung vào những khu vực then chốt thay vì đo mọi thứ với cùng mức độ.", "topic": "Mục 2.6. Tập trung vào điểm quan trọng."}, {"chapter_slug": "chuong-9", "question_no": 12, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Doanh nghiệp cho phép chi phí thực tế dao động ±3% so với ngân sách mà chưa cần can thiệp. Khoảng ±3% được gọi là:", "option_a": "Tiêu chuẩn chiến lược", "option_b": "Feedback", "option_c": "Screening control", "option_d": "Biên độ chấp nhận được", "correct_option": "D", "explanation": "Đây là phạm vi sai lệch mà tổ chức xem là bình thường và chưa cần điều chỉnh đặc biệt.", "topic": "Mục 3.6. Biên độ chấp nhận được."}, {"chapter_slug": "chuong-9", "question_no": 13, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một quản lý chỉ yêu cầu báo cáo khi doanh số lệch quá 10% so với kế hoạch. Đây là ứng dụng của:", "option_a": "Kiểm tra cơ học", "option_b": "Kiểm tra theo ngoại lệ", "option_c": "Lãnh đạo tự do", "option_d": "Phân quyền tuyệt đối", "correct_option": "B", "explanation": "Management by exception tập trung sự chú ý vào những sai lệch quan trọng.", "topic": "Mục 2.7. Kiểm tra theo ngoại lệ."}, {"chapter_slug": "chuong-9", "question_no": 14, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Điểm khác nhau quan trọng giữa kiểm tra trước và kiểm tra sau là:", "option_a": "Kiểm tra sau luôn tốt hơn", "option_b": "Kiểm tra trước chỉ dùng trong tài chính", "option_c": "Kiểm tra trước hướng đến phòng ngừa, kiểm tra sau hướng nhiều đến đánh giá và phản hồi", "option_d": "Hai hình thức hoàn toàn giống nhau", "correct_option": "C", "explanation": "Feedforward tác động trước công việc để phòng ngừa, trong khi feedback/postaction sử dụng kết quả đã xảy ra để đánh giá và học hỏi.", "topic": "Mục 4.1 và 4.5."}, {"chapter_slug": "chuong-9", "question_no": 15, "section_label": "PHẦN II. 5 CÂU TRẮC NGHIỆM MỨC KHÁ", "question_text": "Một hệ thống kiểm tra có chi phí rất lớn trong khi rủi ro cần kiểm soát rất nhỏ. Nguyên tắc bị vi phạm rõ nhất là:", "option_a": "Nguyên tắc kinh tế", "option_b": "Nguyên tắc thống nhất chỉ huy", "option_c": "Nguyên tắc phân quyền", "option_d": "Nguyên tắc chuyên môn hóa", "correct_option": "A", "explanation": "Lợi ích của hoạt động kiểm tra phải tương xứng với chi phí thực hiện.", "topic": "Mục 2.9. Nguyên tắc kinh tế."}, {"chapter_slug": "chuong-9", "question_no": 16, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Doanh số của một phòng thấp hơn mục tiêu 20%. Giám đốc lập tức thay trưởng phòng mà chưa xem xét việc sản phẩm chính đã thiếu hàng trong hai tháng. Sai lầm lớn nhất là:", "option_a": "Đặt tiêu chuẩn rõ", "option_b": "Thực hiện kiểm tra sau", "option_c": "Điều chỉnh trước khi phân tích nguyên nhân sai lệch", "option_d": "Kiểm tra quá ít chỉ tiêu", "correct_option": "C", "explanation": "Sai lệch có thể xuất phát từ nhiều nguyên nhân. Thay đổi nhân sự trước khi xác định nguyên nhân có thể dẫn tới biện pháp không phù hợp.", "topic": "Mục 3.7–3.8."}, {"chapter_slug": "chuong-9", "question_no": 17, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Nhân viên chăm sóc khách hàng được đánh giá chủ yếu dựa trên số cuộc gọi xử lý mỗi ngày. Họ bắt đầu kết thúc cuộc gọi thật nhanh khiến khiếu nại tăng. Vấn đề cốt lõi là:", "option_a": "Nhân viên không cần kiểm tra", "option_b": "Tiêu chuẩn kiểm tra đã thúc đẩy hành vi không phù hợp với mục tiêu thật", "option_c": "Cần tăng chỉ tiêu cuộc gọi", "option_d": "Kiểm tra trước không được sử dụng", "correct_option": "B", "explanation": "Nếu chỉ số dễ đo không phản ánh mục tiêu thật, nhân viên có thể tối ưu chỉ số nhưng làm giảm chất lượng chung.", "topic": "Mục 1.6 và 2.2–2.3."}, {"chapter_slug": "chuong-9", "question_no": 18, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp đạt toàn bộ mục tiêu doanh số và lợi nhuận hiện tại nhưng công nghệ mới đang nhanh chóng làm sản phẩm của doanh nghiệp lỗi thời. Cấp kiểm tra nào đặc biệt cần được chú trọng?", "option_a": "Chỉ kiểm tra ca làm việc", "option_b": "Chỉ kiểm tra tồn kho", "option_c": "Chỉ kiểm tra ngân sách", "option_d": "Kiểm tra chiến lược", "correct_option": "D", "explanation": "Kết quả hiện tại tốt không bảo đảm chiến lược còn phù hợp với thay đổi môi trường và công nghệ.", "topic": "Mục 5.1. Kiểm tra chiến lược."}, {"chapter_slug": "chuong-9", "question_no": 19, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một tổ chức xây dựng hàng chục thủ tục phê duyệt để hạn chế mọi sai sót nhỏ. Sau một thời gian, nhân viên không dám tự quyết và tốc độ phục vụ giảm mạnh. Vấn đề là:", "option_a": "Hệ thống kiểm tra quá mức và làm giảm quyền tự chủ", "option_b": "Kiểm tra chưa đủ mạnh", "option_c": "Tổ chức cần thêm cấp phê duyệt", "option_d": "Mọi hình thức kiểm tra đều gây hại", "correct_option": "A", "explanation": "Kiểm tra quá mức có thể tạo thủ tục, giảm sáng kiến và làm nhân viên cảm thấy không có quyền kiểm soát công việc.", "topic": "Mục 1.6 và 2.14."}, {"chapter_slug": "chuong-9", "question_no": 20, "section_label": "PHẦN III. 5 CÂU TRẮC NGHIỆM MỨC KHÓ", "question_text": "Một doanh nghiệp luôn điều chỉnh hoạt động để đáp ứng mục tiêu nhưng chưa bao giờ đặt câu hỏi liệu mục tiêu đó còn phù hợp với thị trường hay không. Hạn chế là:", "option_a": "Có quá nhiều feedback", "option_b": "Đo lường quá chính xác", "option_c": "Chỉ sửa hoạt động mà chưa xem xét lại chính mục tiêu và kế hoạch", "option_d": "Dùng quá nhiều kiểm tra chiến lược", "correct_option": "C", "explanation": "Kiểm tra quản trị hiện đại cần tạo phản hồi không chỉ về cách thực hiện mà cả về tính phù hợp của mục tiêu và chiến lược.", "topic": "Mục 1.5.7, 3.8 và 5.1."}, {"chapter_slug": "chuong-9", "question_no": 21, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty thực phẩm kiểm tra chất lượng nguyên liệu ngay khi nhà cung cấp giao tới và từ chối lô hàng không đạt chuẩn. Đây là:", "option_a": "Kiểm tra sau", "option_b": "Kiểm tra trước", "option_c": "Kiểm tra chiến lược", "option_d": "Kiểm tra ngân sách", "correct_option": "B", "explanation": "Nguyên liệu được kiểm tra trước khi tham gia quá trình sản xuất nhằm phòng ngừa lỗi.", "topic": "Mục 4.1. Kiểm tra trước."}, {"chapter_slug": "chuong-9", "question_no": 22, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Quản lý nhà máy theo dõi màn hình sản xuất theo thời gian thực và giảm tốc dây chuyền khi tỷ lệ lỗi tăng. Đây là:", "option_a": "Kiểm tra sau", "option_b": "Kiểm tra chiến lược", "option_c": "Kiểm tra ngân sách", "option_d": "Kiểm tra đồng thời", "correct_option": "D", "explanation": "Việc đo lường và điều chỉnh diễn ra khi quá trình sản xuất vẫn đang hoạt động.", "topic": "Mục 4.2. Kiểm tra đồng thời."}, {"chapter_slug": "chuong-9", "question_no": 23, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Sau khi hoàn thành một dự án, doanh nghiệp tổ chức cuộc họp để đánh giá chi phí, tiến độ, sai sót và bài học cho dự án tiếp theo. Đây là:", "option_a": "Kiểm tra sau", "option_b": "Kiểm tra trước", "option_c": "Screening control", "option_d": "Kiểm tra tác nghiệp trước", "correct_option": "A", "explanation": "Hoạt động diễn ra sau khi dự án kết thúc và nhằm đánh giá, tạo phản hồi cho tương lai.", "topic": "Mục 4.5. Kiểm tra sau."}, {"chapter_slug": "chuong-9", "question_no": 24, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trong công trình xây dựng, phần móng phải được nghiệm thu đạt chuẩn trước khi nhà thầu được phép thi công tầng tiếp theo. Đây là:", "option_a": "Feedback control thuần túy", "option_b": "Kiểm tra tài chính", "option_c": "Screening/Go-No-Go Control", "option_d": "Kiểm tra chiến lược", "correct_option": "C", "explanation": "Đây là điểm kiểm soát giữa các công đoạn; chỉ khi giai đoạn trước đạt yêu cầu mới được tiếp tục.", "topic": "Mục 4.4. Kiểm tra sàng lọc."}, {"chapter_slug": "chuong-9", "question_no": 25, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trưởng phòng bán hàng theo dõi số hợp đồng từng tuần và trực tiếp hướng dẫn nhân viên điều chỉnh cách tiếp cận khách hàng trong khi tháng bán hàng vẫn chưa kết thúc. Đây là:", "option_a": "Kiểm tra sau", "option_b": "Steering control", "option_c": "Kiểm tra chiến lược", "option_d": "Kiểm tra tồn kho", "correct_option": "B", "explanation": "Nhà quản trị theo dõi công việc đang diễn ra và đưa ra hướng dẫn để điều chỉnh trước khi kỳ làm việc kết thúc.", "topic": "Mục 4.3. Steering Control."}, {"chapter_slug": "chuong-9", "question_no": 26, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Ban lãnh đạo theo dõi việc thị phần liên tục giảm và xem xét liệu chiến lược giá hiện tại có còn phù hợp hay không. Đây chủ yếu là:", "option_a": "Kiểm tra chiến lược", "option_b": "Kiểm tra tồn kho", "option_c": "Kiểm tra tác nghiệp", "option_d": "Kiểm tra giờ làm", "correct_option": "A", "explanation": "Ban lãnh đạo đang đánh giá một lựa chọn chiến lược và vị thế cạnh tranh của toàn doanh nghiệp.", "topic": "Mục 5.1. Kiểm tra chiến lược."}, {"chapter_slug": "chuong-9", "question_no": 27, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Trưởng bộ phận marketing so sánh chi phí quảng cáo quý này với ngân sách và mục tiêu doanh số của bộ phận. Đây gần nhất với:", "option_a": "Kiểm tra trước", "option_b": "Kiểm tra chiến lược toàn công ty", "option_c": "Kiểm tra cá nhân", "option_d": "Kiểm tra quản trị/chiến thuật", "correct_option": "D", "explanation": "Hoạt động tập trung vào việc sử dụng nguồn lực và thực hiện kế hoạch của một bộ phận.", "topic": "Mục 5.2. Kiểm tra quản trị/chiến thuật."}, {"chapter_slug": "chuong-9", "question_no": 28, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Tổ trưởng kiểm tra số lượng sản phẩm hoàn thành trong từng ca và tỷ lệ lỗi của công nhân. Đây là:", "option_a": "Kiểm tra chiến lược", "option_b": "Kiểm tra chiến thuật dài hạn", "option_c": "Kiểm tra tác nghiệp", "option_d": "Kiểm tra môi trường", "correct_option": "C", "explanation": "Sản lượng và lỗi của từng ca là những hoạt động hằng ngày thuộc operational control.", "topic": "Mục 5.3. Kiểm tra tác nghiệp."}, {"chapter_slug": "chuong-9", "question_no": 29, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Công ty đặt ngân sách quảng cáo tháng là 500 triệu đồng nhưng thực tế chi 540 triệu. Nhà quản trị trước tiên nên:", "option_a": "Sa thải trưởng phòng", "option_b": "Phân tích nguyên nhân và ý nghĩa của chênh lệch 40 triệu đồng", "option_c": "Cắt toàn bộ quảng cáo", "option_d": "Hạ tiêu chuẩn xuống 540 triệu", "correct_option": "B", "explanation": "Chênh lệch không tự nói lên nguyên nhân. Chi phí tăng có thể hợp lý hoặc không hợp lý tùy kết quả và bối cảnh.", "topic": "Mục 3.7 và 5.6."}, {"chapter_slug": "chuong-9", "question_no": 30, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhà máy đặt tiêu chuẩn tỷ lệ lỗi dưới 2%. Tháng này tỷ lệ lỗi là 1,4%. Cách xử lý hợp lý nhất trước tiên là:", "option_a": "Ghi nhận kết quả đạt chuẩn và tiếp tục theo dõi", "option_b": "Lập tức thay toàn bộ quy trình", "option_c": "Tăng mức lỗi cho phép", "option_d": "Dừng sản xuất", "correct_option": "A", "explanation": "Kết quả đang nằm trong tiêu chuẩn; không có lý do để thực hiện biện pháp điều chỉnh lớn chỉ vì muốn can thiệp.", "topic": "Mục 3.5–3.6."}, {"chapter_slug": "chuong-9", "question_no": 31, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty yêu cầu CEO phải duyệt mọi khoản chi vượt ngân sách dù chỉ 10.000 đồng. Mỗi ngày CEO nhận hàng trăm yêu cầu nhỏ. Giải pháp phù hợp nhất là:", "option_a": "CEO kiểm tra chi tiết hơn nữa", "option_b": "Bỏ hoàn toàn ngân sách", "option_c": "Tăng số lượng biểu mẫu", "option_d": "Xây dựng biên độ và áp dụng nguyên tắc kiểm tra theo ngoại lệ", "correct_option": "D", "explanation": "Nhà quản trị cấp cao nên tập trung vào những sai lệch quan trọng thay vì mọi chênh lệch nhỏ.", "topic": "Mục 2.7 và 3.6."}, {"chapter_slug": "chuong-9", "question_no": 32, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một phần mềm tự gửi cảnh báo khi tồn kho giảm xuống dưới mức tối thiểu và tự tạo đề nghị đặt hàng. Đây gần nhất với:", "option_a": "Lãnh đạo dân chủ", "option_b": "Cơ chế kiểm tra tự điều chỉnh", "option_c": "Kiểm tra chiến lược", "option_d": "Tổ chức không chính thức", "correct_option": "B", "explanation": "Hệ thống tự theo dõi trạng thái, phát hiện sai lệch và kích hoạt phản ứng dựa trên quy tắc đã thiết kế.", "topic": "Mục 5.11. Cybernetic Control."}, {"chapter_slug": "chuong-9", "question_no": 33, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một nhóm kỹ sư tự theo dõi tiến độ, chất lượng và tự điều chỉnh nhiệm vụ mà không cần quản lý kiểm tra từng ngày. Đây là biểu hiện của:", "option_a": "Kiểm tra cưỡng chế", "option_b": "Kiểm tra chiến lược", "option_c": "Tự kiểm tra", "option_d": "Không có kiểm tra", "correct_option": "C", "explanation": "Nhóm vẫn sử dụng mục tiêu và tiêu chuẩn nhưng chủ động theo dõi, điều chỉnh công việc của chính mình.", "topic": "Mục 5.12. Tự kiểm tra."}, {"chapter_slug": "chuong-9", "question_no": 34, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một hãng hàng không kiểm tra kỹ thuật máy bay trước chuyến bay, theo dõi hệ thống khi đang bay và đánh giá dữ liệu sau chuyến. Đây là:", "option_a": "Hệ thống kiểm tra kết hợp", "option_b": "Chỉ kiểm tra sau", "option_c": "Chỉ kiểm tra đồng thời", "option_d": "Chỉ kiểm tra chiến lược", "correct_option": "A", "explanation": "Tổ chức đang kết hợp kiểm tra trước, đồng thời và sau để quản trị rủi ro toàn diện hơn.", "topic": "Mục 4.6. Hệ thống kiểm tra kết hợp."}, {"chapter_slug": "chuong-9", "question_no": 35, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Nhà quản trị phát hiện doanh số thấp hơn mục tiêu nhưng thị trường toàn ngành cũng giảm 30%. Điều này cho thấy trước khi điều chỉnh cần:", "option_a": "Chỉ nhìn chênh lệch tuyệt đối", "option_b": "Trừng phạt bộ phận bán hàng", "option_c": "Luôn giữ nguyên mục tiêu", "option_d": "Phân tích nguyên nhân và bối cảnh của sai lệch", "correct_option": "D", "explanation": "Sai lệch có thể đến từ yếu tố môi trường chứ không nhất thiết là do thực hiện kém.", "topic": "Mục 3.7. Phân tích sai lệch và nguyên nhân."}, {"chapter_slug": "chuong-9", "question_no": 36, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Doanh nghiệp đặt KPI giao hàng đúng hạn 98%. Nhân viên đạt KPI bằng cách từ chối nhận những đơn hàng khó. Hệ thống kiểm tra đang gặp vấn đề gì?", "option_a": "Kiểm tra quá ít lần", "option_b": "Chỉ số chưa phản ánh đầy đủ mục tiêu và tạo hành vi đối phó", "option_c": "Không có tiêu chuẩn", "option_d": "Không có nhân viên kiểm tra", "correct_option": "B", "explanation": "Chỉ số đúng hạn được tối ưu nhưng làm tổn hại mục tiêu phục vụ khách hàng. Đây là hệ quả của tiêu chuẩn thiết kế chưa phù hợp.", "topic": "Mục 1.6 và 2.2."}, {"chapter_slug": "chuong-9", "question_no": 37, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty vẫn dùng chỉ tiêu số fax gửi đi để đánh giá hiệu suất dù toàn bộ khách hàng đã chuyển sang nền tảng số. Nguyên tắc nào bị vi phạm?", "option_a": "Tính linh hoạt của hệ thống kiểm tra", "option_b": "Kiểm tra theo ngoại lệ", "option_c": "Thống nhất chỉ huy", "option_d": "Chuyên môn hóa", "correct_option": "A", "explanation": "Tiêu chuẩn không được cập nhật khi công nghệ và phương thức kinh doanh thay đổi.", "topic": "Mục 2.8. Nguyên tắc linh hoạt."}, {"chapter_slug": "chuong-9", "question_no": 38, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty bỏ 100 triệu đồng mỗi tháng để kiểm tra một loại sai sót có tổng thiệt hại trung bình chỉ khoảng 2 triệu đồng và không có rủi ro an toàn hay pháp lý đáng kể. Nhà quản trị nên xem xét lại:", "option_a": "Mức độ chuyên môn hóa", "option_b": "Văn hóa tổ chức", "option_c": "Tính kinh tế của cơ chế kiểm tra", "option_d": "Phong cách lãnh đạo", "correct_option": "C", "explanation": "Chi phí kiểm tra đang cao hơn rất nhiều so với lợi ích kinh tế và mức độ rủi ro cần kiểm soát.", "topic": "Mục 2.9. Nguyên tắc kinh tế."}, {"chapter_slug": "chuong-9", "question_no": 39, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Một công ty đạt chỉ tiêu lợi nhuận năm nay nhưng tỷ lệ khách hàng quay lại và chất lượng sản phẩm cùng giảm mạnh. Kết luận phù hợp nhất là:", "option_a": "Chỉ cần lợi nhuận nên không có vấn đề", "option_b": "Tổ chức cần hệ thống chỉ tiêu kiểm tra cân bằng hơn", "option_c": "Không nên kiểm tra lợi nhuận", "option_d": "Chỉ cần tăng mục tiêu lợi nhuận", "correct_option": "B", "explanation": "Một chỉ số tài chính không phản ánh đầy đủ sức khỏe dài hạn của tổ chức. Cần kết hợp chất lượng, khách hàng và các chỉ tiêu liên quan khác.", "topic": "Mục 2.2, 5.5, 5.7 và 5.10."}, {"chapter_slug": "chuong-9", "question_no": 40, "section_label": "PHẦN IV. 20 CÂU TRẮC NGHIỆM TÌNH HUỐNG THỰC TẾ", "question_text": "Cuối năm, công ty không chỉ so sánh kết quả với kế hoạch mà còn nhận thấy chiến lược ban đầu dựa trên giả định thị trường không còn đúng và quyết định xây dựng chiến lược mới. Điều này thể hiện:", "option_a": "Kiểm tra chỉ nhằm tìm lỗi", "option_b": "Kiểm tra làm thay chức năng tổ chức", "option_c": "Phản hồi của kiểm tra được sử dụng để điều chỉnh hoạch định và chiến lược", "option_d": "Công ty không có cơ chế kiểm tra", "correct_option": "C", "explanation": "Một chức năng quan trọng của kiểm tra là đưa thông tin thực tế trở lại quá trình hoạch định để tổ chức có thể học hỏi và thích nghi.", "topic": "Mục 1.3, 1.5.7, 3.9 và 5.1."}]$questions$::jsonb) as x(chapter_slug text,question_no int,section_label text,question_text text,option_a text,option_b text,option_c text,option_d text,correct_option text,explanation text,topic text))
insert into questions(chapter_id,question_no,section_label,question_text,option_a,option_b,option_c,option_d,correct_option,explanation,topic)
select c.id,j.question_no,j.section_label,j.question_text,j.option_a,j.option_b,j.option_c,j.option_d,j.correct_option,j.explanation,j.topic from j join chapters c on c.slug=j.chapter_slug
on conflict(chapter_id,question_no) do update set section_label=excluded.section_label,question_text=excluded.question_text,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_option=excluded.correct_option,explanation=excluded.explanation,topic=excluded.topic;

create or replace function norm_text(v text) returns text language sql immutable as $$ select lower(trim(regexp_replace(coalesce(v,''),'\s+',' ','g'))) $$;

create or replace function start_or_resume_attempt(p_chapter_slug text,p_full_name text,p_class_name text,p_browser_id text,p_session_token text)
returns table(attempt_id uuid,attempt_number int,monitoring_required boolean) language plpgsql security definer set search_path=public as $$
declare ch uuid;ik text;a attempts%rowtype;n int;
begin
 if length(trim(p_full_name))<2 or length(trim(p_class_name))<1 then raise exception 'Thiếu họ tên hoặc lớp';end if;
 select id into ch from chapters where slug=p_chapter_slug and is_active=true;if ch is null then raise exception 'Chương chưa khả dụng';end if;
 ik:=encode(digest(norm_text(p_full_name)||'|'||norm_text(p_class_name),'sha256'),'hex');
 select * into a from attempts where chapter_id=ch and identity_key=ik and status='active' order by started_at desc limit 1;
 if a.id is null then
   select count(*)+1 into n from attempts where chapter_id=ch and identity_key=ik and status='submitted';
   begin
     insert into attempts(chapter_id,full_name,class_name,identity_key,browser_id,attempt_number,monitoring_required,active_session_token,active_session_seen_at) values(ch,trim(p_full_name),trim(p_class_name),ik,p_browser_id,n,n>=3,p_session_token,now()) returning * into a;
   exception when unique_violation then select * into a from attempts where chapter_id=ch and identity_key=ik and status='active' order by started_at desc limit 1;end;
 end if;
 return query select a.id,a.attempt_number,a.monitoring_required;
end$$;
revoke all on function start_or_resume_attempt(text,text,text,text,text) from public;grant execute on function start_or_resume_attempt(text,text,text,text,text) to anon,authenticated;

create or replace function get_quiz_questions(p_chapter_slug text)
returns table(question_id uuid,question_no int,section_label text,question_text text,option_a text,option_b text,option_c text,option_d text) language sql security definer set search_path=public as $$ select q.id,q.question_no,q.section_label,q.question_text,q.option_a,q.option_b,q.option_c,q.option_d from questions q join chapters c on c.id=q.chapter_id where c.slug=p_chapter_slug and c.is_active=true order by q.question_no $$;
revoke all on function get_quiz_questions(text) from public;grant execute on function get_quiz_questions(text) to anon,authenticated;

create or replace function get_saved_answers(p_attempt_id uuid) returns table(question_id uuid,selected_option text) language sql security definer set search_path=public as $$ select question_id,selected_option from attempt_answers where attempt_id=p_attempt_id $$;
revoke all on function get_saved_answers(uuid) from public;grant execute on function get_saved_answers(uuid) to anon,authenticated;

create or replace function save_answer(p_attempt_id uuid,p_question_id uuid,p_selected_option text) returns void language plpgsql security definer set search_path=public as $$
begin
 if p_selected_option not in('A','B','C','D') then raise exception 'Đáp án không hợp lệ';end if;
 if not exists(select 1 from attempts a join questions q on q.chapter_id=a.chapter_id where a.id=p_attempt_id and a.status='active' and q.id=p_question_id) then raise exception 'Lượt làm hoặc câu hỏi không hợp lệ';end if;
 insert into attempt_answers(attempt_id,question_id,selected_option,is_correct,updated_at) values(p_attempt_id,p_question_id,p_selected_option,null,now()) on conflict(attempt_id,question_id) do update set selected_option=excluded.selected_option,is_correct=null,updated_at=now();
end$$;
revoke all on function save_answer(uuid,uuid,text) from public;grant execute on function save_answer(uuid,uuid,text) to anon,authenticated;

create or replace function log_monitor_event(p_attempt_id uuid,p_session_token text,p_event_type text,p_event_detail jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public as $$
begin if exists(select 1 from attempts where id=p_attempt_id and status='active' and monitoring_required=true) then insert into monitor_events(attempt_id,session_token,event_type,event_detail) values(p_attempt_id,p_session_token,left(p_event_type,80),coalesce(p_event_detail,'{}'::jsonb));end if;end$$;
revoke all on function log_monitor_event(uuid,text,text,jsonb) from public;grant execute on function log_monitor_event(uuid,text,text,jsonb) to anon,authenticated;

create or replace function touch_attempt_session(p_attempt_id uuid,p_session_token text) returns void language plpgsql security definer set search_path=public as $$
declare old_token text;old_seen timestamptz;mon boolean;already boolean;begin
 select active_session_token,active_session_seen_at,monitoring_required,concurrent_detected into old_token,old_seen,mon,already from attempts where id=p_attempt_id and status='active' for update;if not found then return;end if;
 if mon and old_token is not null and old_token<>p_session_token and old_seen>now()-interval '30 seconds' and not already then insert into monitor_events(attempt_id,session_token,event_type,event_detail) values(p_attempt_id,p_session_token,'concurrent_session',jsonb_build_object('previous_session',old_token));update attempts set concurrent_detected=true where id=p_attempt_id;end if;
 update attempts set active_session_token=p_session_token,active_session_seen_at=now() where id=p_attempt_id;end$$;
revoke all on function touch_attempt_session(uuid,text) from public;grant execute on function touch_attempt_session(uuid,text) to anon,authenticated;

create or replace function submit_attempt(p_attempt_id uuid,p_session_token text)
returns table(score int,total int,percent numeric,correct_count int,wrong_count int,attempt_number int,monitoring_required boolean,review jsonb,monitor_summary jsonb,monitor_log jsonb) language plpgsql security definer set search_path=public as $$
declare a attempts%rowtype;qtotal int;acount int;sc int;rev jsonb;mon jsonb;mlog jsonb;begin
 select * into a from attempts where id=p_attempt_id for update;if a.id is null then raise exception 'Không tìm thấy lượt làm';end if;
 if a.status='active' then
   select count(*) into qtotal from questions where chapter_id=a.chapter_id;select count(*) into acount from attempt_answers where attempt_id=a.id;if acount<>qtotal then raise exception 'Bạn chưa trả lời đủ tất cả câu hỏi';end if;
   if a.monitoring_required and a.active_session_token is not null and a.active_session_token<>p_session_token and a.active_session_seen_at>now()-interval '30 seconds' and not a.concurrent_detected then insert into monitor_events(attempt_id,session_token,event_type,event_detail) values(a.id,p_session_token,'concurrent_session',jsonb_build_object('previous_session',a.active_session_token));update attempts set concurrent_detected=true where id=a.id;end if;
   update attempt_answers aa set is_correct=(aa.selected_option=q.correct_option) from questions q where aa.attempt_id=a.id and q.id=aa.question_id;
   select count(*) into sc from attempt_answers where attempt_id=a.id and is_correct=true;
   update attempts set status='submitted',submitted_at=now(),score=sc,total_questions=qtotal,percent=round(sc*100.0/qtotal,2),active_session_seen_at=null where id=a.id returning * into a;
 else qtotal:=a.total_questions;sc:=a.score;end if;
 select jsonb_agg(jsonb_build_object('question_no',q.question_no,'section_label',q.section_label,'question_text',q.question_text,'selected_option',aa.selected_option,'correct_option',q.correct_option,'options',jsonb_build_object('A',q.option_a,'B',q.option_b,'C',q.option_c,'D',q.option_d),'explanation',q.explanation,'topic',q.topic,'is_correct',aa.is_correct) order by q.question_no) into rev from attempt_answers aa join questions q on q.id=aa.question_id where aa.attempt_id=a.id;
 select jsonb_build_object('tab_hidden',count(*) filter(where event_type='tab_hidden'),'window_blur',count(*) filter(where event_type='window_blur'),'fullscreen_exit',count(*) filter(where event_type='fullscreen_exit'),'page_leave_resume',count(*) filter(where event_type='page_leave_resume'),'concurrent_session',count(*) filter(where event_type='concurrent_session'),'total_away_seconds',coalesce(sum(case when event_type='tab_visible' then coalesce((event_detail->>'away_seconds')::int,0) else 0 end),0)) into mon from monitor_events where attempt_id=a.id;
 select coalesce(jsonb_agg(jsonb_build_object('event_type',event_type,'event_detail',event_detail,'occurred_at',occurred_at) order by occurred_at),'[]'::jsonb) into mlog from monitor_events where attempt_id=a.id;
 return query select sc,qtotal,round(sc*100.0/qtotal,2),sc,qtotal-sc,a.attempt_number,a.monitoring_required,rev,mon,mlog;end$$;
revoke all on function submit_attempt(uuid,text) from public;grant execute on function submit_attempt(uuid,text) to anon,authenticated;

create or replace function is_teacher() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from teacher_profiles where user_id=auth.uid()) $$;
revoke all on function is_teacher() from public;grant execute on function is_teacher() to authenticated;

create or replace function admin_attempts()
returns table(attempt_id uuid,full_name text,class_name text,chapter_title text,attempt_number int,score int,total_questions int,percent numeric,monitoring_required boolean,monitor_event_count bigint,flagged boolean,submitted_at timestamptz,duration_seconds int) language plpgsql security definer set search_path=public as $$
begin if not is_teacher() then raise exception 'Không có quyền quản trị';end if;return query select a.id,a.full_name,a.class_name,c.title,a.attempt_number,a.score,a.total_questions,a.percent,a.monitoring_required,(select count(*) from monitor_events m where m.attempt_id=a.id),((select count(*) from monitor_events m where m.attempt_id=a.id and m.event_type in('tab_hidden','window_blur','fullscreen_exit','page_leave_resume','concurrent_session'))>0),a.submitted_at,greatest(0,extract(epoch from(a.submitted_at-a.started_at))::int) from attempts a join chapters c on c.id=a.chapter_id where a.status='submitted' order by a.submitted_at desc;end$$;
revoke all on function admin_attempts() from public;grant execute on function admin_attempts() to authenticated;

create or replace function admin_attempt_detail(p_attempt_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare a attempts%rowtype;c chapters%rowtype;rev jsonb;ev jsonb;begin if not is_teacher() then raise exception 'Không có quyền quản trị';end if;select * into a from attempts where id=p_attempt_id;if a.id is null then raise exception 'Không tìm thấy bài làm';end if;select * into c from chapters where id=a.chapter_id;select coalesce(jsonb_agg(jsonb_build_object('question_no',q.question_no,'selected_option',aa.selected_option,'correct_option',q.correct_option,'is_correct',aa.is_correct) order by q.question_no),'[]'::jsonb) into rev from attempt_answers aa join questions q on q.id=aa.question_id where aa.attempt_id=a.id;select coalesce(jsonb_agg(jsonb_build_object('event_type',m.event_type,'event_detail',m.event_detail,'occurred_at',m.occurred_at) order by m.occurred_at),'[]'::jsonb) into ev from monitor_events m where m.attempt_id=a.id;return jsonb_build_object('full_name',a.full_name,'class_name',a.class_name,'chapter_title',c.title,'attempt_number',a.attempt_number,'score',a.score,'total_questions',a.total_questions,'percent',a.percent,'duration_seconds',greatest(0,extract(epoch from(a.submitted_at-a.started_at))::int),'review',rev,'monitor_log',ev);end$$;
revoke all on function admin_attempt_detail(uuid) from public;grant execute on function admin_attempt_detail(uuid) to authenticated;

